    { r = {"CLAUDIUS"}, t = "You told us of some suit. What is’t, Laertes?" },
    { r = {"CLAUDIUS"}, t = "You cannot speak of reason to the Dane," },
    { r = {"CLAUDIUS"}, t = "And lose your voice. What wouldst thou beg, Laertes," },
    { r = {"CLAUDIUS"}, t = "That shall not be my offer, not thy asking?" },
    { r = {"CLAUDIUS"}, t = "The head is not more native to the heart," },
    { r = {"CLAUDIUS"}, t = "The hand more instrumental to the mouth," },
    { r = {"CLAUDIUS"}, t = "Than is the throne of Denmark to thy father." },
    { r = {"CLAUDIUS"}, t = "What wouldst thou have, Laertes?" },
    { r = {"LAERTES"}, t = "Dread my lord," },
    { r = {"LAERTES"}, t = "Your leave and favour to return to France," },
    { r = {"LAERTES"}, t = "From whence though willingly I came to Denmark" },
    { r = {"LAERTES"}, t = "To show my duty in your coronation;" },
    { r = {"LAERTES"}, t = "Yet now I must confess, that duty done," },
    { r = {"LAERTES"}, t = "My thoughts and wishes bend again toward France," },
    { r = {"LAERTES"}, t = "And bow them to your gracious leave and pardon." },
    { r = {"CLAUDIUS"}, t = "Have you your father’s leave? What says Polonius?" },
    { r = {"POLONIUS"}, t = "He hath, my lord, wrung from me my slow leave" },
    { r = {"POLONIUS"}, t = "By laboursome petition; and at last" },
    { r = {"POLONIUS"}, t = "Upon his will I seal’d my hard consent." },
    { r = {"POLONIUS"}, t = "I do beseech you give him leave to go." },
    { r = {"CLAUDIUS"}, t = "Take thy fair hour, Laertes; time be thine," },
    { r = {"CLAUDIUS"}, t = "And thy best graces spend it at thy will!" },
    { r = {"CLAUDIUS"}, t = "But now, my cousin Hamlet, and my son" },
    { r = {"HAMLET"}, t = "A little more than kin, and less than kind.", d = "Aside" },
    { r = {"CLAUDIUS"}, t = "How is it that the clouds still hang on you?" },
    { r = {"HAMLET"}, t = "Not so, my lord, I am too much i’ the sun." },
    { r = {"GERTRUDE"}, t = "Good Hamlet, cast thy nighted colour off," },
    { r = {"GERTRUDE"}, t = "And let thine eye look like a friend on Denmark." },
    { r = {"GERTRUDE"}, t = "Do not for ever with thy vailed lids" },
    { r = {"GERTRUDE"}, t = "Seek for thy noble father in the dust." },
    { r = {"GERTRUDE"}, t = "Thou know’st ’tis common, all that lives must die," },
    { r = {"GERTRUDE"}, t = "Passing through nature to eternity." },
    { r = {"HAMLET"}, t = "Ay, madam, it is common." },
    { r = {"GERTRUDE"}, t = "If it be," },
    { r = {"GERTRUDE"}, t = "Why seems it so particular with thee?" },
    { r = {"HAMLET"}, t = "Seems, madam! Nay, it is; I know not seems." },
    { r = {"HAMLET"}, t = "’Tis not alone my inky cloak, good mother," },
    { r = {"HAMLET"}, t = "Nor customary suits of solemn black," },
    { r = {"HAMLET"}, t = "Nor windy suspiration of forc’d breath," },
    { r = {"HAMLET"}, t = "No, nor the fruitful river in the eye," },
    { r = {"HAMLET"}, t = "Nor the dejected haviour of the visage," },
    { r = {"HAMLET"}, t = "Together with all forms, moods, shows of grief," },
    { r = {"HAMLET"}, t = "That can denote me truly. These indeed seem," },
    { r = {"HAMLET"}, t = "For they are actions that a man might play;" },
    { r = {"HAMLET"}, t = "But I have that within which passeth show;" },
    { r = {"HAMLET"}, t = "These but the trappings and the suits of woe." },
    { r = {"CLAUDIUS"}, t = "’Tis sweet and commendable in your nature, Hamlet," },
    { r = {"CLAUDIUS"}, t = "To give these mourning duties to your father;" },
    { r = {"CLAUDIUS"}, t = "But you must know, your father lost a father," },
    { r = {"CLAUDIUS"}, t = "That father lost, lost his, and the survivor bound" },
    { r = {"CLAUDIUS"}, t = "In filial obligation, for some term" },
    { r = {"CLAUDIUS"}, t = "To do obsequious sorrow. But to persevere" },
    { r = {"CLAUDIUS"}, t = "In obstinate condolement is a course" },
    { r = {"CLAUDIUS"}, t = "Of impious stubbornness. ’Tis unmanly grief," },
    { r = {"CLAUDIUS"}, t = "It shows a will most incorrect to heaven," },
    { r = {"CLAUDIUS"}, t = "A heart unfortified, a mind impatient," },
    { r = {"CLAUDIUS"}, t = "An understanding simple and unschool’d;" },
    { r = {"CLAUDIUS"}, t = "For what we know must be, and is as common" },
    { r = {"CLAUDIUS"}, t = "As any the most vulgar thing to sense," },
    { r = {"CLAUDIUS"}, t = "Why should we in our peevish opposition" },
    { r = {"CLAUDIUS"}, t = "Take it to heart? Fie, ’tis a fault to heaven," },
    { r = {"CLAUDIUS"}, t = "A fault against the dead, a fault to nature," },
    { r = {"CLAUDIUS"}, t = "To reason most absurd, whose common theme" },
    { r = {"CLAUDIUS"}, t = "Is death of fathers, and who still hath cried," },
    { r = {"CLAUDIUS"}, t = "From the first corse till he that died today," },
    { r = {"CLAUDIUS"}, t = "‘This must be so.’ We pray you throw to earth" },
    { r = {"CLAUDIUS"}, t = "This unprevailing woe, and think of us" },
    { r = {"CLAUDIUS"}, t = "As of a father; for let the world take note" },
    { r = {"CLAUDIUS"}, t = "You are the most immediate to our throne," },
    { r = {"CLAUDIUS"}, t = "And with no less nobility of love" },
    { r = {"CLAUDIUS"}, t = "Than that which dearest father bears his son" },
    { r = {"CLAUDIUS"}, t = "Do I impart toward you. For your intent" },
    { r = {"CLAUDIUS"}, t = "In going back to school in Wittenberg," },
    { r = {"CLAUDIUS"}, t = "It is most retrograde to our desire:" },
    { r = {"CLAUDIUS"}, t = "And we beseech you bend you to remain" },
    { r = {"CLAUDIUS"}, t = "Here in the cheer and comfort of our eye," },
    { r = {"CLAUDIUS"}, t = "Our chiefest courtier, cousin, and our son." },
    { r = {"GERTRUDE"}, t = "Let not thy mother lose her prayers, Hamlet." },
    { r = {"GERTRUDE"}, t = "I pray thee stay with us; go not to Wittenberg." },
    { r = {"HAMLET"}, t = "I shall in all my best obey you, madam." },
    { r = {"CLAUDIUS"}, t = "Why, ’tis a loving and a fair reply." },
    { r = {"CLAUDIUS"}, t = "Be as ourself in Denmark. Madam, come;" },
    { r = {"CLAUDIUS"}, t = "This gentle and unforc’d accord of Hamlet" },
    { r = {"CLAUDIUS"}, t = "Sits smiling to my heart; in grace whereof," },
    { r = {"CLAUDIUS"}, t = "No jocund health that Denmark drinks today" },
    { r = {"CLAUDIUS"}, t = "But the great cannon to the clouds shall tell," },
    { r = {"CLAUDIUS"}, t = "And the King’s rouse the heaven shall bruit again," },
    { r = {"CLAUDIUS"}, t = "Re-speaking earthly thunder. Come away." },
    { d = "Exeunt all but Hamlet" },
    { r = {"HAMLET"}, t = "O that this too too solid flesh would melt," },
    { r = {"HAMLET"}, t = "Thaw, and resolve itself into a dew!" },
    { r = {"HAMLET"}, t = "Or that the Everlasting had not fix’d" },
    { r = {"HAMLET"}, t = "His canon ’gainst self-slaughter. O God! O God!" },
    { r = {"HAMLET"}, t = "How weary, stale, flat, and unprofitable" },
    { r = {"HAMLET"}, t = "Seem to me all the uses of this world!" },
    { r = {"HAMLET"}, t = "Fie on’t! Oh fie! ’tis an unweeded garden" },
    { r = {"HAMLET"}, t = "That grows to seed; things rank and gross in nature" },
    { r = {"HAMLET"}, t = "Possess it merely. That it should come to this!" },
    { r = {"HAMLET"}, t = "But two months dead—nay, not so much, not two:" },
    { r = {"HAMLET"}, t = "So excellent a king; that was to this" },
    { r = {"HAMLET"}, t = "Hyperion to a satyr; so loving to my mother," },
    { r = {"HAMLET"}, t = "That he might not beteem the winds of heaven" },
    { r = {"HAMLET"}, t = "Visit her face too roughly. Heaven and earth!" },
    { r = {"HAMLET"}, t = "Must I remember? Why, she would hang on him" },
    { r = {"HAMLET"}, t = "As if increase of appetite had grown" },
    { r = {"HAMLET"}, t = "By what it fed on; and yet, within a month—" },
    { r = {"HAMLET"}, t = "Let me not think on’t—Frailty, thy name is woman!" },
    { r = {"HAMLET"}, t = "A little month, or ere those shoes were old" },
    { r = {"HAMLET"}, t = "With which she followed my poor father’s body" },
    { r = {"HAMLET"}, t = "Like Niobe, all tears.—Why she, even she—" },
    { r = {"HAMLET"}, t = "O God! A beast that wants discourse of reason" },
    { r = {"HAMLET"}, t = "Would have mourn’d longer,—married with mine uncle," },
    { r = {"HAMLET"}, t = "My father’s brother; but no more like my father" },
    { r = {"HAMLET"}, t = "Than I to Hercules. Within a month," },
    { r = {"HAMLET"}, t = "Ere yet the salt of most unrighteous tears" },
    { r = {"HAMLET"}, t = "Had left the flushing in her galled eyes," },
    { r = {"HAMLET"}, t = "She married. O most wicked speed, to post" },
    { r = {"HAMLET"}, t = "With such dexterity to incestuous sheets!" },
    { r = {"HAMLET"}, t = "It is not, nor it cannot come to good." },
    { r = {"HAMLET"}, t = "But break, my heart, for I must hold my tongue." },
    { d = "Enter Horatio, Marcellus and Barnardo" },
    { r = {"HORATIO"}, t = "Hail to your lordship!" },
    { r = {"HAMLET"}, t = "I am glad to see you well:" },
    { r = {"HAMLET"}, t = "Horatio, or I do forget myself." },
    { r = {"HORATIO"}, t = "The same, my lord," },
    { r = {"HORATIO"}, t = "And your poor servant ever." },
    { r = {"HAMLET"}, t = "Sir, my good friend;" },
    { r = {"HAMLET"}, t = "I’ll change that name with you:" },
    { r = {"HAMLET"}, t = "And what make you from Wittenberg, Horatio?—" },
    { r = {"HAMLET"}, t = "Marcellus?" },
    { r = {"MARCELLUS"}, t = "My good lord." },
    { r = {"HAMLET"}, t = "I am very glad to see you.—Good even, sir.—" },
    { r = {"HAMLET"}, t = "But what, in faith, make you from Wittenberg?" },
    { r = {"HORATIO"}, t = "A truant disposition, good my lord." },
    { r = {"HAMLET"}, t = "I would not hear your enemy say so;" },
    { r = {"HAMLET"}, t = "Nor shall you do my ear that violence," },
    { r = {"HAMLET"}, t = "To make it truster of your own report" },
    { r = {"HAMLET"}, t = "Against yourself. I know you are no truant." },
    { r = {"HAMLET"}, t = "But what is your affair in Elsinore?" },
    { r = {"HAMLET"}, t = "We’ll teach you to drink deep ere you depart." },
    { r = {"HORATIO"}, t = "My lord, I came to see your father’s funeral." },
    { r = {"HAMLET"}, t = "I prithee do not mock me, fellow-student." },
    { r = {"HAMLET"}, t = "I think it was to see my mother’s wedding." },
    { r = {"HORATIO"}, t = "Indeed, my lord, it follow’d hard upon." },
    { r = {"HAMLET"}, t = "Thrift, thrift, Horatio! The funeral bak’d meats" },
    { r = {"HAMLET"}, t = "Did coldly furnish forth the marriage tables." },
    { r = {"HAMLET"}, t = "Would I had met my dearest foe in heaven" },
    { r = {"HAMLET"}, t = "Or ever I had seen that day, Horatio." },
    { r = {"HAMLET"}, t = "My father,—methinks I see my father." },
    { r = {"HORATIO"}, t = "Where, my lord?" },
    { r = {"HAMLET"}, t = "In my mind’s eye, Horatio." },
    { r = {"HORATIO"}, t = "I saw him once; he was a goodly king." },
    { r = {"HAMLET"}, t = "He was a man, take him for all in all," },
    { r = {"HAMLET"}, t = "I shall not look upon his like again." },
    { r = {"HORATIO"}, t = "My lord, I think I saw him yesternight." },
    { r = {"HAMLET"}, t = "Saw? Who?" },
    { r = {"HORATIO"}, t = "My lord, the King your father." },
    { r = {"HAMLET"}, t = "The King my father!" },
    { r = {"HORATIO"}, t = "Season your admiration for a while" },
    { r = {"HORATIO"}, t = "With an attent ear, till I may deliver" },
    { r = {"HORATIO"}, t = "Upon the witness of these gentlemen" },
    { r = {"HORATIO"}, t = "This marvel to you." },
    { r = {"HAMLET"}, t = "For God’s love let me hear." },
    { r = {"HORATIO"}, t = "Two nights together had these gentlemen," },
    { r = {"HORATIO"}, t = "Marcellus and Barnardo, on their watch" },
    { r = {"HORATIO"}, t = "In the dead waste and middle of the night," },
    { r = {"HORATIO"}, t = "Been thus encounter’d. A figure like your father," },
    { r = {"HORATIO"}, t = "Armed at point exactly, cap-à-pie," },
    { r = {"HORATIO"}, t = "Appears before them, and with solemn march" },
    { r = {"HORATIO"}, t = "Goes slow and stately by them: thrice he walk’d" },
    { r = {"HORATIO"}, t = "By their oppress’d and fear-surprised eyes," },
    { r = {"HORATIO"}, t = "Within his truncheon’s length; whilst they, distill’d" },
    { r = {"HORATIO"}, t = "Almost to jelly with the act of fear," },
    { r = {"HORATIO"}, t = "Stand dumb, and speak not to him. This to me" },
    { r = {"HORATIO"}, t = "In dreadful secrecy impart they did," },
    { r = {"HORATIO"}, t = "And I with them the third night kept the watch," },
    { r = {"HORATIO"}, t = "Where, as they had deliver’d, both in time," },
    { r = {"HORATIO"}, t = "Form of the thing, each word made true and good," },
    { r = {"HORATIO"}, t = "The apparition comes. I knew your father;" },
    { r = {"HORATIO"}, t = "These hands are not more like." },
    { r = {"HAMLET"}, t = "But where was this?" },
    { r = {"MARCELLUS"}, t = "My lord, upon the platform where we watch." },
    { r = {"HAMLET"}, t = "Did you not speak to it?" },
    { r = {"HORATIO"}, t = "My lord, I did;" },
    { r = {"HORATIO"}, t = "But answer made it none: yet once methought" },
    { r = {"HORATIO"}, t = "It lifted up it head, and did address" },
    { r = {"HORATIO"}, t = "Itself to motion, like as it would speak." },
    { r = {"HORATIO"}, t = "But even then the morning cock crew loud," },
    { r = {"HORATIO"}, t = "And at the sound it shrunk in haste away," },
    { r = {"HORATIO"}, t = "And vanish’d from our sight." },
    { r = {"HAMLET"}, t = "’Tis very strange." },
    { r = {"HORATIO"}, t = "As I do live, my honour’d lord, ’tis true;" },
    { r = {"HORATIO"}, t = "And we did think it writ down in our duty" },
    { r = {"HORATIO"}, t = "To let you know of it." },
    { r = {"HAMLET"}, t = "Indeed, indeed, sirs, but this troubles me." },
    { r = {"HAMLET"}, t = "Hold you the watch tonight?" },
    { r = {"HAMLET"}, t = "MARCELLUS and BARNARDO." },
    { r = {"HAMLET"}, t = "We do, my lord." },
    { r = {"HAMLET"}, t = "Arm’d, say you?" },
    { r = {"MARCELLUS", "BARNARDO"}, t = "Arm’d, my lord." },
    { r = {"HAMLET"}, t = "From top to toe?" },
    { r = {"MARCELLUS", "BARNARDO"}, t = "My lord, from head to foot." },
    { r = {"HAMLET"}, t = "Then saw you not his face?" },
    { r = {"HORATIO"}, t = "O yes, my lord, he wore his beaver up." },
    { r = {"HAMLET"}, t = "What, look’d he frowningly?" },
    { r = {"HORATIO"}, t = "A countenance more in sorrow than in anger." },
    { r = {"HAMLET"}, t = "Pale, or red?" },
    { r = {"HORATIO"}, t = "Nay, very pale." },
    { r = {"HAMLET"}, t = "And fix’d his eyes upon you?" },
    { r = {"HORATIO"}, t = "Most constantly." },
    { r = {"HAMLET"}, t = "I would I had been there." },
    { r = {"HORATIO"}, t = "It would have much amaz’d you." },
    { r = {"HAMLET"}, t = "Very like, very like. Stay’d it long?" },
    { r = {"HORATIO"}, t = "While one with moderate haste might tell a hundred." },
    { r = {"HORATIO"}, t = "MARCELLUS and BARNARDO." },
    { r = {"HORATIO"}, t = "Longer, longer." },
    { r = {"HORATIO"}, t = "Not when I saw’t." },
    { r = {"HAMLET"}, t = "His beard was grizzled, no?" },
    { r = {"HORATIO"}, t = "It was, as I have seen it in his life," },
    { r = {"HORATIO"}, t = "A sable silver’d." },
    { r = {"HAMLET"}, t = "I will watch tonight;" },
    { r = {"HAMLET"}, t = "Perchance ’twill walk again." },
    { r = {"HORATIO"}, t = "I warrant you it will." },
    { r = {"HAMLET"}, t = "If it assume my noble father’s person," },
    { r = {"HAMLET"}, t = "I’ll speak to it, though hell itself should gape" },
    { r = {"HAMLET"}, t = "And bid me hold my peace. I pray you all," },
    { r = {"HAMLET"}, t = "If you have hitherto conceal’d this sight," },
    { r = {"HAMLET"}, t = "Let it be tenable in your silence still;" },
    { r = {"HAMLET"}, t = "And whatsoever else shall hap tonight," },
    { r = {"HAMLET"}, t = "Give it an understanding, but no tongue." },
    { r = {"HAMLET"}, t = "I will requite your loves. So, fare ye well." },
    { r = {"HAMLET"}, t = "Upon the platform ’twixt eleven and twelve," },
    { r = {"HAMLET"}, t = "I’ll visit you." },
    { r = {"ALL"}, t = "Our duty to your honour." },
    { r = {"HAMLET"}, t = "Your loves, as mine to you: farewell." },
    { d = "Exeunt Horatio, Marcellus and Barnardo" },
    { r = {"HAMLET"}, t = "My father’s spirit in arms! All is not well;" },
    { r = {"HAMLET"}, t = "I doubt some foul play: would the night were come!" },
    { r = {"HAMLET"}, t = "Till then sit still, my soul: foul deeds will rise," },
    { r = {"HAMLET"}, t = "Though all the earth o’erwhelm them, to men’s eyes." },
    { d = "Exit" },
    { d = "Act 1, Scene 3. A room in Polonius’s house.", h = true },
    { d = "Enter Laertes and Ophelia" },
    { r = {"LAERTES"}, t = "My necessaries are embark’d. Farewell." },
    { r = {"LAERTES"}, t = "And, sister, as the winds give benefit" },
    { r = {"LAERTES"}, t = "And convoy is assistant, do not sleep," },
    { r = {"LAERTES"}, t = "But let me hear from you." },
    { r = {"OPHELIA"}, t = "Do you doubt that?" },
    { r = {"LAERTES"}, t = "For Hamlet, and the trifling of his favour," },
    { r = {"LAERTES"}, t = "Hold it a fashion and a toy in blood;" },
    { r = {"LAERTES"}, t = "A violet in the youth of primy nature," },
    { r = {"LAERTES"}, t = "Forward, not permanent, sweet, not lasting;" },
    { r = {"LAERTES"}, t = "The perfume and suppliance of a minute;" },
    { r = {"LAERTES"}, t = "No more." },
    { r = {"OPHELIA"}, t = "No more but so?" },
    { r = {"LAERTES"}, t = "Think it no more." },
    { r = {"LAERTES"}, t = "For nature crescent does not grow alone" },
    { r = {"LAERTES"}, t = "In thews and bulk; but as this temple waxes," },
    { r = {"LAERTES"}, t = "The inward service of the mind and soul" },
    { r = {"LAERTES"}, t = "Grows wide withal. Perhaps he loves you now," },
    { r = {"LAERTES"}, t = "And now no soil nor cautel doth besmirch" },
    { r = {"LAERTES"}, t = "The virtue of his will; but you must fear," },
    { r = {"LAERTES"}, t = "His greatness weigh’d, his will is not his own;" },
    { r = {"LAERTES"}, t = "For he himself is subject to his birth:" },
    { r = {"LAERTES"}, t = "He may not, as unvalu’d persons do," },
    { r = {"LAERTES"}, t = "Carve for himself; for on his choice depends" },
    { r = {"LAERTES"}, t = "The sanctity and health of this whole state;" },
    { r = {"LAERTES"}, t = "And therefore must his choice be circumscrib’d" },
    { r = {"LAERTES"}, t = "Unto the voice and yielding of that body" },
    { r = {"LAERTES"}, t = "Whereof he is the head. Then if he says he loves you," },
    { r = {"LAERTES"}, t = "It fits your wisdom so far to believe it" },
    { r = {"LAERTES"}, t = "As he in his particular act and place" },
    { r = {"LAERTES"}, t = "May give his saying deed; which is no further" },
    { r = {"LAERTES"}, t = "Than the main voice of Denmark goes withal." },
    { r = {"LAERTES"}, t = "Then weigh what loss your honour may sustain" },
    { r = {"LAERTES"}, t = "If with too credent ear you list his songs," },
    { r = {"LAERTES"}, t = "Or lose your heart, or your chaste treasure open" },
    { r = {"LAERTES"}, t = "To his unmaster’d importunity." },
    { r = {"LAERTES"}, t = "Fear it, Ophelia, fear it, my dear sister;" },
    { r = {"LAERTES"}, t = "And keep you in the rear of your affection," },
    { r = {"LAERTES"}, t = "Out of the shot and danger of desire." },
    { r = {"LAERTES"}, t = "The chariest maid is prodigal enough" },
    { r = {"LAERTES"}, t = "If she unmask her beauty to the moon." },
    { r = {"LAERTES"}, t = "Virtue itself ’scapes not calumnious strokes:" },
    { r = {"LAERTES"}, t = "The canker galls the infants of the spring" },
    { r = {"LAERTES"}, t = "Too oft before their buttons be disclos’d," },
    { r = {"LAERTES"}, t = "And in the morn and liquid dew of youth" },
    { r = {"LAERTES"}, t = "Contagious blastments are most imminent." },
    { r = {"LAERTES"}, t = "Be wary then, best safety lies in fear." },
    { r = {"LAERTES"}, t = "Youth to itself rebels, though none else near." },
    { r = {"OPHELIA"}, t = "I shall th’effect of this good lesson keep" },
    { r = {"OPHELIA"}, t = "As watchman to my heart. But good my brother," },
    { r = {"OPHELIA"}, t = "Do not as some ungracious pastors do," },
    { r = {"OPHELIA"}, t = "Show me the steep and thorny way to heaven;" },
    { r = {"OPHELIA"}, t = "Whilst like a puff’d and reckless libertine" },
    { r = {"OPHELIA"}, t = "Himself the primrose path of dalliance treads," },
    { r = {"OPHELIA"}, t = "And recks not his own rede." },
    { r = {"LAERTES"}, t = "O, fear me not." },
    { r = {"LAERTES"}, t = "I stay too long. But here my father comes." },
    { d = "Enter Polonius" },
    { r = {"LAERTES"}, t = "A double blessing is a double grace;" },
    { r = {"LAERTES"}, t = "Occasion smiles upon a second leave." },
    { r = {"POLONIUS"}, t = "Yet here, Laertes? Aboard, aboard, for shame." },
    { r = {"POLONIUS"}, t = "The wind sits in the shoulder of your sail," },
    { r = {"POLONIUS"}, t = "And you are stay’d for. There, my blessing with you." },
    { d = "Laying his hand on Laertes’s head" },
    { r = {"POLONIUS"}, t = "And these few precepts in thy memory" },
    { r = {"POLONIUS"}, t = "Look thou character. Give thy thoughts no tongue," },
    { r = {"POLONIUS"}, t = "Nor any unproportion’d thought his act." },
    { r = {"POLONIUS"}, t = "Be thou familiar, but by no means vulgar." },
    { r = {"POLONIUS"}, t = "Those friends thou hast, and their adoption tried," },
    { r = {"POLONIUS"}, t = "Grapple them unto thy soul with hoops of steel;" },
    { r = {"POLONIUS"}, t = "But do not dull thy palm with entertainment" },
    { r = {"POLONIUS"}, t = "Of each new-hatch’d, unfledg’d comrade. Beware" },
    { r = {"POLONIUS"}, t = "Of entrance to a quarrel; but being in," },
    { r = {"POLONIUS"}, t = "Bear’t that th’opposed may beware of thee." },
    { r = {"POLONIUS"}, t = "Give every man thine ear, but few thy voice:" },
    { r = {"POLONIUS"}, t = "Take each man’s censure, but reserve thy judgement." },
    { r = {"POLONIUS"}, t = "Costly thy habit as thy purse can buy," },
    { r = {"POLONIUS"}, t = "But not express’d in fancy; rich, not gaudy:" },
    { r = {"POLONIUS"}, t = "For the apparel oft proclaims the man;" },
    { r = {"POLONIUS"}, t = "And they in France of the best rank and station" },
    { r = {"POLONIUS"}, t = "Are of a most select and generous chief in that." },
    { r = {"POLONIUS"}, t = "Neither a borrower nor a lender be:" },
    { r = {"POLONIUS"}, t = "For loan oft loses both itself and friend;" },
    { r = {"POLONIUS"}, t = "And borrowing dulls the edge of husbandry." },
    { r = {"POLONIUS"}, t = "This above all: to thine own self be true;" },
    { r = {"POLONIUS"}, t = "And it must follow, as the night the day," },
    { r = {"POLONIUS"}, t = "Thou canst not then be false to any man." },
    { r = {"POLONIUS"}, t = "Farewell: my blessing season this in thee." },
    { r = {"LAERTES"}, t = "Most humbly do I take my leave, my lord." },
    { r = {"POLONIUS"}, t = "The time invites you; go, your servants tend." },
    { r = {"LAERTES"}, t = "Farewell, Ophelia, and remember well" },
    { r = {"LAERTES"}, t = "What I have said to you." },
    { r = {"OPHELIA"}, t = "’Tis in my memory lock’d," },
    { r = {"OPHELIA"}, t = "And you yourself shall keep the key of it." },
    { r = {"LAERTES"}, t = "Farewell." },
    { d = "Exit" },
    { r = {"POLONIUS"}, t = "What is’t, Ophelia, he hath said to you?" },
    { r = {"OPHELIA"}, t = "So please you, something touching the Lord Hamlet." },
    { r = {"POLONIUS"}, t = "Marry, well bethought:" },
    { r = {"POLONIUS"}, t = "’Tis told me he hath very oft of late" },
    { r = {"POLONIUS"}, t = "Given private time to you; and you yourself" },
    { r = {"POLONIUS"}, t = "Have of your audience been most free and bounteous." },
    { r = {"POLONIUS"}, t = "If it be so,—as so ’tis put on me," },
    { r = {"POLONIUS"}, t = "And that in way of caution,—I must tell you" },
    { r = {"POLONIUS"}, t = "You do not understand yourself so clearly" },
    { r = {"POLONIUS"}, t = "As it behoves my daughter and your honour." },
    { r = {"POLONIUS"}, t = "What is between you? Give me up the truth." },
    { r = {"OPHELIA"}, t = "He hath, my lord, of late made many tenders" },
    { r = {"OPHELIA"}, t = "Of his affection to me." },
    { r = {"POLONIUS"}, t = "Affection! Pooh! You speak like a green girl," },
    { r = {"POLONIUS"}, t = "Unsifted in such perilous circumstance." },
    { r = {"POLONIUS"}, t = "Do you believe his tenders, as you call them?" },
    { r = {"OPHELIA"}, t = "I do not know, my lord, what I should think." },
    { r = {"POLONIUS"}, t = "Marry, I’ll teach you; think yourself a baby;" },
    { r = {"POLONIUS"}, t = "That you have ta’en these tenders for true pay," },
    { r = {"POLONIUS"}, t = "Which are not sterling. Tender yourself more dearly;" },
    { r = {"POLONIUS"}, t = "Or,—not to crack the wind of the poor phrase," },
    { r = {"POLONIUS"}, t = "Running it thus,—you’ll tender me a fool." },
    { r = {"OPHELIA"}, t = "My lord, he hath importun’d me with love" },
    { r = {"OPHELIA"}, t = "In honourable fashion." },
    { r = {"POLONIUS"}, t = "Ay, fashion you may call it; go to, go to." },
    { r = {"OPHELIA"}, t = "And hath given countenance to his speech, my lord," },
    { r = {"OPHELIA"}, t = "With almost all the holy vows of heaven." },
    { r = {"POLONIUS"}, t = "Ay, springes to catch woodcocks. I do know," },
    { r = {"POLONIUS"}, t = "When the blood burns, how prodigal the soul" },
    { r = {"POLONIUS"}, t = "Lends the tongue vows: these blazes, daughter," },
    { r = {"POLONIUS"}, t = "Giving more light than heat, extinct in both," },
    { r = {"POLONIUS"}, t = "Even in their promise, as it is a-making," },
    { r = {"POLONIUS"}, t = "You must not take for fire. From this time" },
    { r = {"POLONIUS"}, t = "Be something scanter of your maiden presence;" },
    { r = {"POLONIUS"}, t = "Set your entreatments at a higher rate" },
    { r = {"POLONIUS"}, t = "Than a command to parley. For Lord Hamlet," },
    { r = {"POLONIUS"}, t = "Believe so much in him that he is young;" },
    { r = {"POLONIUS"}, t = "And with a larger tether may he walk" },
    { r = {"POLONIUS"}, t = "Than may be given you. In few, Ophelia," },
    { r = {"POLONIUS"}, t = "Do not believe his vows; for they are brokers," },
    { r = {"POLONIUS"}, t = "Not of that dye which their investments show," },
    { r = {"POLONIUS"}, t = "But mere implorators of unholy suits," },
    { r = {"POLONIUS"}, t = "Breathing like sanctified and pious bawds," },
    { r = {"POLONIUS"}, t = "The better to beguile. This is for all:" },
    { r = {"POLONIUS"}, t = "I would not, in plain terms, from this time forth" },
    { r = {"POLONIUS"}, t = "Have you so slander any moment leisure" },
    { r = {"POLONIUS"}, t = "As to give words or talk with the Lord Hamlet." },
    { r = {"POLONIUS"}, t = "Look to’t, I charge you; come your ways." },
    { r = {"OPHELIA"}, t = "I shall obey, my lord." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 4. The platform.", h = true },
    { d = "Enter Hamlet, Horatio and Marcellus" },
    { r = {"HAMLET"}, t = "The air bites shrewdly; it is very cold." },
    { r = {"HORATIO"}, t = "It is a nipping and an eager air." },
    { r = {"HAMLET"}, t = "What hour now?" },
    { r = {"HORATIO"}, t = "I think it lacks of twelve." },
    { r = {"MARCELLUS"}, t = "No, it is struck." },
    { r = {"HORATIO"}, t = "Indeed? I heard it not. It then draws near the season" },
    { r = {"HORATIO"}, t = "Wherein the spirit held his wont to walk." },
    { d = "A flourish of trumpets, and ordnance shot off within" },
    { r = {"HORATIO"}, t = "What does this mean, my lord?" },
    { r = {"HAMLET"}, t = "The King doth wake tonight and takes his rouse," },
    { r = {"HAMLET"}, t = "Keeps wassail, and the swaggering upspring reels;" },
    { r = {"HAMLET"}, t = "And as he drains his draughts of Rhenish down," },
    { r = {"HAMLET"}, t = "The kettle-drum and trumpet thus bray out" },
    { r = {"HAMLET"}, t = "The triumph of his pledge." },
    { r = {"HORATIO"}, t = "Is it a custom?" },
    { r = {"HAMLET"}, t = "Ay marry is’t;" },
    { r = {"HAMLET"}, t = "And to my mind, though I am native here," },
    { r = {"HAMLET"}, t = "And to the manner born, it is a custom" },
    { r = {"HAMLET"}, t = "More honour’d in the breach than the observance." },
    { r = {"HAMLET"}, t = "This heavy-headed revel east and west" },
    { r = {"HAMLET"}, t = "Makes us traduc’d and tax’d of other nations:" },
    { r = {"HAMLET"}, t = "They clepe us drunkards, and with swinish phrase" },
    { r = {"HAMLET"}, t = "Soil our addition; and indeed it takes" },
    { r = {"HAMLET"}, t = "From our achievements, though perform’d at height," },
    { r = {"HAMLET"}, t = "The pith and marrow of our attribute." },
    { r = {"HAMLET"}, t = "So oft it chances in particular men" },
    { r = {"HAMLET"}, t = "That for some vicious mole of nature in them," },
    { r = {"HAMLET"}, t = "As in their birth, wherein they are not guilty," },
    { r = {"HAMLET"}, t = "Since nature cannot choose his origin," },
    { r = {"HAMLET"}, t = "By their o’ergrowth of some complexion," },
    { r = {"HAMLET"}, t = "Oft breaking down the pales and forts of reason;" },
    { r = {"HAMLET"}, t = "Or by some habit, that too much o’erleavens" },
    { r = {"HAMLET"}, t = "The form of plausive manners;—that these men," },
    { r = {"HAMLET"}, t = "Carrying, I say, the stamp of one defect," },
    { r = {"HAMLET"}, t = "Being Nature’s livery or Fortune’s star,—" },
    { r = {"HAMLET"}, t = "His virtues else,—be they as pure as grace," },
    { r = {"HAMLET"}, t = "As infinite as man may undergo," },
    { r = {"HAMLET"}, t = "Shall in the general censure take corruption" },
    { r = {"HAMLET"}, t = "From that particular fault. The dram of evil" },
    { r = {"HAMLET"}, t = "Doth all the noble substance of a doubt" },
    { r = {"HAMLET"}, t = "To his own scandal." },
    { r = {"HORATIO"}, t = "Look, my lord, it comes!" },
    { r = {"GHOST"}, d = "Enter Ghost", s = {"Fade"} },
    { r = {"HAMLET"}, t = "Angels and ministers of grace defend us!" },
    { r = {"HAMLET"}, t = "Be thou a spirit of health or goblin damn’d," },
    { r = {"HAMLET"}, t = "Bring with thee airs from heaven or blasts from hell," },
    { r = {"HAMLET"}, t = "Be thy intents wicked or charitable," },
    { r = {"HAMLET"}, t = "Thou com’st in such a questionable shape" },
    { r = {"HAMLET"}, t = "That I will speak to thee. I’ll call thee Hamlet," },
    { r = {"HAMLET"}, t = "King, father, royal Dane. O, answer me!" },
    { r = {"HAMLET"}, t = "Let me not burst in ignorance; but tell" },
    { r = {"HAMLET"}, t = "Why thy canoniz’d bones, hearsed in death," },
    { r = {"HAMLET"}, t = "Have burst their cerements; why the sepulchre," },
    { r = {"HAMLET"}, t = "Wherein we saw thee quietly inurn’d," },
    { r = {"HAMLET"}, t = "Hath op’d his ponderous and marble jaws" },
    { r = {"HAMLET"}, t = "To cast thee up again! What may this mean," },
    { r = {"HAMLET"}, t = "That thou, dead corse, again in complete steel," },
    { r = {"HAMLET"}, t = "Revisit’st thus the glimpses of the moon," },
    { r = {"HAMLET"}, t = "Making night hideous, and we fools of nature" },
    { r = {"HAMLET"}, t = "So horridly to shake our disposition" },
    { r = {"HAMLET"}, t = "With thoughts beyond the reaches of our souls?" },
    { r = {"HAMLET"}, t = "Say, why is this? Wherefore? What should we do?" },
    { r = {"GHOST"}, d = "Ghost beckons Hamlet", e = "/beckon", at = "HAMLET" },
    { r = {"HORATIO"}, t = "It beckons you to go away with it," },
    { r = {"HORATIO"}, t = "As if it some impartment did desire" },
    { r = {"HORATIO"}, t = "To you alone." },
    { r = {"MARCELLUS"}, t = "Look with what courteous action" },
    { r = {"MARCELLUS"}, t = "It waves you to a more removed ground." },
    { r = {"MARCELLUS"}, t = "But do not go with it." },
    { r = {"HORATIO"}, t = "No, by no means." },
    { r = {"HAMLET"}, t = "It will not speak; then will I follow it." },
    { r = {"HORATIO"}, t = "Do not, my lord." },
    { r = {"HAMLET"}, t = "Why, what should be the fear?" },
    { r = {"HAMLET"}, t = "I do not set my life at a pin’s fee;" },
    { r = {"HAMLET"}, t = "And for my soul, what can it do to that," },
    { r = {"HAMLET"}, t = "Being a thing immortal as itself?" },
    { r = {"HAMLET"}, t = "It waves me forth again. I’ll follow it." },
    { r = {"HORATIO"}, t = "What if it tempt you toward the flood, my lord," },
    { r = {"HORATIO"}, t = "Or to the dreadful summit of the cliff" },
    { r = {"HORATIO"}, t = "That beetles o’er his base into the sea," },
    { r = {"HORATIO"}, t = "And there assume some other horrible form" },
    { r = {"HORATIO"}, t = "Which might deprive your sovereignty of reason," },
    { r = {"HORATIO"}, t = "And draw you into madness? Think of it." },
    { r = {"HORATIO"}, t = "The very place puts toys of desperation," },
    { r = {"HORATIO"}, t = "Without more motive, into every brain" },
    { r = {"HORATIO"}, t = "That looks so many fathoms to the sea" },
    { r = {"HORATIO"}, t = "And hears it roar beneath." },
    { r = {"HAMLET"}, t = "It waves me still." },
    { r = {"HAMLET"}, t = "Go on, I’ll follow thee." },
    { r = {"MARCELLUS"}, t = "You shall not go, my lord." },
    { r = {"HAMLET"}, t = "Hold off your hands." },
    { r = {"HORATIO"}, t = "Be rul’d; you shall not go." },
    { r = {"HAMLET"}, t = "My fate cries out," },
    { r = {"HAMLET"}, t = "And makes each petty artery in this body" },
    { r = {"HAMLET"}, t = "As hardy as the Nemean lion’s nerve." },
    { r = {"GHOST"}, d = "Ghost beckons", e = "/beckon", at = "HAMLET" },
    { r = {"HAMLET"}, t = "Still am I call’d. Unhand me, gentlemen." },
    { d = "Breaking free from them" },
    { r = {"HAMLET"}, t = "By heaven, I’ll make a ghost of him that lets me." },
    { r = {"HAMLET"}, t = "I say, away!—Go on, I’ll follow thee." },
    { d = "Exeunt Ghost and Hamlet" },
    { r = {"HORATIO"}, t = "He waxes desperate with imagination." },
    { r = {"MARCELLUS"}, t = "Let’s follow; ’tis not fit thus to obey him." },
    { r = {"HORATIO"}, t = "Have after. To what issue will this come?" },
    { r = {"MARCELLUS"}, t = "Something is rotten in the state of Denmark." },
    { r = {"HORATIO"}, t = "Heaven will direct it." },
    { r = {"MARCELLUS"}, t = "Nay, let’s follow him." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 5. A more remote part of the Castle.", h = true },
    { r = {"GHOST"}, d = "Enter Ghost and Hamlet", s = {"Fade"} },
    { r = {"HAMLET"}, t = "Whither wilt thou lead me? Speak, I’ll go no further." },
    { r = {"GHOST"}, t = "Mark me." },
    { r = {"HAMLET"}, t = "I will." },
    { r = {"GHOST"}, t = "My hour is almost come," },
    { r = {"GHOST"}, t = "When I to sulph’rous and tormenting flames" },
    { r = {"GHOST"}, t = "Must render up myself." },
    { r = {"HAMLET"}, t = "Alas, poor ghost!" },
    { r = {"GHOST"}, t = "Pity me not, but lend thy serious hearing" },
    { r = {"GHOST"}, t = "To what I shall unfold." },
    { r = {"HAMLET"}, t = "Speak, I am bound to hear." },
    { r = {"GHOST"}, t = "So art thou to revenge, when thou shalt hear." },
    { r = {"HAMLET"}, t = "What?" },
    { r = {"GHOST"}, t = "I am thy father’s spirit," },
    { r = {"GHOST"}, t = "Doom’d for a certain term to walk the night," },
    { r = {"GHOST"}, t = "And for the day confin’d to fast in fires," },
    { r = {"GHOST"}, t = "Till the foul crimes done in my days of nature" },
    { r = {"GHOST"}, t = "Are burnt and purg’d away. But that I am forbid" },
    { r = {"GHOST"}, t = "To tell the secrets of my prison-house," },
    { r = {"GHOST"}, t = "I could a tale unfold whose lightest word" },
    { r = {"GHOST"}, t = "Would harrow up thy soul; freeze thy young blood," },
    { r = {"GHOST"}, t = "Make thy two eyes like stars start from their spheres," },
    { r = {"GHOST"}, t = "Thy knotted and combined locks to part," },
    { r = {"GHOST"}, t = "And each particular hair to stand on end" },
    { r = {"GHOST"}, t = "Like quills upon the fretful porpentine." },
    { r = {"GHOST"}, t = "But this eternal blazon must not be" },
    { r = {"GHOST"}, t = "To ears of flesh and blood. List, list, O, list!" },
    { r = {"GHOST"}, t = "If thou didst ever thy dear father love" },
    { r = {"HAMLET"}, t = "O God!" },
    { r = {"GHOST"}, t = "Revenge his foul and most unnatural murder." },
    { r = {"HAMLET"}, t = "Murder!" },
    { r = {"GHOST"}, t = "Murder most foul, as in the best it is;" },
    { r = {"GHOST"}, t = "But this most foul, strange, and unnatural." },
    { r = {"HAMLET"}, t = "Haste me to know’t, that I, with wings as swift" },
    { r = {"HAMLET"}, t = "As meditation or the thoughts of love" },
    { r = {"HAMLET"}, t = "May sweep to my revenge." },
    { r = {"GHOST"}, t = "I find thee apt;" },
    { r = {"GHOST"}, t = "And duller shouldst thou be than the fat weed" },
    { r = {"GHOST"}, t = "That rots itself in ease on Lethe wharf," },
    { r = {"GHOST"}, t = "Wouldst thou not stir in this. Now, Hamlet, hear." },
    { r = {"GHOST"}, t = "’Tis given out that, sleeping in my orchard," },
    { r = {"GHOST"}, t = "A serpent stung me; so the whole ear of Denmark" },
    { r = {"GHOST"}, t = "Is by a forged process of my death" },
    { r = {"GHOST"}, t = "Rankly abus’d; but know, thou noble youth," },
    { r = {"GHOST"}, t = "The serpent that did sting thy father’s life" },
    { r = {"GHOST"}, t = "Now wears his crown." },
    { r = {"HAMLET"}, t = "O my prophetic soul!" },
    { r = {"HAMLET"}, t = "Mine uncle!" },
    { r = {"GHOST"}, t = "Ay, that incestuous, that adulterate beast," },
    { r = {"GHOST"}, t = "With witchcraft of his wit, with traitorous gifts,—" },
    { r = {"GHOST"}, t = "O wicked wit, and gifts, that have the power" },
    { r = {"GHOST"}, t = "So to seduce!—won to his shameful lust" },
    { r = {"GHOST"}, t = "The will of my most seeming-virtuous queen." },
    { r = {"GHOST"}, t = "O Hamlet, what a falling off was there," },
    { r = {"GHOST"}, t = "From me, whose love was of that dignity" },
    { r = {"GHOST"}, t = "That it went hand in hand even with the vow" },
    { r = {"GHOST"}, t = "I made to her in marriage; and to decline" },
    { r = {"GHOST"}, t = "Upon a wretch whose natural gifts were poor" },
    { r = {"GHOST"}, t = "To those of mine. But virtue, as it never will be mov’d," },
    { r = {"GHOST"}, t = "Though lewdness court it in a shape of heaven;" },
    { r = {"GHOST"}, t = "So lust, though to a radiant angel link’d," },
    { r = {"GHOST"}, t = "Will sate itself in a celestial bed" },
    { r = {"GHOST"}, t = "And prey on garbage." },
    { r = {"GHOST"}, t = "But soft! methinks I scent the morning air;" },
    { r = {"GHOST"}, t = "Brief let me be. Sleeping within my orchard," },
    { r = {"GHOST"}, t = "My custom always of the afternoon," },
    { r = {"GHOST"}, t = "Upon my secure hour thy uncle stole" },
    { r = {"GHOST"}, t = "With juice of cursed hebenon in a vial," },
    { r = {"GHOST"}, t = "And in the porches of my ears did pour" },
    { r = {"GHOST"}, t = "The leperous distilment, whose effect" },
    { r = {"GHOST"}, t = "Holds such an enmity with blood of man" },
    { r = {"GHOST"}, t = "That swift as quicksilver it courses through" },
    { r = {"GHOST"}, t = "The natural gates and alleys of the body;" },
    { r = {"GHOST"}, t = "And with a sudden vigour it doth posset" },
    { r = {"GHOST"}, t = "And curd, like eager droppings into milk," },
    { r = {"GHOST"}, t = "The thin and wholesome blood. So did it mine;" },
    { r = {"GHOST"}, t = "And a most instant tetter bark’d about," },
    { r = {"GHOST"}, t = "Most lazar-like, with vile and loathsome crust" },
    { r = {"GHOST"}, t = "All my smooth body." },
    { r = {"GHOST"}, t = "Thus was I, sleeping, by a brother’s hand," },
    { r = {"GHOST"}, t = "Of life, of crown, of queen at once dispatch’d:" },
    { r = {"GHOST"}, t = "Cut off even in the blossoms of my sin," },
    { r = {"GHOST"}, t = "Unhous’led, disappointed, unanel’d;" },
    { r = {"GHOST"}, t = "No reckoning made, but sent to my account" },
    { r = {"GHOST"}, t = "With all my imperfections on my head." },
    { r = {"GHOST"}, t = "O horrible! O horrible! most horrible!" },
    { r = {"GHOST"}, t = "If thou hast nature in thee, bear it not;" },
    { r = {"GHOST"}, t = "Let not the royal bed of Denmark be" },
    { r = {"GHOST"}, t = "A couch for luxury and damned incest." },
    { r = {"GHOST"}, t = "But howsoever thou pursu’st this act," },
    { r = {"GHOST"}, t = "Taint not thy mind, nor let thy soul contrive" },
    { r = {"GHOST"}, t = "Against thy mother aught; leave her to heaven," },
    { r = {"GHOST"}, t = "And to those thorns that in her bosom lodge," },
    { r = {"GHOST"}, t = "To prick and sting her. Fare thee well at once!" },
    { r = {"GHOST"}, t = "The glow-worm shows the matin to be near," },
    { r = {"GHOST"}, t = "And ’gins to pale his uneffectual fire." },
    { r = {"GHOST"}, t = "Adieu, adieu, adieu. Remember me." },
    { d = "Exit" },
    { r = {"HAMLET"}, t = "O all you host of heaven! O earth! What else?" },
    { r = {"HAMLET"}, t = "And shall I couple hell? O, fie! Hold, my heart;" },
    { r = {"HAMLET"}, t = "And you, my sinews, grow not instant old," },
    { r = {"HAMLET"}, t = "But bear me stiffly up. Remember thee?" },
    { r = {"HAMLET"}, t = "Ay, thou poor ghost, while memory holds a seat" },
    { r = {"HAMLET"}, t = "In this distracted globe. Remember thee?" },
    { r = {"HAMLET"}, t = "Yea, from the table of my memory" },
    { r = {"HAMLET"}, t = "I’ll wipe away all trivial fond records," },
    { r = {"HAMLET"}, t = "All saws of books, all forms, all pressures past," },
    { r = {"HAMLET"}, t = "That youth and observation copied there;" },
    { r = {"HAMLET"}, t = "And thy commandment all alone shall live" },
    { r = {"HAMLET"}, t = "Within the book and volume of my brain," },
    { r = {"HAMLET"}, t = "Unmix’d with baser matter. Yes, by heaven!" },
    { r = {"HAMLET"}, t = "O most pernicious woman!" },
    { r = {"HAMLET"}, t = "O villain, villain, smiling damned villain!" },
    { r = {"HAMLET"}, t = "My tables. Meet it is I set it down," },
    { r = {"HAMLET"}, t = "That one may smile, and smile, and be a villain!" },
    { r = {"HAMLET"}, t = "At least I am sure it may be so in Denmark." },
    { d = "Writing" },
    { r = {"HAMLET"}, t = "So, uncle, there you are. Now to my word;" },
    { r = {"HAMLET"}, t = "It is ‘Adieu, adieu, remember me.’" },
    { r = {"HAMLET"}, t = "I have sworn’t." },
    { r = {"HAMLET"}, t = "HORATIO and MARCELLUS." },
    { r = {"HAMLET"}, t = "My lord, my lord.", d = "Within" },
    { r = {"MARCELLUS"}, t = "Lord Hamlet.", d = "Within" },
    { r = {"HORATIO"}, t = "Heaven secure him.", d = "Within" },
    { r = {"HAMLET"}, t = "So be it!" },
    { r = {"MARCELLUS"}, t = "Illo, ho, ho, my lord!", d = "Within" },
    { r = {"HAMLET"}, t = "Hillo, ho, ho, boy! Come, bird, come." },
    { d = "Enter Horatio and Marcellus" },
    { r = {"MARCELLUS"}, t = "How is’t, my noble lord?" },
    { r = {"HORATIO"}, t = "What news, my lord?" },
    { r = {"HAMLET"}, t = "O, wonderful!" },
    { r = {"HORATIO"}, t = "Good my lord, tell it." },
    { r = {"HAMLET"}, t = "No, you’ll reveal it." },
    { r = {"HORATIO"}, t = "Not I, my lord, by heaven." },
    { r = {"MARCELLUS"}, t = "Nor I, my lord." },
    { r = {"HAMLET"}, t = "How say you then, would heart of man once think it?—" },
    { r = {"HAMLET"}, t = "But you’ll be secret?" },
    { r = {"HAMLET"}, t = "HORATIO and MARCELLUS." },
    { r = {"HAMLET"}, t = "Ay, by heaven, my lord." },
    { r = {"HAMLET"}, t = "There’s ne’er a villain dwelling in all Denmark" },
    { r = {"HAMLET"}, t = "But he’s an arrant knave." },
    { r = {"HORATIO"}, t = "There needs no ghost, my lord, come from the grave" },
    { r = {"HORATIO"}, t = "To tell us this." },
    { r = {"HAMLET"}, t = "Why, right; you are i’ the right;" },
    { r = {"HAMLET"}, t = "And so, without more circumstance at all," },
    { r = {"HAMLET"}, t = "I hold it fit that we shake hands and part:" },
    { r = {"HAMLET"}, t = "You, as your business and desire shall point you,—" },
    { r = {"HAMLET"}, t = "For every man hath business and desire," },
    { r = {"HAMLET"}, t = "Such as it is;—and for my own poor part," },
    { r = {"HAMLET"}, t = "Look you, I’ll go pray." },
    { r = {"HORATIO"}, t = "These are but wild and whirling words, my lord." },
    { r = {"HAMLET"}, t = "I’m sorry they offend you, heartily;" },
    { r = {"HAMLET"}, t = "Yes faith, heartily." },
    { r = {"HORATIO"}, t = "There’s no offence, my lord." },
    { r = {"HAMLET"}, t = "Yes, by Saint Patrick, but there is, Horatio," },
    { r = {"HAMLET"}, t = "And much offence too. Touching this vision here," },
    { r = {"HAMLET"}, t = "It is an honest ghost, that let me tell you." },
    { r = {"HAMLET"}, t = "For your desire to know what is between us," },
    { r = {"HAMLET"}, t = "O’ermaster’t as you may. And now, good friends," },
    { r = {"HAMLET"}, t = "As you are friends, scholars, and soldiers," },
    { r = {"HAMLET"}, t = "Give me one poor request." },
    { r = {"HORATIO"}, t = "What is’t, my lord? We will." },
    { r = {"HAMLET"}, t = "Never make known what you have seen tonight." },
    { r = {"HAMLET"}, t = "HORATIO and MARCELLUS." },
    { r = {"HAMLET"}, t = "My lord, we will not." },
    { r = {"HAMLET"}, t = "Nay, but swear’t." },
    { r = {"HORATIO"}, t = "In faith, my lord, not I." },
    { r = {"MARCELLUS"}, t = "Nor I, my lord, in faith." },
    { r = {"HAMLET"}, t = "Upon my sword." },
    { r = {"MARCELLUS"}, t = "We have sworn, my lord, already." },
    { r = {"HAMLET"}, t = "Indeed, upon my sword, indeed." },
    { r = {"GHOST"}, t = "Swear.", d = "Cries under the stage" },
    { r = {"HAMLET"}, t = "Ha, ha boy, sayst thou so? Art thou there, truepenny?" },
    { r = {"HAMLET"}, t = "Come on, you hear this fellow in the cellarage." },
    { r = {"HAMLET"}, t = "Consent to swear." },
    { r = {"HORATIO"}, t = "Propose the oath, my lord." },
    { r = {"HAMLET"}, t = "Never to speak of this that you have seen." },
    { r = {"HAMLET"}, t = "Swear by my sword." },
    { r = {"GHOST"}, t = "Swear.", d = "Beneath" },
    { r = {"HAMLET"}, t = "Hic et ubique? Then we’ll shift our ground." },
    { r = {"HAMLET"}, t = "Come hither, gentlemen," },
    { r = {"HAMLET"}, t = "And lay your hands again upon my sword." },
    { r = {"HAMLET"}, t = "Never to speak of this that you have heard." },
    { r = {"HAMLET"}, t = "Swear by my sword." },
    { r = {"GHOST"}, t = "Swear.", d = "Beneath" },
    { r = {"HAMLET"}, t = "Well said, old mole! Canst work i’ th’earth so fast?" },
    { r = {"HAMLET"}, t = "A worthy pioner! Once more remove, good friends." },
    { r = {"HORATIO"}, t = "O day and night, but this is wondrous strange." },
    { r = {"HAMLET"}, t = "And therefore as a stranger give it welcome." },
    { r = {"HAMLET"}, t = "There are more things in heaven and earth, Horatio," },
    { r = {"HAMLET"}, t = "Than are dreamt of in your philosophy. But come," },
    { r = {"HAMLET"}, t = "Here, as before, never, so help you mercy," },
    { r = {"HAMLET"}, t = "How strange or odd soe’er I bear myself,—" },
    { r = {"HAMLET"}, t = "As I perchance hereafter shall think meet" },
    { r = {"HAMLET"}, t = "To put an antic disposition on—" },
    { r = {"HAMLET"}, t = "That you, at such times seeing me, never shall," },
    { r = {"HAMLET"}, t = "With arms encumber’d thus, or this head-shake," },
    { r = {"HAMLET"}, t = "Or by pronouncing of some doubtful phrase," },
    { r = {"HAMLET"}, t = "As ‘Well, we know’, or ‘We could and if we would’," },
    { r = {"HAMLET"}, t = "Or ‘If we list to speak’; or ‘There be and if they might’," },
    { r = {"HAMLET"}, t = "Or such ambiguous giving out, to note" },
    { r = {"HAMLET"}, t = "That you know aught of me:—this not to do." },
    { r = {"HAMLET"}, t = "So grace and mercy at your most need help you," },
    { r = {"HAMLET"}, t = "Swear." },
    { r = {"GHOST"}, t = "Swear.", d = "Beneath" },
    { r = {"HAMLET"}, t = "Rest, rest, perturbed spirit. So, gentlemen," },
    { r = {"HAMLET"}, t = "With all my love I do commend me to you;" },
    { r = {"HAMLET"}, t = "And what so poor a man as Hamlet is" },
    { r = {"HAMLET"}, t = "May do t’express his love and friending to you," },
    { r = {"HAMLET"}, t = "God willing, shall not lack. Let us go in together," },
    { r = {"HAMLET"}, t = "And still your fingers on your lips, I pray." },
    { r = {"HAMLET"}, t = "The time is out of joint. O cursed spite," },
    { r = {"HAMLET"}, t = "That ever I was born to set it right." },
    { r = {"HAMLET"}, t = "Nay, come, let’s go together." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 1. A room in Polonius’s house.", h = true },
    { d = "Enter Polonius and Reynaldo" },
    { r = {"POLONIUS"}, t = "Give him this money and these notes, Reynaldo." },
    { r = {"REYNALDO"}, t = "I will, my lord." },
    { r = {"POLONIUS"}, t = "You shall do marvellous wisely, good Reynaldo," },
    { r = {"POLONIUS"}, t = "Before you visit him, to make inquiry" },
    { r = {"POLONIUS"}, t = "Of his behaviour." },
    { r = {"REYNALDO"}, t = "My lord, I did intend it." },
    { r = {"POLONIUS"}, t = "Marry, well said; very well said. Look you, sir," },
    { r = {"POLONIUS"}, t = "Enquire me first what Danskers are in Paris;" },
    { r = {"POLONIUS"}, t = "And how, and who, what means, and where they keep," },
    { r = {"POLONIUS"}, t = "What company, at what expense; and finding" },
    { r = {"POLONIUS"}, t = "By this encompassment and drift of question," },
    { r = {"POLONIUS"}, t = "That they do know my son, come you more nearer" },
    { r = {"POLONIUS"}, t = "Than your particular demands will touch it." },
    { r = {"POLONIUS"}, t = "Take you as ’twere some distant knowledge of him," },
    { r = {"POLONIUS"}, t = "As thus, ‘I know his father and his friends," },
    { r = {"POLONIUS"}, t = "And in part him’—do you mark this, Reynaldo?" },
    { r = {"REYNALDO"}, t = "Ay, very well, my lord." },
    { r = {"POLONIUS"}, t = "‘And in part him, but,’ you may say, ‘not well;" },
    { r = {"POLONIUS"}, t = "But if’t be he I mean, he’s very wild;" },
    { r = {"POLONIUS"}, t = "Addicted so and so;’ and there put on him" },
    { r = {"POLONIUS"}, t = "What forgeries you please; marry, none so rank" },
    { r = {"POLONIUS"}, t = "As may dishonour him; take heed of that;" },
    { r = {"POLONIUS"}, t = "But, sir, such wanton, wild, and usual slips" },
    { r = {"POLONIUS"}, t = "As are companions noted and most known" },
    { r = {"POLONIUS"}, t = "To youth and liberty." },
    { r = {"REYNALDO"}, t = "As gaming, my lord?" },
    { r = {"POLONIUS"}, t = "Ay, or drinking, fencing, swearing," },
    { r = {"POLONIUS"}, t = "Quarrelling, drabbing. You may go so far." },
    { r = {"REYNALDO"}, t = "My lord, that would dishonour him." },
    { r = {"POLONIUS"}, t = "Faith no, as you may season it in the charge." },
    { r = {"POLONIUS"}, t = "You must not put another scandal on him," },
    { r = {"POLONIUS"}, t = "That he is open to incontinency;" },
    { r = {"POLONIUS"}, t = "That’s not my meaning: but breathe his faults so quaintly" },
    { r = {"POLONIUS"}, t = "That they may seem the taints of liberty;" },
    { r = {"POLONIUS"}, t = "The flash and outbreak of a fiery mind," },
    { r = {"POLONIUS"}, t = "A savageness in unreclaimed blood," },
    { r = {"POLONIUS"}, t = "Of general assault." },
    { r = {"REYNALDO"}, t = "But my good lord" },
    { r = {"POLONIUS"}, t = "Wherefore should you do this?" },
    { r = {"REYNALDO"}, t = "Ay, my lord, I would know that." },
    { r = {"POLONIUS"}, t = "Marry, sir, here’s my drift," },
    { r = {"POLONIUS"}, t = "And I believe it is a fetch of warrant." },
    { r = {"POLONIUS"}, t = "You laying these slight sullies on my son," },
    { r = {"POLONIUS"}, t = "As ’twere a thing a little soil’d i’ th’ working," },
    { r = {"POLONIUS"}, t = "Mark you," },
    { r = {"POLONIUS"}, t = "Your party in converse, him you would sound," },
    { r = {"POLONIUS"}, t = "Having ever seen in the prenominate crimes" },
    { r = {"POLONIUS"}, t = "The youth you breathe of guilty, be assur’d" },
    { r = {"POLONIUS"}, t = "He closes with you in this consequence;" },
    { r = {"POLONIUS"}, t = "‘Good sir,’ or so; or ‘friend,’ or ‘gentleman’—" },
    { r = {"POLONIUS"}, t = "According to the phrase or the addition" },
    { r = {"POLONIUS"}, t = "Of man and country." },
    { r = {"REYNALDO"}, t = "Very good, my lord." },
    { r = {"POLONIUS"}, t = "And then, sir, does he this,—" },
    { r = {"POLONIUS"}, t = "He does—What was I about to say?" },
    { r = {"POLONIUS"}, t = "By the mass, I was about to say something. Where did I leave?" },
    { r = {"REYNALDO"}, t = "At ‘closes in the consequence.’" },
    { r = {"REYNALDO"}, t = "At ‘friend or so,’ and ‘gentleman.’" },
    { r = {"POLONIUS"}, t = "At ‘closes in the consequence’ ay, marry!" },
    { r = {"POLONIUS"}, t = "He closes with you thus: ‘I know the gentleman," },
    { r = {"POLONIUS"}, t = "I saw him yesterday, or t’other day," },
    { r = {"POLONIUS"}, t = "Or then, or then, with such and such; and, as you say," },
    { r = {"POLONIUS"}, t = "There was he gaming, there o’ertook in’s rouse," },
    { r = {"POLONIUS"}, t = "There falling out at tennis’: or perchance," },
    { r = {"POLONIUS"}, t = "‘I saw him enter such a house of sale’—" },
    { r = {"POLONIUS"}, t = "Videlicet, a brothel, or so forth. See you now;" },
    { r = {"POLONIUS"}, t = "Your bait of falsehood takes this carp of truth;" },
    { r = {"POLONIUS"}, t = "And thus do we of wisdom and of reach," },
    { r = {"POLONIUS"}, t = "With windlasses, and with assays of bias," },
    { r = {"POLONIUS"}, t = "By indirections find directions out." },
    { r = {"POLONIUS"}, t = "So by my former lecture and advice" },
    { r = {"POLONIUS"}, t = "Shall you my son. You have me, have you not?" },
    { r = {"REYNALDO"}, t = "My lord, I have." },
    { r = {"POLONIUS"}, t = "God b’ wi’ you, fare you well." },
    { r = {"REYNALDO"}, t = "Good my lord." },
    { r = {"POLONIUS"}, t = "Observe his inclination in yourself." },
    { r = {"REYNALDO"}, t = "I shall, my lord." },
    { r = {"POLONIUS"}, t = "And let him ply his music." },
    { r = {"REYNALDO"}, t = "Well, my lord." },
    { r = {"POLONIUS"}, t = "Farewell." },
    { d = "Exit Reynaldo" },
    { d = "Enter Ophelia" },
    { r = {"POLONIUS"}, t = "How now, Ophelia, what’s the matter?" },
    { r = {"OPHELIA"}, t = "Alas, my lord, I have been so affrighted." },
    { r = {"POLONIUS"}, t = "With what, in the name of God?" },
    { r = {"OPHELIA"}, t = "My lord, as I was sewing in my chamber," },
    { r = {"OPHELIA"}, t = "Lord Hamlet, with his doublet all unbrac’d," },
    { r = {"OPHELIA"}, t = "No hat upon his head, his stockings foul’d," },
    { r = {"OPHELIA"}, t = "Ungart’red, and down-gyved to his ankle," },
    { r = {"OPHELIA"}, t = "Pale as his shirt, his knees knocking each other," },
    { r = {"OPHELIA"}, t = "And with a look so piteous in purport" },
    { r = {"OPHELIA"}, t = "As if he had been loosed out of hell" },
    { r = {"OPHELIA"}, t = "To speak of horrors, he comes before me." },
    { r = {"POLONIUS"}, t = "Mad for thy love?" },
    { r = {"OPHELIA"}, t = "My lord, I do not know, but truly I do fear it." },
    { r = {"POLONIUS"}, t = "What said he?" },
    { r = {"OPHELIA"}, t = "He took me by the wrist and held me hard;" },
    { r = {"OPHELIA"}, t = "Then goes he to the length of all his arm;" },
    { r = {"OPHELIA"}, t = "And with his other hand thus o’er his brow," },
    { r = {"OPHELIA"}, t = "He falls to such perusal of my face" },
    { r = {"OPHELIA"}, t = "As he would draw it. Long stay’d he so," },
    { r = {"OPHELIA"}, t = "At last,—a little shaking of mine arm," },
    { r = {"OPHELIA"}, t = "And thrice his head thus waving up and down," },
    { r = {"OPHELIA"}, t = "He rais’d a sigh so piteous and profound" },
    { r = {"OPHELIA"}, t = "As it did seem to shatter all his bulk" },
    { r = {"OPHELIA"}, t = "And end his being. That done, he lets me go," },
    { r = {"OPHELIA"}, t = "And with his head over his shoulder turn’d" },
    { r = {"OPHELIA"}, t = "He seem’d to find his way without his eyes," },
    { r = {"OPHELIA"}, t = "For out o’ doors he went without their help," },
    { r = {"OPHELIA"}, t = "And to the last bended their light on me." },
    { r = {"POLONIUS"}, t = "Come, go with me. I will go seek the King." },
    { r = {"POLONIUS"}, t = "This is the very ecstasy of love," },
    { r = {"POLONIUS"}, t = "Whose violent property fordoes itself," },
    { r = {"POLONIUS"}, t = "And leads the will to desperate undertakings," },
    { r = {"POLONIUS"}, t = "As oft as any passion under heaven" },
    { r = {"POLONIUS"}, t = "That does afflict our natures. I am sorry,—" },
    { r = {"POLONIUS"}, t = "What, have you given him any hard words of late?" },
    { r = {"OPHELIA"}, t = "No, my good lord; but as you did command," },
    { r = {"OPHELIA"}, t = "I did repel his letters and denied" },
    { r = {"OPHELIA"}, t = "His access to me." },
    { r = {"POLONIUS"}, t = "That hath made him mad." },
    { r = {"POLONIUS"}, t = "I am sorry that with better heed and judgement" },
    { r = {"POLONIUS"}, t = "I had not quoted him. I fear’d he did but trifle," },
    { r = {"POLONIUS"}, t = "And meant to wreck thee. But beshrew my jealousy!" },
    { r = {"POLONIUS"}, t = "It seems it is as proper to our age" },
    { r = {"POLONIUS"}, t = "To cast beyond ourselves in our opinions" },
    { r = {"POLONIUS"}, t = "As it is common for the younger sort" },
    { r = {"POLONIUS"}, t = "To lack discretion. Come, go we to the King." },
    { r = {"POLONIUS"}, t = "This must be known, which, being kept close, might move" },
    { r = {"POLONIUS"}, t = "More grief to hide than hate to utter love." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 2. A room in the Castle.", h = true },
    { d = "Enter King, Queen, Rosencrantz, Guildenstern and Attendants" },
    { r = {"CLAUDIUS"}, t = "Welcome, dear Rosencrantz and Guildenstern." },
    { r = {"CLAUDIUS"}, t = "Moreover that we much did long to see you," },
    { r = {"CLAUDIUS"}, t = "The need we have to use you did provoke" },
    { r = {"CLAUDIUS"}, t = "Our hasty sending. Something have you heard" },
    { r = {"CLAUDIUS"}, t = "Of Hamlet’s transformation; so I call it," },
    { r = {"CLAUDIUS"}, t = "Since nor th’exterior nor the inward man" },
    { r = {"CLAUDIUS"}, t = "Resembles that it was. What it should be," },
    { r = {"CLAUDIUS"}, t = "More than his father’s death, that thus hath put him" },
    { r = {"CLAUDIUS"}, t = "So much from th’understanding of himself," },
    { r = {"CLAUDIUS"}, t = "I cannot dream of. I entreat you both" },
    { r = {"CLAUDIUS"}, t = "That, being of so young days brought up with him," },
    { r = {"CLAUDIUS"}, t = "And since so neighbour’d to his youth and humour," },
    { r = {"CLAUDIUS"}, t = "That you vouchsafe your rest here in our court" },
    { r = {"CLAUDIUS"}, t = "Some little time, so by your companies" },
    { r = {"CLAUDIUS"}, t = "To draw him on to pleasures and to gather," },
    { r = {"CLAUDIUS"}, t = "So much as from occasion you may glean," },
    { r = {"CLAUDIUS"}, t = "Whether aught to us unknown afflicts him thus" },
    { r = {"CLAUDIUS"}, t = "That, open’d, lies within our remedy." },
    { r = {"GERTRUDE"}, t = "Good gentlemen, he hath much talk’d of you," },
    { r = {"GERTRUDE"}, t = "And sure I am, two men there are not living" },
    { r = {"GERTRUDE"}, t = "To whom he more adheres. If it will please you" },
    { r = {"GERTRUDE"}, t = "To show us so much gentry and good will" },
    { r = {"GERTRUDE"}, t = "As to expend your time with us awhile," },
    { r = {"GERTRUDE"}, t = "For the supply and profit of our hope," },
    { r = {"GERTRUDE"}, t = "Your visitation shall receive such thanks" },
    { r = {"GERTRUDE"}, t = "As fits a king’s remembrance." },
    { r = {"ROSENCRANTZ"}, t = "Both your majesties" },
    { r = {"ROSENCRANTZ"}, t = "Might, by the sovereign power you have of us," },
    { r = {"ROSENCRANTZ"}, t = "Put your dread pleasures more into command" },
    { r = {"ROSENCRANTZ"}, t = "Than to entreaty." },
    { r = {"GUILDENSTERN"}, t = "We both obey," },
    { r = {"GUILDENSTERN"}, t = "And here give up ourselves, in the full bent," },
    { r = {"GUILDENSTERN"}, t = "To lay our service freely at your feet" },
    { r = {"GUILDENSTERN"}, t = "To be commanded." },
    { r = {"CLAUDIUS"}, t = "Thanks, Rosencrantz and gentle Guildenstern." },
    { r = {"GERTRUDE"}, t = "Thanks, Guildenstern and gentle Rosencrantz." },
    { r = {"GERTRUDE"}, t = "And I beseech you instantly to visit" },
    { r = {"GERTRUDE"}, t = "My too much changed son. Go, some of you," },
    { r = {"GERTRUDE"}, t = "And bring these gentlemen where Hamlet is." },
    { r = {"GUILDENSTERN"}, t = "Heavens make our presence and our practices" },
    { r = {"GUILDENSTERN"}, t = "Pleasant and helpful to him." },
    { r = {"GERTRUDE"}, t = "Ay, amen." },
    { d = "Exeunt Rosencrantz, Guildenstern and some Attendants" },
    { d = "Enter Polonius" },
    { r = {"POLONIUS"}, t = "Th’ambassadors from Norway, my good lord," },
    { r = {"POLONIUS"}, t = "Are joyfully return’d." },
    { r = {"CLAUDIUS"}, t = "Thou still hast been the father of good news." },
    { r = {"POLONIUS"}, t = "Have I, my lord? Assure you, my good liege," },
    { r = {"POLONIUS"}, t = "I hold my duty, as I hold my soul," },
    { r = {"POLONIUS"}, t = "Both to my God and to my gracious King:" },
    { r = {"POLONIUS"}, t = "And I do think,—or else this brain of mine" },
    { r = {"POLONIUS"}, t = "Hunts not the trail of policy so sure" },
    { r = {"POLONIUS"}, t = "As it hath us’d to do—that I have found" },
    { r = {"POLONIUS"}, t = "The very cause of Hamlet’s lunacy." },
    { r = {"CLAUDIUS"}, t = "O speak of that, that do I long to hear." },
    { r = {"POLONIUS"}, t = "Give first admittance to th’ambassadors;" },
    { r = {"POLONIUS"}, t = "My news shall be the fruit to that great feast." },
    { r = {"CLAUDIUS"}, t = "Thyself do grace to them, and bring them in." },
    { d = "Exit Polonius" },
    { r = {"CLAUDIUS"}, t = "He tells me, my sweet queen, that he hath found" },
    { r = {"CLAUDIUS"}, t = "The head and source of all your son’s distemper." },
    { r = {"GERTRUDE"}, t = "I doubt it is no other but the main," },
    { r = {"GERTRUDE"}, t = "His father’s death and our o’erhasty marriage." },
    { r = {"CLAUDIUS"}, t = "Well, we shall sift him." },
    { d = "Enter Polonius with Voltemand and Cornelius" },
    { r = {"CLAUDIUS"}, t = "Welcome, my good friends!" },
    { r = {"CLAUDIUS"}, t = "Say, Voltemand, what from our brother Norway?" },
    { r = {"VOLTEMAND"}, t = "Most fair return of greetings and desires." },
    { r = {"VOLTEMAND"}, t = "Upon our first, he sent out to suppress" },
    { r = {"VOLTEMAND"}, t = "His nephew’s levies, which to him appear’d" },
    { r = {"VOLTEMAND"}, t = "To be a preparation ’gainst the Polack;" },
    { r = {"VOLTEMAND"}, t = "But better look’d into, he truly found" },
    { r = {"VOLTEMAND"}, t = "It was against your Highness; whereat griev’d," },
    { r = {"VOLTEMAND"}, t = "That so his sickness, age, and impotence" },
    { r = {"VOLTEMAND"}, t = "Was falsely borne in hand, sends out arrests" },
    { r = {"VOLTEMAND"}, t = "On Fortinbras; which he, in brief, obeys," },
    { r = {"VOLTEMAND"}, t = "Receives rebuke from Norway; and in fine," },
    { r = {"VOLTEMAND"}, t = "Makes vow before his uncle never more" },
    { r = {"VOLTEMAND"}, t = "To give th’assay of arms against your Majesty." },
    { r = {"VOLTEMAND"}, t = "Whereon old Norway, overcome with joy," },
    { r = {"VOLTEMAND"}, t = "Gives him three thousand crowns in annual fee," },
    { r = {"VOLTEMAND"}, t = "And his commission to employ those soldiers" },
    { r = {"VOLTEMAND"}, t = "So levied as before, against the Polack:" },
    { r = {"VOLTEMAND"}, t = "With an entreaty, herein further shown," },
    { r = {"VOLTEMAND"}, t = "That it might please you to give quiet pass", d = "Gives a paper" },
    { r = {"VOLTEMAND"}, t = "Through your dominions for this enterprise," },
    { r = {"VOLTEMAND"}, t = "On such regards of safety and allowance" },
    { r = {"VOLTEMAND"}, t = "As therein are set down." },
    { r = {"CLAUDIUS"}, t = "It likes us well;" },
    { r = {"CLAUDIUS"}, t = "And at our more consider’d time we’ll read," },
    { r = {"CLAUDIUS"}, t = "Answer, and think upon this business." },
    { r = {"CLAUDIUS"}, t = "Meantime we thank you for your well-took labour." },
    { r = {"CLAUDIUS"}, t = "Go to your rest, at night we’ll feast together:." },
    { r = {"CLAUDIUS"}, t = "Most welcome home." },
    { d = "Exeunt Voltemand and Cornelius" },
    { r = {"POLONIUS"}, t = "This business is well ended." },
    { r = {"POLONIUS"}, t = "My liege and madam, to expostulate" },
    { r = {"POLONIUS"}, t = "What majesty should be, what duty is," },
    { r = {"POLONIUS"}, t = "Why day is day, night night, and time is time" },
    { r = {"POLONIUS"}, t = "Were nothing but to waste night, day and time." },
    { r = {"POLONIUS"}, t = "Therefore, since brevity is the soul of wit," },
    { r = {"POLONIUS"}, t = "And tediousness the limbs and outward flourishes," },
    { r = {"POLONIUS"}, t = "I will be brief. Your noble son is mad." },
    { r = {"POLONIUS"}, t = "Mad call I it; for to define true madness," },
    { r = {"POLONIUS"}, t = "What is’t but to be nothing else but mad?" },
    { r = {"POLONIUS"}, t = "But let that go." },
    { r = {"GERTRUDE"}, t = "More matter, with less art." },
    { r = {"POLONIUS"}, t = "Madam, I swear I use no art at all." },
    { r = {"POLONIUS"}, t = "That he is mad, ’tis true: ’tis true ’tis pity;" },
    { r = {"POLONIUS"}, t = "And pity ’tis ’tis true. A foolish figure," },
    { r = {"POLONIUS"}, t = "But farewell it, for I will use no art." },
    { r = {"POLONIUS"}, t = "Mad let us grant him then. And now remains" },
    { r = {"POLONIUS"}, t = "That we find out the cause of this effect," },
    { r = {"POLONIUS"}, t = "Or rather say, the cause of this defect," },
    { r = {"POLONIUS"}, t = "For this effect defective comes by cause." },
    { r = {"POLONIUS"}, t = "Thus it remains, and the remainder thus. Perpend," },
    { r = {"POLONIUS"}, t = "I have a daughter—have whilst she is mine—" },
    { r = {"POLONIUS"}, t = "Who in her duty and obedience, mark," },
    { r = {"POLONIUS"}, t = "Hath given me this. Now gather, and surmise." },
    { r = {"POLONIUS"}, t = "To the celestial, and my soul’s idol, the most beautified Ophelia— That’s an ill phrase, a vile phrase; ‘beautified’ is a vile phrase: but you shall hear.", d = "Reads" },
    { r = {"POLONIUS"}, t = "these; in her excellent white bosom, these, &c.", d = "Reads" },
    { r = {"GERTRUDE"}, t = "Came this from Hamlet to her?" },
    { r = {"POLONIUS"}, t = "Good madam, stay awhile; I will be faithful." },
    { r = {"POLONIUS"}, t = "Doubt thou the stars are fire,", d = "Reads" },
    { r = {"POLONIUS"}, t = "Doubt that the sun doth move," },
    { r = {"POLONIUS"}, t = "Doubt truth to be a liar," },
    { r = {"POLONIUS"}, t = "But never doubt I love." },
    { r = {"POLONIUS"}, t = "O dear Ophelia, I am ill at these numbers." },
    { r = {"POLONIUS"}, t = "I have not art to reckon my groans." },
    { r = {"POLONIUS"}, t = "But that I love thee best, O most best, believe it." },
    { r = {"POLONIUS"}, t = "Adieu." },
    { r = {"POLONIUS"}, t = "Thine evermore, most dear lady, whilst this machine is to him," },
    { r = {"POLONIUS"}, t = "HAMLET." },
    { r = {"POLONIUS"}, t = "This in obedience hath my daughter show’d me;" },
    { r = {"POLONIUS"}, t = "And more above, hath his solicitings," },
    { r = {"POLONIUS"}, t = "As they fell out by time, by means, and place," },
    { r = {"POLONIUS"}, t = "All given to mine ear." },
    { r = {"CLAUDIUS"}, t = "But how hath she receiv’d his love?" },
    { r = {"POLONIUS"}, t = "What do you think of me?" },
    { r = {"CLAUDIUS"}, t = "As of a man faithful and honourable." },
    { r = {"POLONIUS"}, t = "I would fain prove so. But what might you think," },
    { r = {"POLONIUS"}, t = "When I had seen this hot love on the wing," },
    { r = {"POLONIUS"}, t = "As I perceiv’d it, I must tell you that," },
    { r = {"POLONIUS"}, t = "Before my daughter told me, what might you," },
    { r = {"POLONIUS"}, t = "Or my dear Majesty your queen here, think," },
    { r = {"POLONIUS"}, t = "If I had play’d the desk or table-book," },
    { r = {"POLONIUS"}, t = "Or given my heart a winking, mute and dumb," },
    { r = {"POLONIUS"}, t = "Or look’d upon this love with idle sight," },
    { r = {"POLONIUS"}, t = "What might you think? No, I went round to work," },
    { r = {"POLONIUS"}, t = "And my young mistress thus I did bespeak:" },
    { r = {"POLONIUS"}, t = "‘Lord Hamlet is a prince, out of thy star." },
    { r = {"POLONIUS"}, t = "This must not be.’ And then I precepts gave her," },
    { r = {"POLONIUS"}, t = "That she should lock herself from his resort," },
    { r = {"POLONIUS"}, t = "Admit no messengers, receive no tokens." },
    { r = {"POLONIUS"}, t = "Which done, she took the fruits of my advice," },
    { r = {"POLONIUS"}, t = "And he, repulsed,—a short tale to make—" },
    { r = {"POLONIUS"}, t = "Fell into a sadness, then into a fast," },
    { r = {"POLONIUS"}, t = "Thence to a watch, thence into a weakness," },
    { r = {"POLONIUS"}, t = "Thence to a lightness, and, by this declension," },
    { r = {"POLONIUS"}, t = "Into the madness wherein now he raves," },
    { r = {"POLONIUS"}, t = "And all we wail for." },
    { r = {"CLAUDIUS"}, t = "Do you think ’tis this?" },
    { r = {"GERTRUDE"}, t = "It may be, very likely." },
    { r = {"POLONIUS"}, t = "Hath there been such a time, I’d fain know that," },
    { r = {"POLONIUS"}, t = "That I have positively said ‘’Tis so,’" },
    { r = {"POLONIUS"}, t = "When it prov’d otherwise?" },
    { r = {"CLAUDIUS"}, t = "Not that I know." },
    { r = {"POLONIUS"}, t = "Take this from this, if this be otherwise." },
    { r = {"POLONIUS"}, t = "If circumstances lead me, I will find", d = "Points to his head and shoulder" },
    { r = {"POLONIUS"}, t = "Where truth is hid, though it were hid indeed" },
    { r = {"POLONIUS"}, t = "Within the centre." },
    { r = {"CLAUDIUS"}, t = "How may we try it further?" },
    { r = {"POLONIUS"}, t = "You know sometimes he walks four hours together" },
    { r = {"POLONIUS"}, t = "Here in the lobby." },
    { r = {"GERTRUDE"}, t = "So he does indeed." },
    { r = {"POLONIUS"}, t = "At such a time I’ll loose my daughter to him." },
    { r = {"POLONIUS"}, t = "Be you and I behind an arras then," },
    { r = {"POLONIUS"}, t = "Mark the encounter. If he love her not," },
    { r = {"POLONIUS"}, t = "And be not from his reason fall’n thereon," },
    { r = {"POLONIUS"}, t = "Let me be no assistant for a state," },
    { r = {"POLONIUS"}, t = "But keep a farm and carters." },
    { r = {"CLAUDIUS"}, t = "We will try it." },
    { d = "Enter Hamlet, reading" },
    { r = {"GERTRUDE"}, t = "But look where sadly the poor wretch comes reading." },
    { r = {"POLONIUS"}, t = "Away, I do beseech you, both away" },
    { r = {"POLONIUS"}, t = "I’ll board him presently. O, give me leave." },
    { d = "Exeunt King, Queen and Attendants" },
    { r = {"POLONIUS"}, t = "How does my good Lord Hamlet?" },
    { r = {"HAMLET"}, t = "Well, God-a-mercy." },
    { r = {"POLONIUS"}, t = "Do you know me, my lord?" },
    { r = {"HAMLET"}, t = "Excellent well. You are a fishmonger." },
    { r = {"POLONIUS"}, t = "Not I, my lord." },
    { r = {"HAMLET"}, t = "Then I would you were so honest a man." },
    { r = {"POLONIUS"}, t = "Honest, my lord?" },
    { r = {"HAMLET"}, t = "Ay sir, to be honest, as this world goes, is to be one man picked out of ten thousand." },
    { r = {"POLONIUS"}, t = "That’s very true, my lord." },
    { r = {"HAMLET"}, t = "For if the sun breed maggots in a dead dog, being a good kissing carrion,—" },
    { r = {"HAMLET"}, t = "Have you a daughter?" },
    { r = {"POLONIUS"}, t = "I have, my lord." },
    { r = {"HAMLET"}, t = "Let her not walk i’ th’ sun." },
    { r = {"HAMLET"}, t = "Conception is a blessing, but not as your daughter may conceive." },
    { r = {"HAMLET"}, t = "Friend, look to’t." },
    { r = {"POLONIUS"}, t = "How say you by that?" },
    { r = {"POLONIUS"}, t = "Still harping on my daughter.", d = "Aside" },
    { r = {"POLONIUS"}, t = "Yet he knew me not at first; he said I was a fishmonger." },
    { r = {"POLONIUS"}, t = "He is far gone, far gone." },
    { r = {"POLONIUS"}, t = "And truly in my youth I suffered much extremity for love; very near this." },
    { r = {"POLONIUS"}, t = "I’ll speak to him again.—What do you read, my lord?" },
    { r = {"HAMLET"}, t = "Words, words, words." },
    { r = {"POLONIUS"}, t = "What is the matter, my lord?" },
    { r = {"HAMLET"}, t = "Between who?" },
    { r = {"POLONIUS"}, t = "I mean the matter that you read, my lord." },
    { r = {"HAMLET"}, t = "Slanders, sir." },
    { r = {"HAMLET"}, t = "For the satirical slave says here that old men have grey beards; that their faces are wrinkled; their eyes purging thick amber and plum-tree gum; and that they have a plentiful lack of wit, together with most weak hams." },
    { r = {"HAMLET"}, t = "All which, sir, though I most powerfully and potently believe, yet I hold it not honesty to have it thus set down." },
    { r = {"HAMLET"}, t = "For you yourself, sir, should be old as I am, if like a crab you could go backward." },
    { r = {"POLONIUS"}, t = "Though this be madness, yet there is method in’t.—", d = "Aside" },
    { r = {"POLONIUS"}, t = "Will you walk out of the air, my lord?" },
    { r = {"HAMLET"}, t = "Into my grave?" },
    { r = {"POLONIUS"}, t = "Indeed, that is out o’ the air." },
    { r = {"POLONIUS"}, t = "How pregnant sometimes his replies are!", d = "Aside" },
    { r = {"POLONIUS"}, t = "A happiness that often madness hits on, which reason and sanity could not so prosperously be delivered of." },
    { r = {"POLONIUS"}, t = "I will leave him and suddenly contrive the means of meeting between him and my daughter." },
    { r = {"POLONIUS"}, t = "My honourable lord, I will most humbly take my leave of you." },
    { r = {"HAMLET"}, t = "You cannot, sir, take from me anything that I will more willingly part withal, except my life, except my life, except my life." },
    { r = {"POLONIUS"}, t = "Fare you well, my lord." },
    { r = {"HAMLET"}, t = "These tedious old fools." },
    { d = "Enter Rosencrantz and Guildenstern" },
    { r = {"POLONIUS"}, t = "You go to seek the Lord Hamlet; there he is." },
    { r = {"ROSENCRANTZ"}, t = "God save you, sir.", d = "To Polonius" },
    { d = "Exit Polonius" },
    { r = {"GUILDENSTERN"}, t = "My honoured lord!" },
    { r = {"ROSENCRANTZ"}, t = "My most dear lord!" },
    { r = {"HAMLET"}, t = "My excellent good friends! How dost thou, Guildenstern? Ah," },
    { r = {"HAMLET"}, t = "Rosencrantz. Good lads, how do ye both?" },
    { r = {"ROSENCRANTZ"}, t = "As the indifferent children of the earth." },
    { r = {"GUILDENSTERN"}, t = "Happy in that we are not over-happy;" },
    { r = {"GUILDENSTERN"}, t = "On Fortune’s cap we are not the very button." },
    { r = {"HAMLET"}, t = "Nor the soles of her shoe?" },
    { r = {"ROSENCRANTZ"}, t = "Neither, my lord." },
    { r = {"HAMLET"}, t = "Then you live about her waist, or in the middle of her favours?" },
    { r = {"GUILDENSTERN"}, t = "Faith, her privates we." },
    { r = {"HAMLET"}, t = "In the secret parts of Fortune?" },
    { r = {"HAMLET"}, t = "O, most true; she is a strumpet." },
    { r = {"HAMLET"}, t = "What’s the news?" },
    { r = {"ROSENCRANTZ"}, t = "None, my lord, but that the world’s grown honest." },
    { r = {"HAMLET"}, t = "Then is doomsday near." },
    { r = {"HAMLET"}, t = "But your news is not true." },
    { r = {"HAMLET"}, t = "Let me question more in particular." },
    { r = {"HAMLET"}, t = "What have you, my good friends, deserved at the hands of Fortune, that she sends you to prison hither?" },
    { r = {"GUILDENSTERN"}, t = "Prison, my lord?" },
    { r = {"HAMLET"}, t = "Denmark’s a prison." },
    { r = {"ROSENCRANTZ"}, t = "Then is the world one." },
    { r = {"HAMLET"}, t = "A goodly one; in which there are many confines, wards, and dungeons, Denmark being one o’ th’ worst." },
    { r = {"ROSENCRANTZ"}, t = "We think not so, my lord." },
    { r = {"HAMLET"}, t = "Why, then ’tis none to you; for there is nothing either good or bad but thinking makes it so." },
    { r = {"HAMLET"}, t = "To me it is a prison." },
    { r = {"ROSENCRANTZ"}, t = "Why, then your ambition makes it one; ’tis too narrow for your mind." },
    { r = {"HAMLET"}, t = "O God, I could be bounded in a nutshell, and count myself a king of infinite space, were it not that I have bad dreams." },
    { r = {"GUILDENSTERN"}, t = "Which dreams, indeed, are ambition; for the very substance of the ambitious is merely the shadow of a dream." },
    { r = {"HAMLET"}, t = "A dream itself is but a shadow." },
    { r = {"ROSENCRANTZ"}, t = "Truly, and I hold ambition of so airy and light a quality that it is but a shadow’s shadow." },
    { r = {"HAMLET"}, t = "Then are our beggars bodies, and our monarchs and outstretch’d heroes the beggars’ shadows." },
    { r = {"HAMLET"}, t = "Shall we to th’ court?" },
    { r = {"HAMLET"}, t = "For, by my fay, I cannot reason." },
    { r = {"HAMLET"}, t = "ROSENCRANTZ and GUILDENSTERN." },
    { r = {"HAMLET"}, t = "We’ll wait upon you." },
    { r = {"HAMLET"}, t = "No such matter." },
    { r = {"HAMLET"}, t = "I will not sort you with the rest of my servants; for, to speak to you like an honest man, I am most dreadfully attended." },
    { r = {"HAMLET"}, t = "But, in the beaten way of friendship, what make you at Elsinore?" },
    { r = {"ROSENCRANTZ"}, t = "To visit you, my lord, no other occasion." },
    { r = {"HAMLET"}, t = "Beggar that I am, I am even poor in thanks; but I thank you." },
    { r = {"HAMLET"}, t = "And sure, dear friends, my thanks are too dear a halfpenny." },
    { r = {"HAMLET"}, t = "Were you not sent for?" },
    { r = {"HAMLET"}, t = "Is it your own inclining?" },
    { r = {"HAMLET"}, t = "Is it a free visitation?" },
    { r = {"HAMLET"}, t = "Come, deal justly with me." },
    { r = {"HAMLET"}, t = "Come, come; nay, speak." },
    { r = {"GUILDENSTERN"}, t = "What should we say, my lord?" },
    { r = {"HAMLET"}, t = "Why, anything." },
    { r = {"HAMLET"}, t = "But to the purpose." },
    { r = {"HAMLET"}, t = "You were sent for; and there is a kind of confession in your looks, which your modesties have not craft enough to colour." },
    { r = {"HAMLET"}, t = "I know the good King and Queen have sent for you." },
    { r = {"ROSENCRANTZ"}, t = "To what end, my lord?" },
    { r = {"HAMLET"}, t = "That you must teach me." },
    { r = {"HAMLET"}, t = "But let me conjure you, by the rights of our fellowship, by the consonancy of our youth, by the obligation of our ever-preserved love, and by what more dear a better proposer could charge you withal, be even and direct with me," },
    { r = {"HAMLET"}, t = "whether you were sent for or no." },
    { r = {"ROSENCRANTZ"}, t = "What say you?", d = "To Guildenstern" },
    { r = {"HAMLET"}, t = "Nay, then I have an eye of you.", d = "Aside" },
    { r = {"HAMLET"}, t = "If you love me, hold not off." },
    { r = {"GUILDENSTERN"}, t = "My lord, we were sent for." },
    { r = {"HAMLET"}, t = "I will tell you why; so shall my anticipation prevent your discovery, and your secrecy to the King and Queen moult no feather." },
    { r = {"HAMLET"}, t = "I have of late, but wherefore I know not, lost all my mirth, forgone all custom of exercises; and indeed, it goes so heavily with my disposition that this goodly frame the earth, seems to me a sterile promontory;" },
    { r = {"HAMLET"}, t = "this most excellent canopy the air, look you, this brave o’erhanging firmament, this majestical roof fretted with golden fire, why, it appears no other thing to me than a foul and pestilent congregation of vapours." },
    { r = {"HAMLET"}, t = "What a piece of work is man, how noble in reason, how infinite in faculties, in form and moving, how express and admirable; in action how like an angel, in apprehension, how like a god: the beauty of the world, the paragon of animals." },
    { r = {"HAMLET"}, t = "And yet, to me, what is this quintessence of dust?" },
    { r = {"HAMLET"}, t = "Man delights not me; no, nor woman neither, though by your smiling you seem to say so." },
    { r = {"ROSENCRANTZ"}, t = "My lord, there was no such stuff in my thoughts." },
    { r = {"HAMLET"}, t = "Why did you laugh then, when I said ‘Man delights not me’?" },
    { r = {"ROSENCRANTZ"}, t = "To think, my lord, if you delight not in man, what Lenten entertainment the players shall receive from you." },
    { r = {"ROSENCRANTZ"}, t = "We coted them on the way, and hither are they coming to offer you service." },
    { r = {"HAMLET"}, t = "He that plays the king shall be welcome,— his Majesty shall have tribute of me; the adventurous knight shall use his foil and target; the lover shall not sigh gratis, the humorous man shall end his part in peace;" },
    { r = {"HAMLET"}, t = "the clown shall make those laugh whose lungs are tickle o’ th’ sere; and the lady shall say her mind freely, or the blank verse shall halt for’t." },
    { r = {"HAMLET"}, t = "What players are they?" },
    { r = {"ROSENCRANTZ"}, t = "Even those you were wont to take such delight in—the tragedians of the city." },
    { r = {"HAMLET"}, t = "How chances it they travel?" },
    { r = {"HAMLET"}, t = "Their residence, both in reputation and profit, was better both ways." },
    { r = {"ROSENCRANTZ"}, t = "I think their inhibition comes by the means of the late innovation." },
    { r = {"HAMLET"}, t = "Do they hold the same estimation they did when I was in the city?" },
    { r = {"HAMLET"}, t = "Are they so followed?" },
    { r = {"ROSENCRANTZ"}, t = "No, indeed, they are not." },
    { r = {"HAMLET"}, t = "How comes it? Do they grow rusty?" },
    { r = {"ROSENCRANTZ"}, t = "Nay, their endeavour keeps in the wonted pace; but there is, sir, an aerie of children, little eyases, that cry out on the top of question, and are most tyrannically clapped for’t." },
    { r = {"ROSENCRANTZ"}, t = "These are now the fashion, and so berattle the common stages—so they call them—that many wearing rapiers are afraid of goose-quills and dare scarce come thither." },
    { r = {"HAMLET"}, t = "What, are they children?" },
    { r = {"HAMLET"}, t = "Who maintains ’em?" },
    { r = {"HAMLET"}, t = "How are they escoted?" },
    { r = {"HAMLET"}, t = "Will they pursue the quality no longer than they can sing?" },
    { r = {"HAMLET"}, t = "Will they not say afterwards, if they should grow themselves to common players—as it is most like, if their means are no better—their writers do them wrong to make them exclaim against their own succession?" },
    { r = {"ROSENCRANTZ"}, t = "Faith, there has been much to do on both sides; and the nation holds it no sin to tarre them to controversy." },
    { r = {"ROSENCRANTZ"}, t = "There was for a while, no money bid for argument unless the poet and the player went to cuffs in the question." },
    { r = {"HAMLET"}, t = "Is’t possible?" },
    { r = {"GUILDENSTERN"}, t = "O, there has been much throwing about of brains." },
    { r = {"HAMLET"}, t = "Do the boys carry it away?" },
    { r = {"ROSENCRANTZ"}, t = "Ay, that they do, my lord. Hercules and his load too." },
    { r = {"HAMLET"}, t = "It is not very strange; for my uncle is King of Denmark, and those that would make mouths at him while my father lived, give twenty, forty, fifty, a hundred ducats apiece for his picture in little." },
    { r = {"HAMLET"}, t = "’Sblood, there is something in this more than natural, if philosophy could find it out." },
    { d = "Flourish of trumpets within" },
    { r = {"GUILDENSTERN"}, t = "There are the players." },
    { r = {"HAMLET"}, t = "Gentlemen, you are welcome to Elsinore." },
    { r = {"HAMLET"}, t = "Your hands, come." },
    { r = {"HAMLET"}, t = "The appurtenance of welcome is fashion and ceremony." },
    { r = {"HAMLET"}, t = "Let me comply with you in this garb, lest my extent to the players, which I tell you must show fairly outward, should more appear like entertainment than yours." },
    { r = {"HAMLET"}, t = "You are welcome." },
    { r = {"HAMLET"}, t = "But my uncle-father and aunt-mother are deceived." },
    { r = {"GUILDENSTERN"}, t = "In what, my dear lord?" },
    { r = {"HAMLET"}, t = "I am but mad north-north-west." },
    { r = {"HAMLET"}, t = "When the wind is southerly, I know a hawk from a handsaw." },
    { d = "Enter Polonius" },
    { r = {"POLONIUS"}, t = "Well be with you, gentlemen." },
    { r = {"HAMLET"}, t = "Hark you, Guildenstern, and you too, at each ear a hearer." },
    { r = {"HAMLET"}, t = "That great baby you see there is not yet out of his swaddling clouts." },
    { r = {"ROSENCRANTZ"}, t = "Happily he’s the second time come to them; for they say an old man is twice a child." },
    { r = {"HAMLET"}, t = "I will prophesy he comes to tell me of the players." },
    { r = {"HAMLET"}, t = "Mark it.—You say right, sir: for a Monday morning ’twas so indeed." },
    { r = {"POLONIUS"}, t = "My lord, I have news to tell you." },
    { r = {"HAMLET"}, t = "My lord, I have news to tell you. When Roscius was an actor in Rome" },
    { r = {"POLONIUS"}, t = "The actors are come hither, my lord." },
    { r = {"HAMLET"}, t = "Buzz, buzz." },
    { r = {"POLONIUS"}, t = "Upon my honour." },
    { r = {"HAMLET"}, t = "Then came each actor on his ass" },
    { r = {"POLONIUS"}, t = "The best actors in the world, either for tragedy, comedy, history, pastoral, pastoral-comical, historical-pastoral, tragical-historical, tragical-comical-historical-pastoral, scene individable, or poem unlimited." },
    { r = {"POLONIUS"}, t = "Seneca cannot be too heavy, nor Plautus too light, for the law of writ and the liberty." },
    { r = {"POLONIUS"}, t = "These are the only men." },
    { r = {"HAMLET"}, t = "O Jephthah, judge of Israel, what a treasure hadst thou!" },
    { r = {"POLONIUS"}, t = "What treasure had he, my lord?" },
    { r = {"HAMLET"}, t = "Why—" },
    { r = {"HAMLET"}, t = "’One fair daughter, and no more," },
    { r = {"HAMLET"}, t = "The which he loved passing well.’" },
    { r = {"POLONIUS"}, t = "Still on my daughter.", d = "Aside" },
    { r = {"HAMLET"}, t = "Am I not i’ th’ right, old Jephthah?" },
    { r = {"POLONIUS"}, t = "If you call me Jephthah, my lord, I have a daughter that I love passing well." },
    { r = {"HAMLET"}, t = "Nay, that follows not." },
    { r = {"POLONIUS"}, t = "What follows then, my lord?" },
    { r = {"HAMLET"}, t = "Why," },
    { r = {"HAMLET"}, t = "As by lot, God wot, and then, you know," },
    { r = {"HAMLET"}, t = "It came to pass, as most like it was." },
    { r = {"HAMLET"}, t = "The first row of the pious chanson will show you more." },
    { r = {"HAMLET"}, t = "For look where my abridgement comes." },
    { d = "Enter four or five Players" },
    { r = {"HAMLET"}, t = "You are welcome, masters, welcome all. I am glad to see thee well." },
    { r = {"HAMLET"}, t = "Welcome, good friends." },
    { r = {"HAMLET"}, t = "O, my old friend!" },
    { r = {"HAMLET"}, t = "Thy face is valanc’d since I saw thee last." },
    { r = {"HAMLET"}, t = "Com’st thou to beard me in Denmark?" },
    { r = {"HAMLET"}, t = "What, my young lady and mistress!" },
    { r = {"HAMLET"}, t = "By’r lady, your ladyship is nearer to heaven than when I saw you last, by the altitude of a chopine." },
    { r = {"HAMLET"}, t = "Pray God your voice, like a piece of uncurrent gold, be not cracked within the ring." },
    { r = {"HAMLET"}, t = "Masters, you are all welcome." },
    { r = {"HAMLET"}, t = "We’ll e’en to’t like French falconers, fly at anything we see." },
    { r = {"HAMLET"}, t = "We’ll have a speech straight." },
    { r = {"HAMLET"}, t = "Come, give us a taste of your quality." },
    { r = {"HAMLET"}, t = "Come, a passionate speech." },
    { r = {"FIRST PLAYER"}, t = "What speech, my lord?" },
    { r = {"HAMLET"}, t = "I heard thee speak me a speech once, but it was never acted, or if it was, not above once, for the play, I remember, pleased not the million, ’twas caviare to the general." },
    { r = {"HAMLET"}, t = "But it was—as I received it, and others, whose judgements in such matters cried in the top of mine—an excellent play, well digested in the scenes, set down with as much modesty as cunning." },
    { r = {"HAMLET"}, t = "I remember one said there were no sallets in the lines to make the matter savoury, nor no matter in the phrase that might indite the author of affectation, but called it an honest method, as wholesome as sweet," },
    { r = {"HAMLET"}, t = "and by very much more handsome than fine." },
    { r = {"HAMLET"}, t = "One speech in it, I chiefly loved. ’Twas Aeneas’ tale to Dido, and thereabout of it especially where he speaks of Priam’s slaughter." },
    { r = {"HAMLET"}, t = "If it live in your memory, begin at this line, let me see, let me see:" },
    { r = {"HAMLET"}, t = "The rugged Pyrrhus, like th’ Hyrcanian beast,—" },
    { r = {"HAMLET"}, t = "It is not so: it begins with Pyrrhus—" },
    { r = {"HAMLET"}, t = "The rugged Pyrrhus, he whose sable arms," },
    { r = {"HAMLET"}, t = "Black as his purpose, did the night resemble" },
    { r = {"HAMLET"}, t = "When he lay couched in the ominous horse," },
    { r = {"HAMLET"}, t = "Hath now this dread and black complexion smear’d" },
    { r = {"HAMLET"}, t = "With heraldry more dismal. Head to foot" },
    { r = {"HAMLET"}, t = "Now is he total gules, horridly trick’d" },
    { r = {"HAMLET"}, t = "With blood of fathers, mothers, daughters, sons," },
    { r = {"HAMLET"}, t = "Bak’d and impasted with the parching streets," },
    { r = {"HAMLET"}, t = "That lend a tyrannous and a damned light" },
    { r = {"HAMLET"}, t = "To their vile murders. Roasted in wrath and fire," },
    { r = {"HAMLET"}, t = "And thus o’ersized with coagulate gore," },
    { r = {"HAMLET"}, t = "With eyes like carbuncles, the hellish Pyrrhus" },
    { r = {"HAMLET"}, t = "Old grandsire Priam seeks." },
    { r = {"HAMLET"}, t = "So, proceed you." },
    { r = {"POLONIUS"}, t = "’Fore God, my lord, well spoken, with good accent and good discretion." },
    { r = {"FIRST PLAYER"}, t = "Anon he finds him," },
    { r = {"FIRST PLAYER"}, t = "Striking too short at Greeks. His antique sword," },
    { r = {"FIRST PLAYER"}, t = "Rebellious to his arm, lies where it falls," },
    { r = {"FIRST PLAYER"}, t = "Repugnant to command. Unequal match’d," },
    { r = {"FIRST PLAYER"}, t = "Pyrrhus at Priam drives, in rage strikes wide;" },
    { r = {"FIRST PLAYER"}, t = "But with the whiff and wind of his fell sword" },
    { r = {"FIRST PLAYER"}, t = "Th’unnerved father falls. Then senseless Ilium," },
    { r = {"FIRST PLAYER"}, t = "Seeming to feel this blow, with flaming top" },
    { r = {"FIRST PLAYER"}, t = "Stoops to his base, and with a hideous crash" },
    { r = {"FIRST PLAYER"}, t = "Takes prisoner Pyrrhus’ ear. For lo, his sword," },
    { r = {"FIRST PLAYER"}, t = "Which was declining on the milky head" },
    { r = {"FIRST PLAYER"}, t = "Of reverend Priam, seem’d i’ th’air to stick." },
    { r = {"FIRST PLAYER"}, t = "So, as a painted tyrant, Pyrrhus stood," },
    { r = {"FIRST PLAYER"}, t = "And like a neutral to his will and matter," },
    { r = {"FIRST PLAYER"}, t = "Did nothing." },
    { r = {"FIRST PLAYER"}, t = "But as we often see against some storm," },
    { r = {"FIRST PLAYER"}, t = "A silence in the heavens, the rack stand still," },
    { r = {"FIRST PLAYER"}, t = "The bold winds speechless, and the orb below" },
    { r = {"FIRST PLAYER"}, t = "As hush as death, anon the dreadful thunder" },
    { r = {"FIRST PLAYER"}, t = "Doth rend the region; so after Pyrrhus’ pause," },
    { r = {"FIRST PLAYER"}, t = "Aroused vengeance sets him new a-work," },
    { r = {"FIRST PLAYER"}, t = "And never did the Cyclops’ hammers fall" },
    { r = {"FIRST PLAYER"}, t = "On Mars’s armour, forg’d for proof eterne," },
    { r = {"FIRST PLAYER"}, t = "With less remorse than Pyrrhus’ bleeding sword" },
    { r = {"FIRST PLAYER"}, t = "Now falls on Priam." },
    { r = {"FIRST PLAYER"}, t = "Out, out, thou strumpet Fortune! All you gods," },
    { r = {"FIRST PLAYER"}, t = "In general synod, take away her power;" },
    { r = {"FIRST PLAYER"}, t = "Break all the spokes and fellies from her wheel," },
    { r = {"FIRST PLAYER"}, t = "And bowl the round nave down the hill of heaven," },
    { r = {"FIRST PLAYER"}, t = "As low as to the fiends." },
    { r = {"POLONIUS"}, t = "This is too long." },
    { r = {"HAMLET"}, t = "It shall to the barber’s, with your beard.—Prithee say on." },
    { r = {"HAMLET"}, t = "He’s for a jig or a tale of bawdry, or he sleeps." },
    { r = {"HAMLET"}, t = "Say on; come to Hecuba." },
    { r = {"FIRST PLAYER"}, t = "But who, O who, had seen the mobled queen," },
    { r = {"HAMLET"}, t = "‘The mobled queen’?" },
    { r = {"POLONIUS"}, t = "That’s good! ‘Mobled queen’ is good." },
    { r = {"FIRST PLAYER"}, t = "Run barefoot up and down, threat’ning the flames" },
    { r = {"FIRST PLAYER"}, t = "With bisson rheum. A clout upon that head" },
    { r = {"FIRST PLAYER"}, t = "Where late the diadem stood, and for a robe," },
    { r = {"FIRST PLAYER"}, t = "About her lank and all o’erteemed loins," },
    { r = {"FIRST PLAYER"}, t = "A blanket, in th’alarm of fear caught up—" },
    { r = {"FIRST PLAYER"}, t = "Who this had seen, with tongue in venom steep’d," },
    { r = {"FIRST PLAYER"}, t = "’Gainst Fortune’s state would treason have pronounc’d." },
    { r = {"FIRST PLAYER"}, t = "But if the gods themselves did see her then," },
    { r = {"FIRST PLAYER"}, t = "When she saw Pyrrhus make malicious sport" },
    { r = {"FIRST PLAYER"}, t = "In mincing with his sword her husband’s limbs," },
    { r = {"FIRST PLAYER"}, t = "The instant burst of clamour that she made,—" },
    { r = {"FIRST PLAYER"}, t = "Unless things mortal move them not at all,—" },
    { r = {"FIRST PLAYER"}, t = "Would have made milch the burning eyes of heaven," },
    { r = {"FIRST PLAYER"}, t = "And passion in the gods." },
    { r = {"POLONIUS"}, t = "Look, where he has not turn’d his colour, and has tears in’s eyes." },
    { r = {"POLONIUS"}, t = "Pray you, no more." },
    { r = {"HAMLET"}, t = "’Tis well." },
    { r = {"HAMLET"}, t = "I’ll have thee speak out the rest of this soon.—Good my lord, will you see the players well bestowed?" },
    { r = {"HAMLET"}, t = "Do you hear, let them be well used; for they are the abstracts and brief chronicles of the time." },
    { r = {"HAMLET"}, t = "After your death you were better have a bad epitaph than their ill report while you live." },
    { r = {"POLONIUS"}, t = "My lord, I will use them according to their desert." },
    { r = {"HAMLET"}, t = "God’s bodikin, man, much better." },
    { r = {"HAMLET"}, t = "Use every man after his desert, and who should ’scape whipping?" },
    { r = {"HAMLET"}, t = "Use them after your own honour and dignity." },
    { r = {"HAMLET"}, t = "The less they deserve, the more merit is in your bounty." },
    { r = {"HAMLET"}, t = "Take them in." },
    { r = {"POLONIUS"}, t = "Come, sirs." },
    { r = {"HAMLET"}, t = "Follow him, friends. We’ll hear a play tomorrow." },
    { d = "Exeunt Polonius with all the Players but the First" },
    { r = {"HAMLET"}, t = "Dost thou hear me, old friend? Can you play The Murder of Gonzago?" },
    { r = {"FIRST PLAYER"}, t = "Ay, my lord." },
    { r = {"HAMLET"}, t = "We’ll ha’t tomorrow night." },
    { r = {"HAMLET"}, t = "You could for a need study a speech of some dozen or sixteen lines, which I would set down and insert in’t, could you not?" },
    { r = {"FIRST PLAYER"}, t = "Ay, my lord." },
    { r = {"HAMLET"}, t = "Very well. Follow that lord, and look you mock him not." },
    { d = "Exit First Player" },
    { r = {"HAMLET"}, t = "My good friends, I’ll leave you till night.", d = "To Rosencrantz and Guildenstern" },
    { r = {"HAMLET"}, t = "You are welcome to Elsinore." },
    { r = {"ROSENCRANTZ"}, t = "Good my lord." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { r = {"HAMLET"}, t = "Ay, so, God b’ wi’ ye. Now I am alone." },
    { r = {"HAMLET"}, t = "O what a rogue and peasant slave am I!" },
    { r = {"HAMLET"}, t = "Is it not monstrous that this player here," },
    { r = {"HAMLET"}, t = "But in a fiction, in a dream of passion," },
    { r = {"HAMLET"}, t = "Could force his soul so to his own conceit" },
    { r = {"HAMLET"}, t = "That from her working all his visage wan’d;" },
    { r = {"HAMLET"}, t = "Tears in his eyes, distraction in’s aspect," },
    { r = {"HAMLET"}, t = "A broken voice, and his whole function suiting" },
    { r = {"HAMLET"}, t = "With forms to his conceit? And all for nothing!" },
    { r = {"HAMLET"}, t = "For Hecuba?" },
    { r = {"HAMLET"}, t = "What’s Hecuba to him, or he to Hecuba," },
    { r = {"HAMLET"}, t = "That he should weep for her? What would he do," },
    { r = {"HAMLET"}, t = "Had he the motive and the cue for passion" },
    { r = {"HAMLET"}, t = "That I have? He would drown the stage with tears" },
    { r = {"HAMLET"}, t = "And cleave the general ear with horrid speech;" },
    { r = {"HAMLET"}, t = "Make mad the guilty, and appal the free," },
    { r = {"HAMLET"}, t = "Confound the ignorant, and amaze indeed," },
    { r = {"HAMLET"}, t = "The very faculties of eyes and ears. Yet I," },
    { r = {"HAMLET"}, t = "A dull and muddy-mettled rascal, peak" },
    { r = {"HAMLET"}, t = "Like John-a-dreams, unpregnant of my cause," },
    { r = {"HAMLET"}, t = "And can say nothing. No, not for a king" },
    { r = {"HAMLET"}, t = "Upon whose property and most dear life" },
    { r = {"HAMLET"}, t = "A damn’d defeat was made. Am I a coward?" },
    { r = {"HAMLET"}, t = "Who calls me villain, breaks my pate across?" },
    { r = {"HAMLET"}, t = "Plucks off my beard and blows it in my face?" },
    { r = {"HAMLET"}, t = "Tweaks me by the nose, gives me the lie i’ th’ throat" },
    { r = {"HAMLET"}, t = "As deep as to the lungs? Who does me this?" },
    { r = {"HAMLET"}, t = "Ha! ’Swounds, I should take it: for it cannot be" },
    { r = {"HAMLET"}, t = "But I am pigeon-liver’d, and lack gall" },
    { r = {"HAMLET"}, t = "To make oppression bitter, or ere this" },
    { r = {"HAMLET"}, t = "I should have fatted all the region kites" },
    { r = {"HAMLET"}, t = "With this slave’s offal. Bloody, bawdy villain!" },
    { r = {"HAMLET"}, t = "Remorseless, treacherous, lecherous, kindless villain!" },
    { r = {"HAMLET"}, t = "Oh vengeance!" },
    { r = {"HAMLET"}, t = "Why, what an ass am I! This is most brave," },
    { r = {"HAMLET"}, t = "That I, the son of a dear father murder’d," },
    { r = {"HAMLET"}, t = "Prompted to my revenge by heaven and hell," },
    { r = {"HAMLET"}, t = "Must, like a whore, unpack my heart with words" },
    { r = {"HAMLET"}, t = "And fall a-cursing like a very drab," },
    { r = {"HAMLET"}, t = "A scullion! Fie upon’t! Foh!" },
    { r = {"HAMLET"}, t = "About, my brain! I have heard" },
    { r = {"HAMLET"}, t = "That guilty creatures sitting at a play," },
    { r = {"HAMLET"}, t = "Have by the very cunning of the scene," },
    { r = {"HAMLET"}, t = "Been struck so to the soul that presently" },
    { r = {"HAMLET"}, t = "They have proclaim’d their malefactions." },
    { r = {"HAMLET"}, t = "For murder, though it have no tongue, will speak" },
    { r = {"HAMLET"}, t = "With most miraculous organ. I’ll have these players" },
    { r = {"HAMLET"}, t = "Play something like the murder of my father" },
    { r = {"HAMLET"}, t = "Before mine uncle. I’ll observe his looks;" },
    { r = {"HAMLET"}, t = "I’ll tent him to the quick. If he but blench," },
    { r = {"HAMLET"}, t = "I know my course. The spirit that I have seen" },
    { r = {"HAMLET"}, t = "May be the devil, and the devil hath power" },
    { r = {"HAMLET"}, t = "T’assume a pleasing shape, yea, and perhaps" },
    { r = {"HAMLET"}, t = "Out of my weakness and my melancholy," },
    { r = {"HAMLET"}, t = "As he is very potent with such spirits," },
    { r = {"HAMLET"}, t = "Abuses me to damn me. I’ll have grounds" },
    { r = {"HAMLET"}, t = "More relative than this. The play’s the thing" },
    { r = {"HAMLET"}, t = "Wherein I’ll catch the conscience of the King." },
    { d = "Exit" },
    { d = "Act 3, Scene 1. A room in the Castle.", h = true },
    { d = "Enter King, Queen, Polonius, Ophelia, Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "And can you by no drift of circumstance" },
    { r = {"CLAUDIUS"}, t = "Get from him why he puts on this confusion," },
    { r = {"CLAUDIUS"}, t = "Grating so harshly all his days of quiet" },
    { r = {"CLAUDIUS"}, t = "With turbulent and dangerous lunacy?" },
    { r = {"ROSENCRANTZ"}, t = "He does confess he feels himself distracted," },
    { r = {"ROSENCRANTZ"}, t = "But from what cause he will by no means speak." },
    { r = {"GUILDENSTERN"}, t = "Nor do we find him forward to be sounded," },
    { r = {"GUILDENSTERN"}, t = "But with a crafty madness keeps aloof" },
    { r = {"GUILDENSTERN"}, t = "When we would bring him on to some confession" },
    { r = {"GUILDENSTERN"}, t = "Of his true state." },
    { r = {"GERTRUDE"}, t = "Did he receive you well?" },
    { r = {"ROSENCRANTZ"}, t = "Most like a gentleman." },
    { r = {"GUILDENSTERN"}, t = "But with much forcing of his disposition." },
    { r = {"ROSENCRANTZ"}, t = "Niggard of question, but of our demands," },
    { r = {"ROSENCRANTZ"}, t = "Most free in his reply." },
    { r = {"GERTRUDE"}, t = "Did you assay him to any pastime?" },
    { r = {"ROSENCRANTZ"}, t = "Madam, it so fell out that certain players" },
    { r = {"ROSENCRANTZ"}, t = "We o’er-raught on the way. Of these we told him," },
    { r = {"ROSENCRANTZ"}, t = "And there did seem in him a kind of joy" },
    { r = {"ROSENCRANTZ"}, t = "To hear of it. They are about the court," },
    { r = {"ROSENCRANTZ"}, t = "And, as I think, they have already order" },
    { r = {"ROSENCRANTZ"}, t = "This night to play before him." },
    { r = {"POLONIUS"}, t = "’Tis most true;" },
    { r = {"POLONIUS"}, t = "And he beseech’d me to entreat your Majesties" },
    { r = {"POLONIUS"}, t = "To hear and see the matter." },
    { r = {"CLAUDIUS"}, t = "With all my heart; and it doth much content me" },
    { r = {"CLAUDIUS"}, t = "To hear him so inclin’d." },
    { r = {"CLAUDIUS"}, t = "Good gentlemen, give him a further edge," },
    { r = {"CLAUDIUS"}, t = "And drive his purpose on to these delights." },
    { r = {"ROSENCRANTZ"}, t = "We shall, my lord." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "Sweet Gertrude, leave us too," },
    { r = {"CLAUDIUS"}, t = "For we have closely sent for Hamlet hither," },
    { r = {"CLAUDIUS"}, t = "That he, as ’twere by accident, may here" },
    { r = {"CLAUDIUS"}, t = "Affront Ophelia." },
    { r = {"CLAUDIUS"}, t = "Her father and myself, lawful espials," },
    { r = {"CLAUDIUS"}, t = "Will so bestow ourselves that, seeing unseen," },
    { r = {"CLAUDIUS"}, t = "We may of their encounter frankly judge," },
    { r = {"CLAUDIUS"}, t = "And gather by him, as he is behav’d," },
    { r = {"CLAUDIUS"}, t = "If’t be th’affliction of his love or no" },
    { r = {"CLAUDIUS"}, t = "That thus he suffers for." },
    { r = {"GERTRUDE"}, t = "I shall obey you." },
    { r = {"GERTRUDE"}, t = "And for your part, Ophelia, I do wish" },
    { r = {"GERTRUDE"}, t = "That your good beauties be the happy cause" },
    { r = {"GERTRUDE"}, t = "Of Hamlet’s wildness: so shall I hope your virtues" },
    { r = {"GERTRUDE"}, t = "Will bring him to his wonted way again," },
    { r = {"GERTRUDE"}, t = "To both your honours." },
    { r = {"OPHELIA"}, t = "Madam, I wish it may." },
    { d = "Exit Queen" },
    { r = {"POLONIUS"}, t = "Ophelia, walk you here.—Gracious, so please you," },
    { r = {"POLONIUS"}, t = "We will bestow ourselves." },
    { r = {"POLONIUS"}, t = "Read on this book,", d = "To Ophelia" },
    { r = {"POLONIUS"}, t = "That show of such an exercise may colour" },
    { r = {"POLONIUS"}, t = "Your loneliness.—We are oft to blame in this," },
    { r = {"POLONIUS"}, t = "’Tis too much prov’d, that with devotion’s visage" },
    { r = {"POLONIUS"}, t = "And pious action we do sugar o’er" },
    { r = {"POLONIUS"}, t = "The devil himself." },
    { r = {"CLAUDIUS"}, t = "O ’tis too true!", d = "Aside" },
    { r = {"CLAUDIUS"}, t = "How smart a lash that speech doth give my conscience!" },
    { r = {"CLAUDIUS"}, t = "The harlot’s cheek, beautied with plastering art," },
    { r = {"CLAUDIUS"}, t = "Is not more ugly to the thing that helps it" },
    { r = {"CLAUDIUS"}, t = "Than is my deed to my most painted word." },
    { r = {"CLAUDIUS"}, t = "O heavy burden!" },
    { r = {"POLONIUS"}, t = "I hear him coming. Let’s withdraw, my lord." },
    { d = "Exeunt King and Polonius" },
    { d = "Enter Hamlet" },
    { r = {"HAMLET"}, t = "To be, or not to be, that is the question:", e = "/ponder" },
    { r = {"HAMLET"}, t = "Whether ’tis nobler in the mind to suffer" },
    { r = {"HAMLET"}, t = "The slings and arrows of outrageous fortune," },
    { r = {"HAMLET"}, t = "Or to take arms against a sea of troubles," },
    { r = {"HAMLET"}, t = "And by opposing end them? To die—to sleep," },
    { r = {"HAMLET"}, t = "No more; and by a sleep to say we end" },
    { r = {"HAMLET"}, t = "The heart-ache, and the thousand natural shocks" },
    { r = {"HAMLET"}, t = "That flesh is heir to: ’tis a consummation" },
    { r = {"HAMLET"}, t = "Devoutly to be wish’d. To die, to sleep." },
    { r = {"HAMLET"}, t = "To sleep, perchance to dream—ay, there’s the rub," },
    { r = {"HAMLET"}, t = "For in that sleep of death what dreams may come," },
    { r = {"HAMLET"}, t = "When we have shuffled off this mortal coil," },
    { r = {"HAMLET"}, t = "Must give us pause. There’s the respect" },
    { r = {"HAMLET"}, t = "That makes calamity of so long life." },
    { r = {"HAMLET"}, t = "For who would bear the whips and scorns of time," },
    { r = {"HAMLET"}, t = "The oppressor’s wrong, the proud man’s contumely," },
    { r = {"HAMLET"}, t = "The pangs of dispriz’d love, the law’s delay," },
    { r = {"HAMLET"}, t = "The insolence of office, and the spurns" },
    { r = {"HAMLET"}, t = "That patient merit of the unworthy takes," },
    { r = {"HAMLET"}, t = "When he himself might his quietus make" },
    { r = {"HAMLET"}, t = "With a bare bodkin? Who would these fardels bear," },
    { r = {"HAMLET"}, t = "To grunt and sweat under a weary life," },
    { r = {"HAMLET"}, t = "But that the dread of something after death," },
    { r = {"HAMLET"}, t = "The undiscover’d country, from whose bourn" },
    { r = {"HAMLET"}, t = "No traveller returns, puzzles the will," },
    { r = {"HAMLET"}, t = "And makes us rather bear those ills we have" },
    { r = {"HAMLET"}, t = "Than fly to others that we know not of?" },
    { r = {"HAMLET"}, t = "Thus conscience does make cowards of us all," },
    { r = {"HAMLET"}, t = "And thus the native hue of resolution" },
    { r = {"HAMLET"}, t = "Is sicklied o’er with the pale cast of thought," },
    { r = {"HAMLET"}, t = "And enterprises of great pith and moment," },
    { r = {"HAMLET"}, t = "With this regard their currents turn awry" },
    { r = {"HAMLET"}, t = "And lose the name of action. Soft you now," },
    { r = {"HAMLET"}, t = "The fair Ophelia! Nymph, in thy orisons" },
    { r = {"HAMLET"}, t = "Be all my sins remember’d." },
    { r = {"OPHELIA"}, t = "Good my lord," },
    { r = {"OPHELIA"}, t = "How does your honour for this many a day?" },
    { r = {"HAMLET"}, t = "I humbly thank you; well, well, well." },
    { r = {"OPHELIA"}, t = "My lord, I have remembrances of yours" },
    { r = {"OPHELIA"}, t = "That I have longed long to re-deliver." },
    { r = {"OPHELIA"}, t = "I pray you, now receive them." },
    { r = {"HAMLET"}, t = "No, not I." },
    { r = {"HAMLET"}, t = "I never gave you aught." },
    { r = {"OPHELIA"}, t = "My honour’d lord, you know right well you did," },
    { r = {"OPHELIA"}, t = "And with them words of so sweet breath compos’d" },
    { r = {"OPHELIA"}, t = "As made the things more rich; their perfume lost," },
    { r = {"OPHELIA"}, t = "Take these again; for to the noble mind" },
    { r = {"OPHELIA"}, t = "Rich gifts wax poor when givers prove unkind." },
    { r = {"OPHELIA"}, t = "There, my lord." },
    { r = {"HAMLET"}, t = "Ha, ha! Are you honest?" },
    { r = {"OPHELIA"}, t = "My lord?" },
    { r = {"HAMLET"}, t = "Are you fair?" },
    { r = {"OPHELIA"}, t = "What means your lordship?" },
    { r = {"HAMLET"}, t = "That if you be honest and fair, your honesty should admit no discourse to your beauty." },
    { r = {"OPHELIA"}, t = "Could beauty, my lord, have better commerce than with honesty?" },
    { r = {"HAMLET"}, t = "Ay, truly; for the power of beauty will sooner transform honesty from what it is to a bawd than the force of honesty can translate beauty into his likeness." },
    { r = {"HAMLET"}, t = "This was sometime a paradox, but now the time gives it proof." },
    { r = {"HAMLET"}, t = "I did love you once." },
    { r = {"OPHELIA"}, t = "Indeed, my lord, you made me believe so." },
    { r = {"HAMLET"}, t = "You should not have believed me; for virtue cannot so inoculate our old stock but we shall relish of it." },
    { r = {"HAMLET"}, t = "I loved you not." },
    { r = {"OPHELIA"}, t = "I was the more deceived." },
    { r = {"HAMLET"}, t = "Get thee to a nunnery." },
    { r = {"HAMLET"}, t = "Why wouldst thou be a breeder of sinners?" },
    { r = {"HAMLET"}, t = "I am myself indifferent honest; but yet I could accuse me of such things that it were better my mother had not borne me." },
    { r = {"HAMLET"}, t = "I am very proud, revengeful, ambitious, with more offences at my beck than I have thoughts to put them in, imagination to give them shape, or time to act them in." },
    { r = {"HAMLET"}, t = "What should such fellows as I do crawling between earth and heaven?" },
    { r = {"HAMLET"}, t = "We are arrant knaves all, believe none of us." },
    { r = {"HAMLET"}, t = "Go thy ways to a nunnery." },
    { r = {"HAMLET"}, t = "Where’s your father?" },
    { r = {"OPHELIA"}, t = "At home, my lord." },
    { r = {"HAMLET"}, t = "Let the doors be shut upon him, that he may play the fool nowhere but in’s own house." },
    { r = {"HAMLET"}, t = "Farewell." },
    { r = {"OPHELIA"}, t = "O help him, you sweet heavens!" },
    { r = {"HAMLET"}, t = "If thou dost marry, I’ll give thee this plague for thy dowry." },
    { r = {"HAMLET"}, t = "Be thou as chaste as ice, as pure as snow, thou shalt not escape calumny." },
    { r = {"HAMLET"}, t = "Get thee to a nunnery, go: farewell." },
    { r = {"HAMLET"}, t = "Or if thou wilt needs marry, marry a fool; for wise men know well enough what monsters you make of them." },
    { r = {"HAMLET"}, t = "To a nunnery, go; and quickly too." },
    { r = {"HAMLET"}, t = "Farewell." },
    { r = {"OPHELIA"}, t = "O heavenly powers, restore him!" },
    { r = {"HAMLET"}, t = "I have heard of your paintings too, well enough." },
    { r = {"HAMLET"}, t = "God hath given you one face, and you make yourselves another." },
    { r = {"HAMLET"}, t = "You jig, you amble, and you lisp, and nickname God’s creatures, and make your wantonness your ignorance." },
    { r = {"HAMLET"}, t = "Go to, I’ll no more on’t, it hath made me mad." },
    { r = {"HAMLET"}, t = "I say, we will have no more marriages." },
    { r = {"HAMLET"}, t = "Those that are married already, all but one, shall live; the rest shall keep as they are." },
    { r = {"HAMLET"}, t = "To a nunnery, go." },
    { d = "Exit" },
    { r = {"OPHELIA"}, t = "O, what a noble mind is here o’erthrown!" },
    { r = {"OPHELIA"}, t = "The courtier’s, soldier’s, scholar’s, eye, tongue, sword," },
    { r = {"OPHELIA"}, t = "Th’expectancy and rose of the fair state," },
    { r = {"OPHELIA"}, t = "The glass of fashion and the mould of form," },
    { r = {"OPHELIA"}, t = "Th’observ’d of all observers, quite, quite down!" },
    { r = {"OPHELIA"}, t = "And I, of ladies most deject and wretched," },
    { r = {"OPHELIA"}, t = "That suck’d the honey of his music vows," },
    { r = {"OPHELIA"}, t = "Now see that noble and most sovereign reason," },
    { r = {"OPHELIA"}, t = "Like sweet bells jangled out of tune and harsh," },
    { r = {"OPHELIA"}, t = "That unmatch’d form and feature of blown youth" },
    { r = {"OPHELIA"}, t = "Blasted with ecstasy. O woe is me," },
    { r = {"OPHELIA"}, t = "T’have seen what I have seen, see what I see." },
    { d = "Enter King and Polonius" },
    { r = {"CLAUDIUS"}, t = "Love? His affections do not that way tend," },
    { r = {"CLAUDIUS"}, t = "Nor what he spake, though it lack’d form a little," },
    { r = {"CLAUDIUS"}, t = "Was not like madness. There’s something in his soul" },
    { r = {"CLAUDIUS"}, t = "O’er which his melancholy sits on brood," },
    { r = {"CLAUDIUS"}, t = "And I do doubt the hatch and the disclose" },
    { r = {"CLAUDIUS"}, t = "Will be some danger, which for to prevent," },
    { r = {"CLAUDIUS"}, t = "I have in quick determination" },
    { r = {"CLAUDIUS"}, t = "Thus set it down: he shall with speed to England" },
    { r = {"CLAUDIUS"}, t = "For the demand of our neglected tribute:" },
    { r = {"CLAUDIUS"}, t = "Haply the seas and countries different," },
    { r = {"CLAUDIUS"}, t = "With variable objects, shall expel" },
    { r = {"CLAUDIUS"}, t = "This something settled matter in his heart," },
    { r = {"CLAUDIUS"}, t = "Whereon his brains still beating puts him thus" },
    { r = {"CLAUDIUS"}, t = "From fashion of himself. What think you on’t?" },
    { r = {"POLONIUS"}, t = "It shall do well. But yet do I believe" },
    { r = {"POLONIUS"}, t = "The origin and commencement of his grief" },
    { r = {"POLONIUS"}, t = "Sprung from neglected love. How now, Ophelia?" },
    { r = {"POLONIUS"}, t = "You need not tell us what Lord Hamlet said," },
    { r = {"POLONIUS"}, t = "We heard it all. My lord, do as you please," },
    { r = {"POLONIUS"}, t = "But if you hold it fit, after the play," },
    { r = {"POLONIUS"}, t = "Let his queen mother all alone entreat him" },
    { r = {"POLONIUS"}, t = "To show his grief, let her be round with him," },
    { r = {"POLONIUS"}, t = "And I’ll be plac’d, so please you, in the ear" },
    { r = {"POLONIUS"}, t = "Of all their conference. If she find him not," },
    { r = {"POLONIUS"}, t = "To England send him; or confine him where" },
    { r = {"POLONIUS"}, t = "Your wisdom best shall think." },
    { r = {"CLAUDIUS"}, t = "It shall be so." },
    { r = {"CLAUDIUS"}, t = "Madness in great ones must not unwatch’d go." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 2. A hall in the Castle.", h = true },
    { d = "Enter Hamlet and certain Players" },
    { r = {"HAMLET"}, t = "Speak the speech, I pray you, as I pronounced it to you, trippingly on the tongue." },
    { r = {"HAMLET"}, t = "But if you mouth it, as many of your players do, I had as lief the town-crier spoke my lines." },
    { r = {"HAMLET"}, t = "Nor do not saw the air too much with your hand, thus, but use all gently; for in the very torrent, tempest, and, as I may say, whirlwind of passion, you must acquire and beget a temperance that may give it smoothness." },
    { r = {"HAMLET"}, t = "O, it offends me to the soul to hear a robustious periwig-pated fellow tear a passion to tatters, to very rags, to split the ears of the groundlings, who, for the most part, are capable of nothing but inexplicable dumb shows and noise." },
    { r = {"HAMLET"}, t = "I would have such a fellow whipped for o’erdoing Termagant." },
    { r = {"HAMLET"}, t = "It out-Herods Herod." },
    { r = {"HAMLET"}, t = "Pray you avoid it." },
    { r = {"FIRST PLAYER"}, t = "I warrant your honour." },
    { r = {"HAMLET"}, t = "Be not too tame neither; but let your own discretion be your tutor." },
    { r = {"HAMLET"}, t = "Suit the action to the word, the word to the action, with this special observance, that you o’erstep not the modesty of nature;" },
    { r = {"HAMLET"}, t = "for anything so overdone is from the purpose of playing, whose end, both at the first and now, was and is, to hold as ’twere the mirror up to nature;" },
    { r = {"HAMLET"}, t = "to show virtue her own feature, scorn her own image, and the very age and body of the time his form and pressure." },
    { r = {"HAMLET"}, t = "Now, this overdone, or come tardy off, though it make the unskilful laugh, cannot but make the judicious grieve; the censure of the which one must in your allowance o’erweigh a whole theatre of others." },
    { r = {"HAMLET"}, t = "O, there be players that I have seen play— and heard others praise, and that highly—" },
    { r = {"HAMLET"}, t = "not to speak it profanely, that, neither having the accent of Christians, nor the gait of Christian, pagan, nor man, have so strutted and bellowed that I have thought some of Nature’s journeymen had made men, and not made them well," },
    { r = {"HAMLET"}, t = "they imitated humanity so abominably." },
    { r = {"FIRST PLAYER"}, t = "I hope we have reform’d that indifferently with us, sir." },
    { r = {"HAMLET"}, t = "O reform it altogether." },
    { r = {"HAMLET"}, t = "And let those that play your clowns speak no more than is set down for them." },
    { r = {"HAMLET"}, t = "For there be of them that will themselves laugh, to set on some quantity of barren spectators to laugh too, though in the meantime some necessary question of the play be then to be considered." },
    { r = {"HAMLET"}, t = "That’s villainous, and shows a most pitiful ambition in the fool that uses it." },
    { r = {"HAMLET"}, t = "Go make you ready." },
    { d = "Exeunt Players" },
    { d = "Enter Polonius, Rosencrantz and Guildenstern" },
    { r = {"HAMLET"}, t = "How now, my lord?" },
    { r = {"HAMLET"}, t = "Will the King hear this piece of work?" },
    { r = {"POLONIUS"}, t = "And the Queen too, and that presently." },
    { r = {"HAMLET"}, t = "Bid the players make haste." },
    { d = "Exit Polonius" },
    { r = {"HAMLET"}, t = "Will you two help to hasten them?" },
    { r = {"HAMLET"}, t = "ROSENCRANTZ and GUILDENSTERN." },
    { r = {"HAMLET"}, t = "We will, my lord." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { r = {"HAMLET"}, t = "What ho, Horatio!" },
    { d = "Enter Horatio" },
    { r = {"HORATIO"}, t = "Here, sweet lord, at your service." },
    { r = {"HAMLET"}, t = "Horatio, thou art e’en as just a man" },
    { r = {"HAMLET"}, t = "As e’er my conversation cop’d withal." },
    { r = {"HORATIO"}, t = "O my dear lord." },
    { r = {"HAMLET"}, t = "Nay, do not think I flatter;" },
    { r = {"HAMLET"}, t = "For what advancement may I hope from thee," },
    { r = {"HAMLET"}, t = "That no revenue hast, but thy good spirits" },
    { r = {"HAMLET"}, t = "To feed and clothe thee? Why should the poor be flatter’d?" },
    { r = {"HAMLET"}, t = "No, let the candied tongue lick absurd pomp," },
    { r = {"HAMLET"}, t = "And crook the pregnant hinges of the knee" },
    { r = {"HAMLET"}, t = "Where thrift may follow fawning. Dost thou hear?" },
    { r = {"HAMLET"}, t = "Since my dear soul was mistress of her choice," },
    { r = {"HAMLET"}, t = "And could of men distinguish, her election" },
    { r = {"HAMLET"}, t = "Hath seal’d thee for herself. For thou hast been" },
    { r = {"HAMLET"}, t = "As one, in suffering all, that suffers nothing," },
    { r = {"HAMLET"}, t = "A man that Fortune’s buffets and rewards" },
    { r = {"HAMLET"}, t = "Hast ta’en with equal thanks. And blessed are those" },
    { r = {"HAMLET"}, t = "Whose blood and judgement are so well co-mingled" },
    { r = {"HAMLET"}, t = "That they are not a pipe for Fortune’s finger" },
    { r = {"HAMLET"}, t = "To sound what stop she please. Give me that man" },
    { r = {"HAMLET"}, t = "That is not passion’s slave, and I will wear him" },
    { r = {"HAMLET"}, t = "In my heart’s core, ay, in my heart of heart," },
    { r = {"HAMLET"}, t = "As I do thee. Something too much of this." },
    { r = {"HAMLET"}, t = "There is a play tonight before the King." },
    { r = {"HAMLET"}, t = "One scene of it comes near the circumstance" },
    { r = {"HAMLET"}, t = "Which I have told thee, of my father’s death." },
    { r = {"HAMLET"}, t = "I prithee, when thou see’st that act a-foot," },
    { r = {"HAMLET"}, t = "Even with the very comment of thy soul" },
    { r = {"HAMLET"}, t = "Observe mine uncle. If his occulted guilt" },
    { r = {"HAMLET"}, t = "Do not itself unkennel in one speech," },
    { r = {"HAMLET"}, t = "It is a damned ghost that we have seen;" },
    { r = {"HAMLET"}, t = "And my imaginations are as foul" },
    { r = {"HAMLET"}, t = "As Vulcan’s stithy. Give him heedful note;" },
    { r = {"HAMLET"}, t = "For I mine eyes will rivet to his face;" },
    { r = {"HAMLET"}, t = "And after we will both our judgements join" },
    { r = {"HAMLET"}, t = "In censure of his seeming." },
    { r = {"HORATIO"}, t = "Well, my lord." },
    { r = {"HORATIO"}, t = "If he steal aught the whilst this play is playing," },
    { r = {"HORATIO"}, t = "And ’scape detecting, I will pay the theft." },
    { r = {"HAMLET"}, t = "They are coming to the play. I must be idle." },
    { r = {"HAMLET"}, t = "Get you a place." },
    { d = "Danish march. A flourish. Enter King, Queen, Polonius, Ophelia, Rosencrantz, Guildenstern and others" },
    { r = {"CLAUDIUS"}, t = "How fares our cousin Hamlet?" },
    { r = {"HAMLET"}, t = "Excellent, i’ faith; of the chameleon’s dish: I eat the air, promise-crammed: you cannot feed capons so." },
    { r = {"CLAUDIUS"}, t = "I have nothing with this answer, Hamlet; these words are not mine." },
    { r = {"HAMLET"}, t = "No, nor mine now." },
    { r = {"HAMLET"}, t = "My lord, you play’d once i’ th’university, you say?", d = "To Polonius" },
    { r = {"POLONIUS"}, t = "That did I, my lord, and was accounted a good actor." },
    { r = {"HAMLET"}, t = "What did you enact?" },
    { r = {"POLONIUS"}, t = "I did enact Julius Caesar." },
    { r = {"POLONIUS"}, t = "I was kill’d i’ th’ Capitol." },
    { r = {"POLONIUS"}, t = "Brutus killed me." },
    { r = {"HAMLET"}, t = "It was a brute part of him to kill so capital a calf there." },
    { r = {"HAMLET"}, t = "Be the players ready?" },
    { r = {"ROSENCRANTZ"}, t = "Ay, my lord; they stay upon your patience." },
    { r = {"GERTRUDE"}, t = "Come hither, my dear Hamlet, sit by me." },
    { r = {"HAMLET"}, t = "No, good mother, here’s metal more attractive." },
    { r = {"POLONIUS"}, t = "O ho! do you mark that?", d = "To the King" },
    { r = {"HAMLET"}, t = "Lady, shall I lie in your lap?" },
    { d = "Lying down at Ophelia’s feet" },
    { r = {"OPHELIA"}, t = "No, my lord." },
    { r = {"HAMLET"}, t = "I mean, my head upon your lap?" },
    { r = {"OPHELIA"}, t = "Ay, my lord." },
    { r = {"HAMLET"}, t = "Do you think I meant country matters?" },
    { r = {"OPHELIA"}, t = "I think nothing, my lord." },
    { r = {"HAMLET"}, t = "That’s a fair thought to lie between maids’ legs." },
    { r = {"OPHELIA"}, t = "What is, my lord?" },
    { r = {"HAMLET"}, t = "Nothing." },
    { r = {"OPHELIA"}, t = "You are merry, my lord." },
    { r = {"HAMLET"}, t = "Who, I?" },
    { r = {"OPHELIA"}, t = "Ay, my lord." },
    { r = {"HAMLET"}, t = "O God, your only jig-maker!" },
    { r = {"HAMLET"}, t = "What should a man do but be merry?" },
    { r = {"HAMLET"}, t = "For look you how cheerfully my mother looks, and my father died within’s two hours." },
    { r = {"OPHELIA"}, t = "Nay, ’tis twice two months, my lord." },
    { r = {"HAMLET"}, t = "So long?" },
    { r = {"HAMLET"}, t = "Nay then, let the devil wear black, for I’ll have a suit of sables." },
    { r = {"HAMLET"}, t = "O heavens! die two months ago, and not forgotten yet?" },
    { r = {"HAMLET"}, t = "Then there’s hope a great man’s memory may outlive his life half a year." },
    { r = {"HAMLET"}, t = "But by’r lady, he must build churches then; or else shall he suffer not thinking on, with the hobby-horse, whose epitaph is ‘For, O, for O, the hobby-horse is forgot!’" },
    { d = "Trumpets sound. The dumb show enters" },
    { d = "Enter a King and a Queen very lovingly; the Queen embracing him and he her. She kneels, and makes show of protestation unto him. He takes her up, and declines his head upon her neck. Lays him down upon a bank of flowers. She, seeing him asleep, leaves him. Anon comes in a fellow, takes off his crown, kisses it, pours poison in the King’s ears, and exits. The Queen returns, finds the King dead, and makes passionate action. The Poisoner with some three or four Mutes, comes in again, seeming to lament with her. The dead body is carried away. The Poisoner woos the Queen with gifts. She seems loth and unwilling awhile, but in the end accepts his love" },
    { d = "Exeunt" },
    { r = {"OPHELIA"}, t = "What means this, my lord?" },
    { r = {"HAMLET"}, t = "Marry, this is miching mallecho; it means mischief." },
    { r = {"OPHELIA"}, t = "Belike this show imports the argument of the play." },
    { d = "Enter Prologue" },
    { r = {"HAMLET"}, t = "We shall know by this fellow: the players cannot keep counsel; they’ll tell all." },
    { r = {"OPHELIA"}, t = "Will they tell us what this show meant?" },
    { r = {"HAMLET"}, t = "Ay, or any show that you’ll show him." },
    { r = {"HAMLET"}, t = "Be not you ashamed to show, he’ll not shame to tell you what it means." },
    { r = {"OPHELIA"}, t = "You are naught, you are naught: I’ll mark the play." },
    { r = {"PROLOGUE"}, t = "For us, and for our tragedy," },
    { r = {"PROLOGUE"}, t = "Here stooping to your clemency," },
    { r = {"PROLOGUE"}, t = "We beg your hearing patiently." },
    { r = {"HAMLET"}, t = "Is this a prologue, or the posy of a ring?" },
    { r = {"OPHELIA"}, t = "’Tis brief, my lord." },
    { r = {"HAMLET"}, t = "As woman’s love." },
    { d = "Enter a King and a Queen" },
    { r = {"PLAYER KING"}, t = "Full thirty times hath Phoebus’ cart gone round" },
    { r = {"PLAYER KING"}, t = "Neptune’s salt wash and Tellus’ orbed ground," },
    { r = {"PLAYER KING"}, t = "And thirty dozen moons with borrow’d sheen" },
    { r = {"PLAYER KING"}, t = "About the world have times twelve thirties been," },
    { r = {"PLAYER KING"}, t = "Since love our hearts, and Hymen did our hands" },
    { r = {"PLAYER KING"}, t = "Unite commutual in most sacred bands." },
    { r = {"PLAYER QUEEN"}, t = "So many journeys may the sun and moon" },
    { r = {"PLAYER QUEEN"}, t = "Make us again count o’er ere love be done." },
    { r = {"PLAYER QUEEN"}, t = "But, woe is me, you are so sick of late," },
    { r = {"PLAYER QUEEN"}, t = "So far from cheer and from your former state," },
    { r = {"PLAYER QUEEN"}, t = "That I distrust you. Yet, though I distrust," },
    { r = {"PLAYER QUEEN"}, t = "Discomfort you, my lord, it nothing must:" },
    { r = {"PLAYER QUEEN"}, t = "For women’s fear and love holds quantity," },
    { r = {"PLAYER QUEEN"}, t = "In neither aught, or in extremity." },
    { r = {"PLAYER QUEEN"}, t = "Now what my love is, proof hath made you know," },
    { r = {"PLAYER QUEEN"}, t = "And as my love is siz’d, my fear is so." },
    { r = {"PLAYER QUEEN"}, t = "Where love is great, the littlest doubts are fear;" },
    { r = {"PLAYER QUEEN"}, t = "Where little fears grow great, great love grows there." },
    { r = {"PLAYER KING"}, t = "Faith, I must leave thee, love, and shortly too:" },
    { r = {"PLAYER KING"}, t = "My operant powers their functions leave to do:" },
    { r = {"PLAYER KING"}, t = "And thou shalt live in this fair world behind," },
    { r = {"PLAYER KING"}, t = "Honour’d, belov’d, and haply one as kind" },
    { r = {"PLAYER KING"}, t = "For husband shalt thou" },
    { r = {"PLAYER QUEEN"}, t = "O confound the rest." },
    { r = {"PLAYER QUEEN"}, t = "Such love must needs be treason in my breast." },
    { r = {"PLAYER QUEEN"}, t = "In second husband let me be accurst!" },
    { r = {"PLAYER QUEEN"}, t = "None wed the second but who kill’d the first." },
    { r = {"HAMLET"}, t = "Wormwood, wormwood.", d = "Aside" },
    { r = {"PLAYER QUEEN"}, t = "The instances that second marriage move" },
    { r = {"PLAYER QUEEN"}, t = "Are base respects of thrift, but none of love." },
    { r = {"PLAYER QUEEN"}, t = "A second time I kill my husband dead," },
    { r = {"PLAYER QUEEN"}, t = "When second husband kisses me in bed." },
    { r = {"PLAYER KING"}, t = "I do believe you think what now you speak;" },
    { r = {"PLAYER KING"}, t = "But what we do determine, oft we break." },
    { r = {"PLAYER KING"}, t = "Purpose is but the slave to memory," },
    { r = {"PLAYER KING"}, t = "Of violent birth, but poor validity:" },
    { r = {"PLAYER KING"}, t = "Which now, like fruit unripe, sticks on the tree," },
    { r = {"PLAYER KING"}, t = "But fall unshaken when they mellow be." },
    { r = {"PLAYER KING"}, t = "Most necessary ’tis that we forget" },
    { r = {"PLAYER KING"}, t = "To pay ourselves what to ourselves is debt." },
    { r = {"PLAYER KING"}, t = "What to ourselves in passion we propose," },
    { r = {"PLAYER KING"}, t = "The passion ending, doth the purpose lose." },
    { r = {"PLAYER KING"}, t = "The violence of either grief or joy" },
    { r = {"PLAYER KING"}, t = "Their own enactures with themselves destroy." },
    { r = {"PLAYER KING"}, t = "Where joy most revels, grief doth most lament;" },
    { r = {"PLAYER KING"}, t = "Grief joys, joy grieves, on slender accident." },
    { r = {"PLAYER KING"}, t = "This world is not for aye; nor ’tis not strange" },
    { r = {"PLAYER KING"}, t = "That even our loves should with our fortunes change," },
    { r = {"PLAYER KING"}, t = "For ’tis a question left us yet to prove," },
    { r = {"PLAYER KING"}, t = "Whether love lead fortune, or else fortune love." },
    { r = {"PLAYER KING"}, t = "The great man down, you mark his favourite flies," },
    { r = {"PLAYER KING"}, t = "The poor advanc’d makes friends of enemies;" },
    { r = {"PLAYER KING"}, t = "And hitherto doth love on fortune tend:" },
    { r = {"PLAYER KING"}, t = "For who not needs shall never lack a friend," },
    { r = {"PLAYER KING"}, t = "And who in want a hollow friend doth try," },
    { r = {"PLAYER KING"}, t = "Directly seasons him his enemy." },
    { r = {"PLAYER KING"}, t = "But orderly to end where I begun," },
    { r = {"PLAYER KING"}, t = "Our wills and fates do so contrary run" },
    { r = {"PLAYER KING"}, t = "That our devices still are overthrown." },
    { r = {"PLAYER KING"}, t = "Our thoughts are ours, their ends none of our own." },
    { r = {"PLAYER KING"}, t = "So think thou wilt no second husband wed," },
    { r = {"PLAYER KING"}, t = "But die thy thoughts when thy first lord is dead." },
    { r = {"PLAYER QUEEN"}, t = "Nor earth to me give food, nor heaven light," },
    { r = {"PLAYER QUEEN"}, t = "Sport and repose lock from me day and night," },
    { r = {"PLAYER QUEEN"}, t = "To desperation turn my trust and hope," },
    { r = {"PLAYER QUEEN"}, t = "An anchor’s cheer in prison be my scope," },
    { r = {"PLAYER QUEEN"}, t = "Each opposite that blanks the face of joy," },
    { r = {"PLAYER QUEEN"}, t = "Meet what I would have well, and it destroy!" },
    { r = {"PLAYER QUEEN"}, t = "Both here and hence pursue me lasting strife," },
    { r = {"PLAYER QUEEN"}, t = "If, once a widow, ever I be wife." },
    { r = {"HAMLET"}, t = "If she should break it now.", d = "To Ophelia" },
    { r = {"PLAYER KING"}, t = "’Tis deeply sworn. Sweet, leave me here awhile." },
    { r = {"PLAYER KING"}, t = "My spirits grow dull, and fain I would beguile" },
    { r = {"PLAYER KING"}, t = "The tedious day with sleep." },
    { r = {"PLAYER KING"}, d = "Sleeps", e = "/sleep" },
    { r = {"PLAYER QUEEN"}, t = "Sleep rock thy brain," },
    { r = {"PLAYER QUEEN"}, t = "And never come mischance between us twain." },
    { d = "Exit" },
    { r = {"HAMLET"}, t = "Madam, how like you this play?" },
    { r = {"GERTRUDE"}, t = "The lady protests too much, methinks." },
    { r = {"HAMLET"}, t = "O, but she’ll keep her word." },
    { r = {"CLAUDIUS"}, t = "Have you heard the argument? Is there no offence in’t?" },
    { r = {"HAMLET"}, t = "No, no, they do but jest, poison in jest; no offence i’ th’ world." },
    { r = {"CLAUDIUS"}, t = "What do you call the play?" },
    { r = {"HAMLET"}, t = "The Mousetrap." },
    { r = {"HAMLET"}, t = "Marry, how?" },
    { r = {"HAMLET"}, t = "Tropically." },
    { r = {"HAMLET"}, t = "This play is the image of a murder done in Vienna." },
    { r = {"HAMLET"}, t = "Gonzago is the Duke’s name, his wife Baptista: you shall see anon; ’tis a knavish piece of work: but what o’ that?" },
    { r = {"HAMLET"}, t = "Your majesty, and we that have free souls, it touches us not." },
    { r = {"HAMLET"}, t = "Let the gall’d jade wince; our withers are unwrung." },
    { d = "Enter Lucianus" },
    { r = {"HAMLET"}, t = "This is one Lucianus, nephew to the King." },
    { r = {"OPHELIA"}, t = "You are a good chorus, my lord." },
    { r = {"HAMLET"}, t = "I could interpret between you and your love, if I could see the puppets dallying." },
    { r = {"OPHELIA"}, t = "You are keen, my lord, you are keen." },
    { r = {"HAMLET"}, t = "It would cost you a groaning to take off my edge." },
    { r = {"OPHELIA"}, t = "Still better, and worse." },
    { r = {"HAMLET"}, t = "So you mistake your husbands.—Begin, murderer." },
    { r = {"HAMLET"}, t = "Pox, leave thy damnable faces, and begin." },
    { r = {"HAMLET"}, t = "Come, the croaking raven doth bellow for revenge." },
    { r = {"LUCIANUS"}, t = "Thoughts black, hands apt, drugs fit, and time agreeing," },
    { r = {"LUCIANUS"}, t = "Confederate season, else no creature seeing;" },
    { r = {"LUCIANUS"}, t = "Thou mixture rank, of midnight weeds collected," },
    { r = {"LUCIANUS"}, t = "With Hecate’s ban thrice blasted, thrice infected," },
    { r = {"LUCIANUS"}, t = "Thy natural magic and dire property" },
    { r = {"LUCIANUS"}, t = "On wholesome life usurp immediately." },
    { d = "Pours the poison into the sleeper’s ears" },
    { r = {"HAMLET"}, t = "He poisons him i’ th’garden for’s estate." },
    { r = {"HAMLET"}, t = "His name’s Gonzago." },
    { r = {"HAMLET"}, t = "The story is extant, and written in very choice Italian." },
    { r = {"HAMLET"}, t = "You shall see anon how the murderer gets the love of Gonzago’s wife." },
    { r = {"OPHELIA"}, t = "The King rises." },
    { r = {"HAMLET"}, t = "What, frighted with false fire?" },
    { r = {"GERTRUDE"}, t = "How fares my lord?" },
    { r = {"POLONIUS"}, t = "Give o’er the play." },
    { r = {"CLAUDIUS"}, t = "Give me some light. Away." },
    { r = {"ALL"}, t = "Lights, lights, lights." },
    { d = "Exeunt all but Hamlet and Horatio" },
    { r = {"HAMLET"}, t = "Why, let the strucken deer go weep," },
    { r = {"HAMLET"}, t = "The hart ungalled play;" },
    { r = {"HAMLET"}, t = "For some must watch, while some must sleep," },
    { r = {"HAMLET"}, t = "So runs the world away." },
    { r = {"HAMLET"}, t = "Would not this, sir, and a forest of feathers, if the rest of my fortunes turn Turk with me; with two Provincial roses on my razed shoes, get me a fellowship in a cry of players, sir?" },
    { r = {"HORATIO"}, t = "Half a share." },
    { r = {"HAMLET"}, t = "A whole one, I." },
    { r = {"HAMLET"}, t = "For thou dost know, O Damon dear," },
    { r = {"HAMLET"}, t = "This realm dismantled was" },
    { r = {"HAMLET"}, t = "Of Jove himself, and now reigns here" },
    { r = {"HAMLET"}, t = "A very, very—pajock." },
    { r = {"HORATIO"}, t = "You might have rhymed." },
    { r = {"HAMLET"}, t = "O good Horatio, I’ll take the ghost’s word for a thousand pound." },
    { r = {"HAMLET"}, t = "Didst perceive?" },
    { r = {"HORATIO"}, t = "Very well, my lord." },
    { r = {"HAMLET"}, t = "Upon the talk of the poisoning?" },
    { r = {"HORATIO"}, t = "I did very well note him." },
    { r = {"HAMLET"}, t = "Ah, ha! Come, some music. Come, the recorders." },
    { r = {"HAMLET"}, t = "For if the king like not the comedy," },
    { r = {"HAMLET"}, t = "Why then, belike he likes it not, perdie." },
    { r = {"HAMLET"}, t = "Come, some music." },
    { d = "Enter Rosencrantz and Guildenstern" },
    { r = {"GUILDENSTERN"}, t = "Good my lord, vouchsafe me a word with you." },
    { r = {"HAMLET"}, t = "Sir, a whole history." },
    { r = {"GUILDENSTERN"}, t = "The King, sir" },
    { r = {"HAMLET"}, t = "Ay, sir, what of him?" },
    { r = {"GUILDENSTERN"}, t = "Is in his retirement, marvellous distempered." },
    { r = {"HAMLET"}, t = "With drink, sir?" },
    { r = {"GUILDENSTERN"}, t = "No, my lord; rather with choler." },
    { r = {"HAMLET"}, t = "Your wisdom should show itself more richer to signify this to the doctor, for me to put him to his purgation would perhaps plunge him into far more choler." },
    { r = {"GUILDENSTERN"}, t = "Good my lord, put your discourse into some frame, and start not so wildly from my affair." },
    { r = {"HAMLET"}, t = "I am tame, sir, pronounce." },
    { r = {"GUILDENSTERN"}, t = "The Queen your mother, in most great affliction of spirit, hath sent me to you." },
    { r = {"HAMLET"}, t = "You are welcome." },
    { r = {"GUILDENSTERN"}, t = "Nay, good my lord, this courtesy is not of the right breed." },
    { r = {"GUILDENSTERN"}, t = "If it shall please you to make me a wholesome answer, I will do your mother’s commandment; if not, your pardon and my return shall be the end of my business." },
    { r = {"HAMLET"}, t = "Sir, I cannot." },
    { r = {"GUILDENSTERN"}, t = "What, my lord?" },
    { r = {"HAMLET"}, t = "Make you a wholesome answer." },
    { r = {"HAMLET"}, t = "My wit’s diseased." },
    { r = {"HAMLET"}, t = "But, sir, such answer as I can make, you shall command; or rather, as you say, my mother." },
    { r = {"HAMLET"}, t = "Therefore no more, but to the matter. My mother, you say," },
    { r = {"ROSENCRANTZ"}, t = "Then thus she says: your behaviour hath struck her into amazement and admiration." },
    { r = {"HAMLET"}, t = "O wonderful son, that can so stonish a mother!" },
    { r = {"HAMLET"}, t = "But is there no sequel at the heels of this mother’s admiration?" },
    { r = {"ROSENCRANTZ"}, t = "She desires to speak with you in her closet ere you go to bed." },
    { r = {"HAMLET"}, t = "We shall obey, were she ten times our mother." },
    { r = {"HAMLET"}, t = "Have you any further trade with us?" },
    { r = {"ROSENCRANTZ"}, t = "My lord, you once did love me." },
    { r = {"HAMLET"}, t = "And so I do still, by these pickers and stealers." },
    { r = {"ROSENCRANTZ"}, t = "Good my lord, what is your cause of distemper?" },
    { r = {"ROSENCRANTZ"}, t = "You do surely bar the door upon your own liberty if you deny your griefs to your friend." },
    { r = {"HAMLET"}, t = "Sir, I lack advancement." },
    { r = {"ROSENCRANTZ"}, t = "How can that be, when you have the voice of the King himself for your succession in Denmark?" },
    { r = {"HAMLET"}, t = "Ay, sir, but while the grass grows—the proverb is something musty." },
    { d = "Re-enter the Players with recorders" },
    { r = {"HAMLET"}, t = "O, the recorders." },
    { r = {"HAMLET"}, t = "Let me see one.—To withdraw with you, why do you go about to recover the wind of me, as if you would drive me into a toil?" },
    { r = {"GUILDENSTERN"}, t = "O my lord, if my duty be too bold, my love is too unmannerly." },
    { r = {"HAMLET"}, t = "I do not well understand that. Will you play upon this pipe?" },
    { r = {"GUILDENSTERN"}, t = "My lord, I cannot." },
    { r = {"HAMLET"}, t = "I pray you." },
    { r = {"GUILDENSTERN"}, t = "Believe me, I cannot." },
    { r = {"HAMLET"}, t = "I do beseech you." },
    { r = {"GUILDENSTERN"}, t = "I know no touch of it, my lord." },
    { r = {"HAMLET"}, t = "’Tis as easy as lying: govern these ventages with your finger and thumb, give it breath with your mouth, and it will discourse most eloquent music." },
    { r = {"HAMLET"}, t = "Look you, these are the stops." },
    { r = {"GUILDENSTERN"}, t = "But these cannot I command to any utterance of harmony." },
    { r = {"GUILDENSTERN"}, t = "I have not the skill." },
    { r = {"HAMLET"}, t = "Why, look you now, how unworthy a thing you make of me!" },
    { r = {"HAMLET"}, t = "You would play upon me; you would seem to know my stops; you would pluck out the heart of my mystery; you would sound me from my lowest note to the top of my compass;" },
    { r = {"HAMLET"}, t = "and there is much music, excellent voice, in this little organ, yet cannot you make it speak. ’Sblood, do you think I am easier to be played on than a pipe?" },
    { r = {"HAMLET"}, t = "Call me what instrument you will, though you can fret me, you cannot play upon me." },
    { d = "Enter Polonius" },
    { r = {"HAMLET"}, t = "God bless you, sir." },
    { r = {"POLONIUS"}, t = "My lord, the Queen would speak with you, and presently." },
    { r = {"HAMLET"}, t = "Do you see yonder cloud that’s almost in shape of a camel?" },
    { r = {"POLONIUS"}, t = "By the mass, and ’tis like a camel indeed." },
    { r = {"HAMLET"}, t = "Methinks it is like a weasel." },
    { r = {"POLONIUS"}, t = "It is backed like a weasel." },
    { r = {"HAMLET"}, t = "Or like a whale." },
    { r = {"POLONIUS"}, t = "Very like a whale." },
    { r = {"HAMLET"}, t = "Then will I come to my mother by and by.—They fool me to the top of my bent.—I will come by and by." },
    { r = {"POLONIUS"}, t = "I will say so." },
    { d = "Exit" },
    { r = {"HAMLET"}, t = "By and by is easily said. Leave me, friends." },
    { d = "Exeunt all but Hamlet" },
    { r = {"HAMLET"}, t = "’Tis now the very witching time of night," },
    { r = {"HAMLET"}, t = "When churchyards yawn, and hell itself breathes out" },
    { r = {"HAMLET"}, t = "Contagion to this world. Now could I drink hot blood," },
    { r = {"HAMLET"}, t = "And do such bitter business as the day" },
    { r = {"HAMLET"}, t = "Would quake to look on. Soft now, to my mother." },
    { r = {"HAMLET"}, t = "O heart, lose not thy nature; let not ever" },
    { r = {"HAMLET"}, t = "The soul of Nero enter this firm bosom:" },
    { r = {"HAMLET"}, t = "Let me be cruel, not unnatural." },
    { r = {"HAMLET"}, t = "I will speak daggers to her, but use none;" },
    { r = {"HAMLET"}, t = "My tongue and soul in this be hypocrites." },
    { r = {"HAMLET"}, t = "How in my words somever she be shent," },
    { r = {"HAMLET"}, t = "To give them seals never, my soul, consent." },
    { d = "Exit" },
    { d = "Act 3, Scene 3. A room in the Castle.", h = true },
    { d = "Enter King, Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "I like him not, nor stands it safe with us" },
    { r = {"CLAUDIUS"}, t = "To let his madness range. Therefore prepare you," },
    { r = {"CLAUDIUS"}, t = "I your commission will forthwith dispatch," },
    { r = {"CLAUDIUS"}, t = "And he to England shall along with you." },
    { r = {"CLAUDIUS"}, t = "The terms of our estate may not endure" },
    { r = {"CLAUDIUS"}, t = "Hazard so near us as doth hourly grow" },
    { r = {"CLAUDIUS"}, t = "Out of his lunacies." },
    { r = {"GUILDENSTERN"}, t = "We will ourselves provide." },
    { r = {"GUILDENSTERN"}, t = "Most holy and religious fear it is" },
    { r = {"GUILDENSTERN"}, t = "To keep those many many bodies safe" },
    { r = {"GUILDENSTERN"}, t = "That live and feed upon your Majesty." },
    { r = {"ROSENCRANTZ"}, t = "The single and peculiar life is bound" },
    { r = {"ROSENCRANTZ"}, t = "With all the strength and armour of the mind," },
    { r = {"ROSENCRANTZ"}, t = "To keep itself from ’noyance; but much more" },
    { r = {"ROSENCRANTZ"}, t = "That spirit upon whose weal depend and rest" },
    { r = {"ROSENCRANTZ"}, t = "The lives of many. The cease of majesty" },
    { r = {"ROSENCRANTZ"}, t = "Dies not alone; but like a gulf doth draw" },
    { r = {"ROSENCRANTZ"}, t = "What’s near it with it. It is a massy wheel" },
    { r = {"ROSENCRANTZ"}, t = "Fix’d on the summit of the highest mount," },
    { r = {"ROSENCRANTZ"}, t = "To whose huge spokes ten thousand lesser things" },
    { r = {"ROSENCRANTZ"}, t = "Are mortis’d and adjoin’d; which when it falls," },
    { r = {"ROSENCRANTZ"}, t = "Each small annexment, petty consequence," },
    { r = {"ROSENCRANTZ"}, t = "Attends the boist’rous ruin. Never alone" },
    { r = {"ROSENCRANTZ"}, t = "Did the King sigh, but with a general groan." },
    { r = {"CLAUDIUS"}, t = "Arm you, I pray you, to this speedy voyage;" },
    { r = {"CLAUDIUS"}, t = "For we will fetters put upon this fear," },
    { r = {"CLAUDIUS"}, t = "Which now goes too free-footed." },
    { r = {"CLAUDIUS"}, t = "ROSENCRANTZ and GUILDENSTERN." },
    { r = {"CLAUDIUS"}, t = "We will haste us." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { d = "Enter Polonius" },
    { r = {"POLONIUS"}, t = "My lord, he’s going to his mother’s closet." },
    { r = {"POLONIUS"}, t = "Behind the arras I’ll convey myself" },
    { r = {"POLONIUS"}, t = "To hear the process. I’ll warrant she’ll tax him home," },
    { r = {"POLONIUS"}, t = "And as you said, and wisely was it said," },
    { r = {"POLONIUS"}, t = "’Tis meet that some more audience than a mother," },
    { r = {"POLONIUS"}, t = "Since nature makes them partial, should o’erhear" },
    { r = {"POLONIUS"}, t = "The speech of vantage. Fare you well, my liege," },
    { r = {"POLONIUS"}, t = "I’ll call upon you ere you go to bed," },
    { r = {"POLONIUS"}, t = "And tell you what I know." },
    { r = {"CLAUDIUS"}, t = "Thanks, dear my lord." },
    { d = "Exit Polonius" },
    { r = {"CLAUDIUS"}, t = "O, my offence is rank, it smells to heaven;" },
    { r = {"CLAUDIUS"}, t = "It hath the primal eldest curse upon’t,—" },
    { r = {"CLAUDIUS"}, t = "A brother’s murder! Pray can I not," },
    { r = {"CLAUDIUS"}, t = "Though inclination be as sharp as will:" },
    { r = {"CLAUDIUS"}, t = "My stronger guilt defeats my strong intent," },
    { r = {"CLAUDIUS"}, t = "And, like a man to double business bound," },
    { r = {"CLAUDIUS"}, t = "I stand in pause where I shall first begin," },
    { r = {"CLAUDIUS"}, t = "And both neglect. What if this cursed hand" },
    { r = {"CLAUDIUS"}, t = "Were thicker than itself with brother’s blood," },
    { r = {"CLAUDIUS"}, t = "Is there not rain enough in the sweet heavens" },
    { r = {"CLAUDIUS"}, t = "To wash it white as snow? Whereto serves mercy" },
    { r = {"CLAUDIUS"}, t = "But to confront the visage of offence?" },
    { r = {"CLAUDIUS"}, t = "And what’s in prayer but this twofold force," },
    { r = {"CLAUDIUS"}, t = "To be forestalled ere we come to fall," },
    { r = {"CLAUDIUS"}, t = "Or pardon’d being down? Then I’ll look up." },
    { r = {"CLAUDIUS"}, t = "My fault is past. But O, what form of prayer" },
    { r = {"CLAUDIUS"}, t = "Can serve my turn? Forgive me my foul murder!" },
    { r = {"CLAUDIUS"}, t = "That cannot be; since I am still possess’d" },
    { r = {"CLAUDIUS"}, t = "Of those effects for which I did the murder,—" },
    { r = {"CLAUDIUS"}, t = "My crown, mine own ambition, and my queen." },
    { r = {"CLAUDIUS"}, t = "May one be pardon’d and retain th’offence?" },
    { r = {"CLAUDIUS"}, t = "In the corrupted currents of this world" },
    { r = {"CLAUDIUS"}, t = "Offence’s gilded hand may shove by justice," },
    { r = {"CLAUDIUS"}, t = "And oft ’tis seen the wicked prize itself" },
    { r = {"CLAUDIUS"}, t = "Buys out the law. But ’tis not so above;" },
    { r = {"CLAUDIUS"}, t = "There is no shuffling, there the action lies" },
    { r = {"CLAUDIUS"}, t = "In his true nature, and we ourselves compell’d" },
    { r = {"CLAUDIUS"}, t = "Even to the teeth and forehead of our faults," },
    { r = {"CLAUDIUS"}, t = "To give in evidence. What then? What rests?" },
    { r = {"CLAUDIUS"}, t = "Try what repentance can. What can it not?" },
    { r = {"CLAUDIUS"}, t = "Yet what can it, when one cannot repent?" },
    { r = {"CLAUDIUS"}, t = "O wretched state! O bosom black as death!" },
    { r = {"CLAUDIUS"}, t = "O limed soul, that struggling to be free," },
    { r = {"CLAUDIUS"}, t = "Art more engag’d! Help, angels! Make assay:" },
    { r = {"CLAUDIUS"}, t = "Bow, stubborn knees; and heart with strings of steel," },
    { r = {"CLAUDIUS"}, t = "Be soft as sinews of the new-born babe." },
    { r = {"CLAUDIUS"}, t = "All may be well." },
    { r = {"CLAUDIUS"}, d = "Retires and kneels", e = "/kneel" },
    { d = "Enter Hamlet" },
    { r = {"HAMLET"}, t = "Now might I do it pat, now he is praying." },
    { r = {"HAMLET"}, t = "And now I’ll do’t. And so he goes to heaven;" },
    { r = {"HAMLET"}, t = "And so am I reveng’d. That would be scann’d:" },
    { r = {"HAMLET"}, t = "A villain kills my father, and for that" },
    { r = {"HAMLET"}, t = "I, his sole son, do this same villain send" },
    { r = {"HAMLET"}, t = "To heaven. O, this is hire and salary, not revenge." },
    { r = {"HAMLET"}, t = "He took my father grossly, full of bread," },
    { r = {"HAMLET"}, t = "With all his crimes broad blown, as flush as May;" },
    { r = {"HAMLET"}, t = "And how his audit stands, who knows save heaven?" },
    { r = {"HAMLET"}, t = "But in our circumstance and course of thought," },
    { r = {"HAMLET"}, t = "’Tis heavy with him. And am I then reveng’d," },
    { r = {"HAMLET"}, t = "To take him in the purging of his soul," },
    { r = {"HAMLET"}, t = "When he is fit and season’d for his passage? No." },
    { r = {"HAMLET"}, t = "Up, sword, and know thou a more horrid hent:" },
    { r = {"HAMLET"}, t = "When he is drunk asleep; or in his rage," },
    { r = {"HAMLET"}, t = "Or in th’incestuous pleasure of his bed," },
    { r = {"HAMLET"}, t = "At gaming, swearing; or about some act" },
    { r = {"HAMLET"}, t = "That has no relish of salvation in’t," },
    { r = {"HAMLET"}, t = "Then trip him, that his heels may kick at heaven," },
    { r = {"HAMLET"}, t = "And that his soul may be as damn’d and black" },
    { r = {"HAMLET"}, t = "As hell, whereto it goes. My mother stays." },
    { r = {"HAMLET"}, t = "This physic but prolongs thy sickly days." },
    { d = "Exit" },
    { r = {"HAMLET"}, t = "The King rises and advances." },
    { r = {"CLAUDIUS"}, t = "My words fly up, my thoughts remain below." },
    { r = {"CLAUDIUS"}, t = "Words without thoughts never to heaven go." },
    { d = "Exit" },
    { d = "Act 3, Scene 4. Another room in the Castle.", h = true },
    { d = "Enter Queen and Polonius" },
    { r = {"POLONIUS"}, t = "He will come straight. Look you lay home to him," },
    { r = {"POLONIUS"}, t = "Tell him his pranks have been too broad to bear with," },
    { r = {"POLONIUS"}, t = "And that your Grace hath screen’d and stood between" },
    { r = {"POLONIUS"}, t = "Much heat and him. I’ll silence me e’en here." },
    { r = {"POLONIUS"}, t = "Pray you be round with him." },
    { r = {"HAMLET"}, t = "Mother, mother, mother.", d = "Within" },
    { r = {"GERTRUDE"}, t = "I’ll warrant you, Fear me not." },
    { r = {"GERTRUDE"}, t = "Withdraw, I hear him coming." },
    { d = "Polonius goes behind the arras" },
    { d = "Enter Hamlet" },
    { r = {"HAMLET"}, t = "Now, mother, what’s the matter?" },
    { r = {"GERTRUDE"}, t = "Hamlet, thou hast thy father much offended." },
    { r = {"HAMLET"}, t = "Mother, you have my father much offended." },
    { r = {"GERTRUDE"}, t = "Come, come, you answer with an idle tongue." },
    { r = {"HAMLET"}, t = "Go, go, you question with a wicked tongue." },
    { r = {"GERTRUDE"}, t = "Why, how now, Hamlet?" },
    { r = {"HAMLET"}, t = "What’s the matter now?" },
    { r = {"GERTRUDE"}, t = "Have you forgot me?" },
    { r = {"HAMLET"}, t = "No, by the rood, not so." },
    { r = {"HAMLET"}, t = "You are the Queen, your husband’s brother’s wife," },
    { r = {"HAMLET"}, t = "And, would it were not so. You are my mother." },
    { r = {"GERTRUDE"}, t = "Nay, then I’ll set those to you that can speak." },
    { r = {"HAMLET"}, t = "Come, come, and sit you down, you shall not budge." },
    { r = {"HAMLET"}, t = "You go not till I set you up a glass" },
    { r = {"HAMLET"}, t = "Where you may see the inmost part of you." },
    { r = {"GERTRUDE"}, t = "What wilt thou do? Thou wilt not murder me?" },
    { r = {"GERTRUDE"}, t = "Help, help, ho!" },
    { r = {"POLONIUS"}, t = "What, ho! help, help, help!", d = "Behind" },
    { r = {"HAMLET"}, t = "How now? A rat?" },
    { r = {"HAMLET"}, t = "Dead for a ducat, dead!", d = "Draws" },
    { d = "Makes a pass through the arras" },
    { r = {"POLONIUS"}, t = "O, I am slain!", d = "Behind" },
    { r = {"POLONIUS"}, d = "Falls and dies", e = "/lie", s = {"Feign Death"} },
    { r = {"GERTRUDE"}, t = "O me, what hast thou done?" },
    { r = {"HAMLET"}, t = "Nay, I know not. Is it the King?" },
    { d = "Draws forth Polonius" },
    { r = {"GERTRUDE"}, t = "O what a rash and bloody deed is this!" },
    { r = {"HAMLET"}, t = "A bloody deed. Almost as bad, good mother," },
    { r = {"HAMLET"}, t = "As kill a king and marry with his brother." },
    { r = {"GERTRUDE"}, t = "As kill a king?" },
    { r = {"HAMLET"}, t = "Ay, lady, ’twas my word." },
    { r = {"HAMLET"}, t = "Thou wretched, rash, intruding fool, farewell!", d = "To Polonius" },
    { r = {"HAMLET"}, t = "I took thee for thy better. Take thy fortune," },
    { r = {"HAMLET"}, t = "Thou find’st to be too busy is some danger.—" },
    { r = {"HAMLET"}, t = "Leave wringing of your hands. Peace, sit you down," },
    { r = {"HAMLET"}, t = "And let me wring your heart, for so I shall," },
    { r = {"HAMLET"}, t = "If it be made of penetrable stuff;" },
    { r = {"HAMLET"}, t = "If damned custom have not braz’d it so," },
    { r = {"HAMLET"}, t = "That it is proof and bulwark against sense." },
    { r = {"GERTRUDE"}, t = "What have I done, that thou dar’st wag thy tongue" },
    { r = {"GERTRUDE"}, t = "In noise so rude against me?" },
    { r = {"HAMLET"}, t = "Such an act" },
    { r = {"HAMLET"}, t = "That blurs the grace and blush of modesty," },
    { r = {"HAMLET"}, t = "Calls virtue hypocrite, takes off the rose" },
    { r = {"HAMLET"}, t = "From the fair forehead of an innocent love," },
    { r = {"HAMLET"}, t = "And sets a blister there. Makes marriage vows" },
    { r = {"HAMLET"}, t = "As false as dicers’ oaths. O such a deed" },
    { r = {"HAMLET"}, t = "As from the body of contraction plucks" },
    { r = {"HAMLET"}, t = "The very soul, and sweet religion makes" },
    { r = {"HAMLET"}, t = "A rhapsody of words. Heaven’s face doth glow," },
    { r = {"HAMLET"}, t = "Yea this solidity and compound mass," },
    { r = {"HAMLET"}, t = "With tristful visage, as against the doom," },
    { r = {"HAMLET"}, t = "Is thought-sick at the act." },
    { r = {"GERTRUDE"}, t = "Ay me, what act," },
    { r = {"GERTRUDE"}, t = "That roars so loud, and thunders in the index?" },
    { r = {"HAMLET"}, t = "Look here upon this picture, and on this," },
    { r = {"HAMLET"}, t = "The counterfeit presentment of two brothers." },
    { r = {"HAMLET"}, t = "See what a grace was seated on this brow," },
    { r = {"HAMLET"}, t = "Hyperion’s curls, the front of Jove himself," },
    { r = {"HAMLET"}, t = "An eye like Mars, to threaten and command," },
    { r = {"HAMLET"}, t = "A station like the herald Mercury" },
    { r = {"HAMLET"}, t = "New lighted on a heaven-kissing hill:" },
    { r = {"HAMLET"}, t = "A combination and a form indeed," },
    { r = {"HAMLET"}, t = "Where every god did seem to set his seal," },
    { r = {"HAMLET"}, t = "To give the world assurance of a man." },
    { r = {"HAMLET"}, t = "This was your husband. Look you now what follows." },
    { r = {"HAMLET"}, t = "Here is your husband, like a mildew’d ear" },
    { r = {"HAMLET"}, t = "Blasting his wholesome brother. Have you eyes?" },
    { r = {"HAMLET"}, t = "Could you on this fair mountain leave to feed," },
    { r = {"HAMLET"}, t = "And batten on this moor? Ha! have you eyes?" },
    { r = {"HAMLET"}, t = "You cannot call it love; for at your age" },
    { r = {"HAMLET"}, t = "The hey-day in the blood is tame, it’s humble," },
    { r = {"HAMLET"}, t = "And waits upon the judgement: and what judgement" },
    { r = {"HAMLET"}, t = "Would step from this to this? Sense sure you have," },
    { r = {"HAMLET"}, t = "Else could you not have motion; but sure that sense" },
    { r = {"HAMLET"}, t = "Is apoplex’d, for madness would not err" },
    { r = {"HAMLET"}, t = "Nor sense to ecstacy was ne’er so thrall’d" },
    { r = {"HAMLET"}, t = "But it reserv’d some quantity of choice" },
    { r = {"HAMLET"}, t = "To serve in such a difference. What devil was’t" },
    { r = {"HAMLET"}, t = "That thus hath cozen’d you at hoodman-blind?" },
    { r = {"HAMLET"}, t = "Eyes without feeling, feeling without sight," },
    { r = {"HAMLET"}, t = "Ears without hands or eyes, smelling sans all," },
    { r = {"HAMLET"}, t = "Or but a sickly part of one true sense" },
    { r = {"HAMLET"}, t = "Could not so mope. O shame! where is thy blush?" },
    { r = {"HAMLET"}, t = "Rebellious hell," },
    { r = {"HAMLET"}, t = "If thou canst mutine in a matron’s bones," },
    { r = {"HAMLET"}, t = "To flaming youth let virtue be as wax," },
    { r = {"HAMLET"}, t = "And melt in her own fire. Proclaim no shame" },
    { r = {"HAMLET"}, t = "When the compulsive ardour gives the charge," },
    { r = {"HAMLET"}, t = "Since frost itself as actively doth burn," },
    { r = {"HAMLET"}, t = "And reason panders will." },
    { r = {"GERTRUDE"}, t = "O Hamlet, speak no more." },
    { r = {"GERTRUDE"}, t = "Thou turn’st mine eyes into my very soul," },
    { r = {"GERTRUDE"}, t = "And there I see such black and grained spots" },
    { r = {"GERTRUDE"}, t = "As will not leave their tinct." },
    { r = {"HAMLET"}, t = "Nay, but to live" },
    { r = {"HAMLET"}, t = "In the rank sweat of an enseamed bed," },
    { r = {"HAMLET"}, t = "Stew’d in corruption, honeying and making love" },
    { r = {"HAMLET"}, t = "Over the nasty sty." },
    { r = {"GERTRUDE"}, t = "O speak to me no more;" },
    { r = {"GERTRUDE"}, t = "These words like daggers enter in mine ears;" },
    { r = {"GERTRUDE"}, t = "No more, sweet Hamlet." },
    { r = {"HAMLET"}, t = "A murderer and a villain;" },
    { r = {"HAMLET"}, t = "A slave that is not twentieth part the tithe" },
    { r = {"HAMLET"}, t = "Of your precedent lord. A vice of kings," },
    { r = {"HAMLET"}, t = "A cutpurse of the empire and the rule," },
    { r = {"HAMLET"}, t = "That from a shelf the precious diadem stole" },
    { r = {"HAMLET"}, t = "And put it in his pocket!" },
    { r = {"GERTRUDE"}, t = "No more." },
    { r = {"HAMLET"}, t = "A king of shreds and patches!" },
    { r = {"GHOST"}, d = "Enter Ghost", s = {"Fade"} },
    { r = {"HAMLET"}, t = "Save me and hover o’er me with your wings," },
    { r = {"HAMLET"}, t = "You heavenly guards! What would your gracious figure?" },
    { r = {"GERTRUDE"}, t = "Alas, he’s mad." },
    { r = {"HAMLET"}, t = "Do you not come your tardy son to chide," },
    { r = {"HAMLET"}, t = "That, laps’d in time and passion, lets go by" },
    { r = {"HAMLET"}, t = "The important acting of your dread command?" },
    { r = {"HAMLET"}, t = "O say!" },
    { r = {"GHOST"}, t = "Do not forget. This visitation" },
    { r = {"GHOST"}, t = "Is but to whet thy almost blunted purpose." },
    { r = {"GHOST"}, t = "But look, amazement on thy mother sits." },
    { r = {"GHOST"}, t = "O step between her and her fighting soul." },
    { r = {"GHOST"}, t = "Conceit in weakest bodies strongest works." },
    { r = {"GHOST"}, t = "Speak to her, Hamlet." },
    { r = {"HAMLET"}, t = "How is it with you, lady?" },
    { r = {"GERTRUDE"}, t = "Alas, how is’t with you," },
    { r = {"GERTRUDE"}, t = "That you do bend your eye on vacancy," },
    { r = {"GERTRUDE"}, t = "And with the incorporal air do hold discourse?" },
    { r = {"GERTRUDE"}, t = "Forth at your eyes your spirits wildly peep," },
    { r = {"GERTRUDE"}, t = "And, as the sleeping soldiers in the alarm," },
    { r = {"GERTRUDE"}, t = "Your bedded hairs, like life in excrements," },
    { r = {"GERTRUDE"}, t = "Start up and stand an end. O gentle son," },
    { r = {"GERTRUDE"}, t = "Upon the heat and flame of thy distemper" },
    { r = {"GERTRUDE"}, t = "Sprinkle cool patience. Whereon do you look?" },
    { r = {"HAMLET"}, t = "On him, on him! Look you how pale he glares," },
    { r = {"HAMLET"}, t = "His form and cause conjoin’d, preaching to stones," },
    { r = {"HAMLET"}, t = "Would make them capable.—Do not look upon me," },
    { r = {"HAMLET"}, t = "Lest with this piteous action you convert" },
    { r = {"HAMLET"}, t = "My stern effects. Then what I have to do" },
    { r = {"HAMLET"}, t = "Will want true colour; tears perchance for blood." },
    { r = {"GERTRUDE"}, t = "To whom do you speak this?" },
    { r = {"HAMLET"}, t = "Do you see nothing there?" },
    { r = {"GERTRUDE"}, t = "Nothing at all; yet all that is I see." },
    { r = {"HAMLET"}, t = "Nor did you nothing hear?" },
    { r = {"GERTRUDE"}, t = "No, nothing but ourselves." },
    { r = {"HAMLET"}, t = "Why, look you there! look how it steals away!" },
    { r = {"HAMLET"}, t = "My father, in his habit as he liv’d!" },
    { r = {"HAMLET"}, t = "Look where he goes even now out at the portal." },
    { r = {"GHOST"}, d = "Exit Ghost", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"GERTRUDE"}, t = "This is the very coinage of your brain." },
    { r = {"GERTRUDE"}, t = "This bodiless creation ecstasy" },
    { r = {"GERTRUDE"}, t = "Is very cunning in." },
    { r = {"HAMLET"}, t = "Ecstasy!" },
    { r = {"HAMLET"}, t = "My pulse as yours doth temperately keep time," },
    { r = {"HAMLET"}, t = "And makes as healthful music. It is not madness" },
    { r = {"HAMLET"}, t = "That I have utter’d. Bring me to the test," },
    { r = {"HAMLET"}, t = "And I the matter will re-word; which madness" },
    { r = {"HAMLET"}, t = "Would gambol from. Mother, for love of grace," },
    { r = {"HAMLET"}, t = "Lay not that flattering unction to your soul" },
    { r = {"HAMLET"}, t = "That not your trespass, but my madness speaks." },
    { r = {"HAMLET"}, t = "It will but skin and film the ulcerous place," },
    { r = {"HAMLET"}, t = "Whilst rank corruption, mining all within," },
    { r = {"HAMLET"}, t = "Infects unseen. Confess yourself to heaven," },
    { r = {"HAMLET"}, t = "Repent what’s past, avoid what is to come;" },
    { r = {"HAMLET"}, t = "And do not spread the compost on the weeds," },
    { r = {"HAMLET"}, t = "To make them ranker. Forgive me this my virtue;" },
    { r = {"HAMLET"}, t = "For in the fatness of these pursy times" },
    { r = {"HAMLET"}, t = "Virtue itself of vice must pardon beg," },
    { r = {"HAMLET"}, t = "Yea, curb and woo for leave to do him good." },
    { r = {"GERTRUDE"}, t = "O Hamlet, thou hast cleft my heart in twain." },
    { r = {"HAMLET"}, t = "O throw away the worser part of it," },
    { r = {"HAMLET"}, t = "And live the purer with the other half." },
    { r = {"HAMLET"}, t = "Good night. But go not to mine uncle’s bed." },
    { r = {"HAMLET"}, t = "Assume a virtue, if you have it not." },
    { r = {"HAMLET"}, t = "That monster custom, who all sense doth eat," },
    { r = {"HAMLET"}, t = "Of habits evil, is angel yet in this," },
    { r = {"HAMLET"}, t = "That to the use of actions fair and good" },
    { r = {"HAMLET"}, t = "He likewise gives a frock or livery" },
    { r = {"HAMLET"}, t = "That aptly is put on. Refrain tonight," },
    { r = {"HAMLET"}, t = "And that shall lend a kind of easiness" },
    { r = {"HAMLET"}, t = "To the next abstinence. The next more easy;" },
    { r = {"HAMLET"}, t = "For use almost can change the stamp of nature," },
    { r = {"HAMLET"}, t = "And either curb the devil, or throw him out" },
    { r = {"HAMLET"}, t = "With wondrous potency. Once more, good night," },
    { r = {"HAMLET"}, t = "And when you are desirous to be bles’d," },
    { r = {"HAMLET"}, t = "I’ll blessing beg of you. For this same lord" },
    { r = {"HAMLET"}, t = "I do repent; but heaven hath pleas’d it so,", d = "Pointing to Polonius" },
    { r = {"HAMLET"}, t = "To punish me with this, and this with me," },
    { r = {"HAMLET"}, t = "That I must be their scourge and minister." },
    { r = {"HAMLET"}, t = "I will bestow him, and will answer well" },
    { r = {"HAMLET"}, t = "The death I gave him. So again, good night." },
    { r = {"HAMLET"}, t = "I must be cruel, only to be kind:" },
    { r = {"HAMLET"}, t = "Thus bad begins, and worse remains behind." },
    { r = {"HAMLET"}, t = "One word more, good lady." },
    { r = {"GERTRUDE"}, t = "What shall I do?" },
    { r = {"HAMLET"}, t = "Not this, by no means, that I bid you do:" },
    { r = {"HAMLET"}, t = "Let the bloat King tempt you again to bed," },
    { r = {"HAMLET"}, t = "Pinch wanton on your cheek, call you his mouse," },
    { r = {"HAMLET"}, t = "And let him, for a pair of reechy kisses," },
    { r = {"HAMLET"}, t = "Or paddling in your neck with his damn’d fingers," },
    { r = {"HAMLET"}, t = "Make you to ravel all this matter out," },
    { r = {"HAMLET"}, t = "That I essentially am not in madness," },
    { r = {"HAMLET"}, t = "But mad in craft. ’Twere good you let him know," },
    { r = {"HAMLET"}, t = "For who that’s but a queen, fair, sober, wise," },
    { r = {"HAMLET"}, t = "Would from a paddock, from a bat, a gib," },
    { r = {"HAMLET"}, t = "Such dear concernings hide? Who would do so?" },
    { r = {"HAMLET"}, t = "No, in despite of sense and secrecy," },
    { r = {"HAMLET"}, t = "Unpeg the basket on the house’s top," },
    { r = {"HAMLET"}, t = "Let the birds fly, and like the famous ape," },
    { r = {"HAMLET"}, t = "To try conclusions, in the basket creep" },
    { r = {"HAMLET"}, t = "And break your own neck down." },
    { r = {"GERTRUDE"}, t = "Be thou assur’d, if words be made of breath," },
    { r = {"GERTRUDE"}, t = "And breath of life, I have no life to breathe" },
    { r = {"GERTRUDE"}, t = "What thou hast said to me." },
    { r = {"HAMLET"}, t = "I must to England, you know that?" },
    { r = {"GERTRUDE"}, t = "Alack," },
    { r = {"GERTRUDE"}, t = "I had forgot. ’Tis so concluded on." },
    { r = {"HAMLET"}, t = "There’s letters seal’d: and my two schoolfellows," },
    { r = {"HAMLET"}, t = "Whom I will trust as I will adders fang’d,—" },
    { r = {"HAMLET"}, t = "They bear the mandate, they must sweep my way" },
    { r = {"HAMLET"}, t = "And marshal me to knavery. Let it work;" },
    { r = {"HAMLET"}, t = "For ’tis the sport to have the enginer" },
    { r = {"HAMLET"}, t = "Hoist with his own petard, and ’t shall go hard" },
    { r = {"HAMLET"}, t = "But I will delve one yard below their mines" },
    { r = {"HAMLET"}, t = "And blow them at the moon. O, ’tis most sweet," },
    { r = {"HAMLET"}, t = "When in one line two crafts directly meet." },
    { r = {"HAMLET"}, t = "This man shall set me packing." },
    { r = {"HAMLET"}, t = "I’ll lug the guts into the neighbour room." },
    { r = {"HAMLET"}, t = "Mother, good night. Indeed, this counsellor" },
    { r = {"HAMLET"}, t = "Is now most still, most secret, and most grave," },
    { r = {"HAMLET"}, t = "Who was in life a foolish prating knave." },
    { r = {"HAMLET"}, t = "Come, sir, to draw toward an end with you." },
    { r = {"HAMLET"}, t = "Good night, mother." },
    { d = "Exit Hamlet dragging out Polonius" },
    { d = "Act 4, Scene 1. A room in the Castle.", h = true },
    { d = "Enter King, Queen, Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "There’s matter in these sighs. These profound heaves" },
    { r = {"CLAUDIUS"}, t = "You must translate; ’tis fit we understand them." },
    { r = {"CLAUDIUS"}, t = "Where is your son?" },
    { r = {"GERTRUDE"}, t = "Bestow this place on us a little while." },
    { d = "To Rosencrantz and Guildenstern, who go out" },
    { r = {"GERTRUDE"}, t = "Ah, my good lord, what have I seen tonight!" },
    { r = {"CLAUDIUS"}, t = "What, Gertrude? How does Hamlet?" },
    { r = {"GERTRUDE"}, t = "Mad as the sea and wind, when both contend" },
    { r = {"GERTRUDE"}, t = "Which is the mightier. In his lawless fit" },
    { r = {"GERTRUDE"}, t = "Behind the arras hearing something stir," },
    { r = {"GERTRUDE"}, t = "Whips out his rapier, cries ‘A rat, a rat!’" },
    { r = {"GERTRUDE"}, t = "And in this brainish apprehension kills" },
    { r = {"GERTRUDE"}, t = "The unseen good old man." },
    { r = {"CLAUDIUS"}, t = "O heavy deed!" },
    { r = {"CLAUDIUS"}, t = "It had been so with us, had we been there." },
    { r = {"CLAUDIUS"}, t = "His liberty is full of threats to all;" },
    { r = {"CLAUDIUS"}, t = "To you yourself, to us, to everyone." },
    { r = {"CLAUDIUS"}, t = "Alas, how shall this bloody deed be answer’d?" },
    { r = {"CLAUDIUS"}, t = "It will be laid to us, whose providence" },
    { r = {"CLAUDIUS"}, t = "Should have kept short, restrain’d, and out of haunt" },
    { r = {"CLAUDIUS"}, t = "This mad young man. But so much was our love" },
    { r = {"CLAUDIUS"}, t = "We would not understand what was most fit," },
    { r = {"CLAUDIUS"}, t = "But like the owner of a foul disease," },
    { r = {"CLAUDIUS"}, t = "To keep it from divulging, let it feed" },
    { r = {"CLAUDIUS"}, t = "Even on the pith of life. Where is he gone?" },
    { r = {"GERTRUDE"}, t = "To draw apart the body he hath kill’d," },
    { r = {"GERTRUDE"}, t = "O’er whom his very madness, like some ore" },
    { r = {"GERTRUDE"}, t = "Among a mineral of metals base," },
    { r = {"GERTRUDE"}, t = "Shows itself pure. He weeps for what is done." },
    { r = {"CLAUDIUS"}, t = "O Gertrude, come away!" },
    { r = {"CLAUDIUS"}, t = "The sun no sooner shall the mountains touch" },
    { r = {"CLAUDIUS"}, t = "But we will ship him hence, and this vile deed" },
    { r = {"CLAUDIUS"}, t = "We must with all our majesty and skill" },
    { r = {"CLAUDIUS"}, t = "Both countenance and excuse.—Ho, Guildenstern!" },
    { d = "Re-enter Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "Friends both, go join you with some further aid:" },
    { r = {"CLAUDIUS"}, t = "Hamlet in madness hath Polonius slain," },
    { r = {"CLAUDIUS"}, t = "And from his mother’s closet hath he dragg’d him." },
    { r = {"CLAUDIUS"}, t = "Go seek him out, speak fair, and bring the body" },
    { r = {"CLAUDIUS"}, t = "Into the chapel. I pray you haste in this." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "Come, Gertrude, we’ll call up our wisest friends," },
    { r = {"CLAUDIUS"}, t = "And let them know both what we mean to do" },
    { r = {"CLAUDIUS"}, t = "And what’s untimely done, so haply slander," },
    { r = {"CLAUDIUS"}, t = "Whose whisper o’er the world’s diameter," },
    { r = {"CLAUDIUS"}, t = "As level as the cannon to his blank," },
    { r = {"CLAUDIUS"}, t = "Transports his poison’d shot, may miss our name," },
    { r = {"CLAUDIUS"}, t = "And hit the woundless air. O, come away!" },
    { r = {"CLAUDIUS"}, t = "My soul is full of discord and dismay." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 2. Another room in the Castle.", h = true },
    { d = "Enter Hamlet" },
    { r = {"HAMLET"}, t = "Safely stowed." },
    { r = {"HAMLET"}, t = "ROSENCRANTZ and GUILDENSTERN." },
    { r = {"HAMLET"}, t = "Hamlet! Lord Hamlet!", d = "Within" },
    { r = {"HAMLET"}, t = "What noise? Who calls on Hamlet? O, here they come." },
    { d = "Enter Rosencrantz and Guildenstern" },
    { r = {"ROSENCRANTZ"}, t = "What have you done, my lord, with the dead body?" },
    { r = {"HAMLET"}, t = "Compounded it with dust, whereto ’tis kin." },
    { r = {"ROSENCRANTZ"}, t = "Tell us where ’tis, that we may take it thence," },
    { r = {"ROSENCRANTZ"}, t = "And bear it to the chapel." },
    { r = {"HAMLET"}, t = "Do not believe it." },
    { r = {"ROSENCRANTZ"}, t = "Believe what?" },
    { r = {"HAMLET"}, t = "That I can keep your counsel, and not mine own." },
    { r = {"HAMLET"}, t = "Besides, to be demanded of a sponge—what replication should be made by the son of a king?" },
    { r = {"ROSENCRANTZ"}, t = "Take you me for a sponge, my lord?" },
    { r = {"HAMLET"}, t = "Ay, sir; that soaks up the King’s countenance, his rewards, his authorities." },
    { r = {"HAMLET"}, t = "But such officers do the King best service in the end: he keeps them, like an ape, in the corner of his jaw; first mouthed, to be last swallowed: when he needs what you have gleaned, it is but squeezing you, and, sponge, you shall be dry again." },
    { r = {"ROSENCRANTZ"}, t = "I understand you not, my lord." },
    { r = {"HAMLET"}, t = "I am glad of it. A knavish speech sleeps in a foolish ear." },
    { r = {"ROSENCRANTZ"}, t = "My lord, you must tell us where the body is and go with us to the King." },
    { r = {"HAMLET"}, t = "The body is with the King, but the King is not with the body." },
    { r = {"HAMLET"}, t = "The King is a thing" },
    { r = {"GUILDENSTERN"}, t = "A thing, my lord!" },
    { r = {"HAMLET"}, t = "Of nothing. Bring me to him. Hide fox, and all after." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 3. Another room in the Castle.", h = true },
    { d = "Enter King, attended" },
    { r = {"CLAUDIUS"}, t = "I have sent to seek him and to find the body." },
    { r = {"CLAUDIUS"}, t = "How dangerous is it that this man goes loose!" },
    { r = {"CLAUDIUS"}, t = "Yet must not we put the strong law on him:" },
    { r = {"CLAUDIUS"}, t = "He’s lov’d of the distracted multitude," },
    { r = {"CLAUDIUS"}, t = "Who like not in their judgement, but their eyes;" },
    { r = {"CLAUDIUS"}, t = "And where ’tis so, th’offender’s scourge is weigh’d," },
    { r = {"CLAUDIUS"}, t = "But never the offence. To bear all smooth and even," },
    { r = {"CLAUDIUS"}, t = "This sudden sending him away must seem" },
    { r = {"CLAUDIUS"}, t = "Deliberate pause. Diseases desperate grown" },
    { r = {"CLAUDIUS"}, t = "By desperate appliance are reliev’d," },
    { r = {"CLAUDIUS"}, t = "Or not at all." },
    { d = "Enter Rosencrantz" },
    { r = {"CLAUDIUS"}, t = "How now? What hath befall’n?" },
    { r = {"ROSENCRANTZ"}, t = "Where the dead body is bestow’d, my lord," },
    { r = {"ROSENCRANTZ"}, t = "We cannot get from him." },
    { r = {"CLAUDIUS"}, t = "But where is he?" },
    { r = {"ROSENCRANTZ"}, t = "Without, my lord, guarded, to know your pleasure." },
    { r = {"CLAUDIUS"}, t = "Bring him before us." },
    { r = {"ROSENCRANTZ"}, t = "Ho, Guildenstern! Bring in my lord." },
    { d = "Enter Hamlet and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "Now, Hamlet, where’s Polonius?" },
    { r = {"HAMLET"}, t = "At supper." },
    { r = {"CLAUDIUS"}, t = "At supper? Where?" },
    { r = {"HAMLET"}, t = "Not where he eats, but where he is eaten." },
    { r = {"HAMLET"}, t = "A certain convocation of politic worms are e’en at him." },
    { r = {"HAMLET"}, t = "Your worm is your only emperor for diet." },
    { r = {"HAMLET"}, t = "We fat all creatures else to fat us, and we fat ourselves for maggots." },
    { r = {"HAMLET"}, t = "Your fat king and your lean beggar is but variable service,—two dishes, but to one table." },
    { r = {"HAMLET"}, t = "That’s the end." },
    { r = {"CLAUDIUS"}, t = "Alas, alas!" },
    { r = {"HAMLET"}, t = "A man may fish with the worm that hath eat of a king, and eat of the fish that hath fed of that worm." },
    { r = {"CLAUDIUS"}, t = "What dost thou mean by this?" },
    { r = {"HAMLET"}, t = "Nothing but to show you how a king may go a progress through the guts of a beggar." },
    { r = {"CLAUDIUS"}, t = "Where is Polonius?" },
    { r = {"HAMLET"}, t = "In heaven." },
    { r = {"HAMLET"}, t = "Send thither to see." },
    { r = {"HAMLET"}, t = "If your messenger find him not there, seek him i’ th’other place yourself." },
    { r = {"HAMLET"}, t = "But indeed, if you find him not within this month, you shall nose him as you go up the stairs into the lobby." },
    { r = {"CLAUDIUS"}, t = "Go seek him there.", d = "To some Attendants" },
    { r = {"HAMLET"}, t = "He will stay till you come." },
    { d = "Exeunt Attendants" },
    { r = {"CLAUDIUS"}, t = "Hamlet, this deed, for thine especial safety,—" },
    { r = {"CLAUDIUS"}, t = "Which we do tender, as we dearly grieve" },
    { r = {"CLAUDIUS"}, t = "For that which thou hast done,—must send thee hence" },
    { r = {"CLAUDIUS"}, t = "With fiery quickness. Therefore prepare thyself;" },
    { r = {"CLAUDIUS"}, t = "The bark is ready, and the wind at help," },
    { r = {"CLAUDIUS"}, t = "Th’associates tend, and everything is bent" },
    { r = {"CLAUDIUS"}, t = "For England." },
    { r = {"HAMLET"}, t = "For England?" },
    { r = {"CLAUDIUS"}, t = "Ay, Hamlet." },
    { r = {"HAMLET"}, t = "Good." },
    { r = {"CLAUDIUS"}, t = "So is it, if thou knew’st our purposes." },
    { r = {"HAMLET"}, t = "I see a cherub that sees them." },
    { r = {"HAMLET"}, t = "But, come; for England!" },
    { r = {"HAMLET"}, t = "Farewell, dear mother." },
    { r = {"CLAUDIUS"}, t = "Thy loving father, Hamlet." },
    { r = {"HAMLET"}, t = "My mother." },
    { r = {"HAMLET"}, t = "Father and mother is man and wife; man and wife is one flesh; and so, my mother." },
    { r = {"HAMLET"}, t = "Come, for England." },
    { d = "Exit" },
    { r = {"CLAUDIUS"}, t = "Follow him at foot. Tempt him with speed aboard;" },
    { r = {"CLAUDIUS"}, t = "Delay it not; I’ll have him hence tonight." },
    { r = {"CLAUDIUS"}, t = "Away, for everything is seal’d and done" },
    { r = {"CLAUDIUS"}, t = "That else leans on th’affair. Pray you make haste." },
    { d = "Exeunt Rosencrantz and Guildenstern" },
    { r = {"CLAUDIUS"}, t = "And England, if my love thou hold’st at aught,—" },
    { r = {"CLAUDIUS"}, t = "As my great power thereof may give thee sense," },
    { r = {"CLAUDIUS"}, t = "Since yet thy cicatrice looks raw and red" },
    { r = {"CLAUDIUS"}, t = "After the Danish sword, and thy free awe" },
    { r = {"CLAUDIUS"}, t = "Pays homage to us,—thou mayst not coldly set" },
    { r = {"CLAUDIUS"}, t = "Our sovereign process, which imports at full," },
    { r = {"CLAUDIUS"}, t = "By letters conjuring to that effect," },
    { r = {"CLAUDIUS"}, t = "The present death of Hamlet. Do it, England;" },
    { r = {"CLAUDIUS"}, t = "For like the hectic in my blood he rages," },
    { r = {"CLAUDIUS"}, t = "And thou must cure me. Till I know ’tis done," },
    { r = {"CLAUDIUS"}, t = "Howe’er my haps, my joys were ne’er begun." },
    { d = "Exit" },
    { d = "Act 4, Scene 4. A plain in Denmark.", h = true },
    { d = "Enter Fortinbras and Forces marching" },
    { r = {"FORTINBRAS"}, t = "Go, Captain, from me greet the Danish king." },
    { r = {"FORTINBRAS"}, t = "Tell him that by his license, Fortinbras" },
    { r = {"FORTINBRAS"}, t = "Craves the conveyance of a promis’d march" },
    { r = {"FORTINBRAS"}, t = "Over his kingdom. You know the rendezvous." },
    { r = {"FORTINBRAS"}, t = "If that his Majesty would aught with us," },
    { r = {"FORTINBRAS"}, t = "We shall express our duty in his eye;" },
    { r = {"FORTINBRAS"}, t = "And let him know so." },
    { r = {"CAPTAIN"}, t = "I will do’t, my lord." },
    { r = {"FORTINBRAS"}, t = "Go softly on." },
    { d = "Exeunt all but the Captain" },
    { d = "Enter Hamlet, Rosencrantz, Guildenstern &c" },
    { r = {"HAMLET"}, t = "Good sir, whose powers are these?" },
    { r = {"CAPTAIN"}, t = "They are of Norway, sir." },
    { r = {"HAMLET"}, t = "How purpos’d, sir, I pray you?" },
    { r = {"CAPTAIN"}, t = "Against some part of Poland." },
    { r = {"HAMLET"}, t = "Who commands them, sir?" },
    { r = {"CAPTAIN"}, t = "The nephew to old Norway, Fortinbras." },
    { r = {"HAMLET"}, t = "Goes it against the main of Poland, sir," },
    { r = {"HAMLET"}, t = "Or for some frontier?" },
    { r = {"CAPTAIN"}, t = "Truly to speak, and with no addition," },
    { r = {"CAPTAIN"}, t = "We go to gain a little patch of ground" },
    { r = {"CAPTAIN"}, t = "That hath in it no profit but the name." },
    { r = {"CAPTAIN"}, t = "To pay five ducats, five, I would not farm it;" },
    { r = {"CAPTAIN"}, t = "Nor will it yield to Norway or the Pole" },
    { r = {"CAPTAIN"}, t = "A ranker rate, should it be sold in fee." },
    { r = {"HAMLET"}, t = "Why, then the Polack never will defend it." },
    { r = {"CAPTAIN"}, t = "Yes, it is already garrison’d." },
    { r = {"HAMLET"}, t = "Two thousand souls and twenty thousand ducats" },
    { r = {"HAMLET"}, t = "Will not debate the question of this straw!" },
    { r = {"HAMLET"}, t = "This is th’imposthume of much wealth and peace," },
    { r = {"HAMLET"}, t = "That inward breaks, and shows no cause without" },
    { r = {"HAMLET"}, t = "Why the man dies. I humbly thank you, sir." },
    { r = {"CAPTAIN"}, t = "God b’ wi’ you, sir." },
    { d = "Exit" },
    { r = {"ROSENCRANTZ"}, t = "Will’t please you go, my lord?" },
    { r = {"HAMLET"}, t = "I’ll be with you straight. Go a little before." },
    { d = "Exeunt all but Hamlet" },
    { r = {"HAMLET"}, t = "How all occasions do inform against me," },
    { r = {"HAMLET"}, t = "And spur my dull revenge. What is a man" },
    { r = {"HAMLET"}, t = "If his chief good and market of his time" },
    { r = {"HAMLET"}, t = "Be but to sleep and feed? A beast, no more." },
    { r = {"HAMLET"}, t = "Sure he that made us with such large discourse," },
    { r = {"HAMLET"}, t = "Looking before and after, gave us not" },
    { r = {"HAMLET"}, t = "That capability and godlike reason" },
    { r = {"HAMLET"}, t = "To fust in us unus’d. Now whether it be" },
    { r = {"HAMLET"}, t = "Bestial oblivion, or some craven scruple" },
    { r = {"HAMLET"}, t = "Of thinking too precisely on th’event,—" },
    { r = {"HAMLET"}, t = "A thought which, quarter’d, hath but one part wisdom" },
    { r = {"HAMLET"}, t = "And ever three parts coward,—I do not know" },
    { r = {"HAMLET"}, t = "Why yet I live to say this thing’s to do," },
    { r = {"HAMLET"}, t = "Sith I have cause, and will, and strength, and means" },
    { r = {"HAMLET"}, t = "To do’t. Examples gross as earth exhort me," },
    { r = {"HAMLET"}, t = "Witness this army of such mass and charge," },
    { r = {"HAMLET"}, t = "Led by a delicate and tender prince," },
    { r = {"HAMLET"}, t = "Whose spirit, with divine ambition puff’d," },
    { r = {"HAMLET"}, t = "Makes mouths at the invisible event," },
    { r = {"HAMLET"}, t = "Exposing what is mortal and unsure" },
    { r = {"HAMLET"}, t = "To all that fortune, death, and danger dare," },
    { r = {"HAMLET"}, t = "Even for an eggshell. Rightly to be great" },
    { r = {"HAMLET"}, t = "Is not to stir without great argument," },
    { r = {"HAMLET"}, t = "But greatly to find quarrel in a straw" },
    { r = {"HAMLET"}, t = "When honour’s at the stake. How stand I then," },
    { r = {"HAMLET"}, t = "That have a father kill’d, a mother stain’d," },
    { r = {"HAMLET"}, t = "Excitements of my reason and my blood," },
    { r = {"HAMLET"}, t = "And let all sleep, while to my shame I see" },
    { r = {"HAMLET"}, t = "The imminent death of twenty thousand men" },
    { r = {"HAMLET"}, t = "That, for a fantasy and trick of fame," },
    { r = {"HAMLET"}, t = "Go to their graves like beds, fight for a plot" },
    { r = {"HAMLET"}, t = "Whereon the numbers cannot try the cause," },
    { r = {"HAMLET"}, t = "Which is not tomb enough and continent" },
    { r = {"HAMLET"}, t = "To hide the slain? O, from this time forth," },
    { r = {"HAMLET"}, t = "My thoughts be bloody or be nothing worth." },
    { d = "Exit" },
    { d = "Act 4, Scene 5. Elsinore. A room in the Castle.", h = true },
    { d = "Enter Queen, Horatio and a Gentleman" },
    { r = {"GERTRUDE"}, t = "I will not speak with her." },
    { r = {"GENTLEMAN"}, t = "She is importunate, indeed distract." },
    { r = {"GENTLEMAN"}, t = "Her mood will needs be pitied." },
    { r = {"GERTRUDE"}, t = "What would she have?" },
    { r = {"GENTLEMAN"}, t = "She speaks much of her father; says she hears" },
    { r = {"GENTLEMAN"}, t = "There’s tricks i’ th’ world, and hems, and beats her heart," },
    { r = {"GENTLEMAN"}, t = "Spurns enviously at straws, speaks things in doubt," },
    { r = {"GENTLEMAN"}, t = "That carry but half sense. Her speech is nothing," },
    { r = {"GENTLEMAN"}, t = "Yet the unshaped use of it doth move" },
    { r = {"GENTLEMAN"}, t = "The hearers to collection; they aim at it," },
    { r = {"GENTLEMAN"}, t = "And botch the words up fit to their own thoughts," },
    { r = {"GENTLEMAN"}, t = "Which, as her winks, and nods, and gestures yield them," },
    { r = {"GENTLEMAN"}, t = "Indeed would make one think there might be thought," },
    { r = {"GENTLEMAN"}, t = "Though nothing sure, yet much unhappily." },
    { r = {"GENTLEMAN"}, t = "’Twere good she were spoken with, for she may strew" },
    { r = {"GENTLEMAN"}, t = "Dangerous conjectures in ill-breeding minds." },
    { r = {"GERTRUDE"}, t = "Let her come in." },
    { d = "Exit Gentleman" },
    { r = {"GERTRUDE"}, t = "To my sick soul, as sin’s true nature is," },
    { r = {"GERTRUDE"}, t = "Each toy seems prologue to some great amiss." },
    { r = {"GERTRUDE"}, t = "So full of artless jealousy is guilt," },
    { r = {"GERTRUDE"}, t = "It spills itself in fearing to be spilt." },
    { d = "Enter Ophelia" },
    { r = {"OPHELIA"}, t = "Where is the beauteous Majesty of Denmark?" },
    { r = {"GERTRUDE"}, t = "How now, Ophelia?" },
    { r = {"OPHELIA"}, t = "How should I your true love know", d = "Sings" },
    { r = {"OPHELIA"}, t = "From another one?" },
    { r = {"OPHELIA"}, t = "By his cockle hat and staff" },
    { r = {"OPHELIA"}, t = "And his sandal shoon." },
    { r = {"GERTRUDE"}, t = "Alas, sweet lady, what imports this song?" },
    { r = {"OPHELIA"}, t = "Say you? Nay, pray you mark." },
    { r = {"OPHELIA"}, t = "He is dead and gone, lady,", d = "Sings" },
    { r = {"OPHELIA"}, t = "He is dead and gone," },
    { r = {"OPHELIA"}, t = "At his head a grass green turf," },
    { r = {"OPHELIA"}, t = "At his heels a stone." },
    { r = {"GERTRUDE"}, t = "Nay, but Ophelia" },
    { r = {"OPHELIA"}, t = "Pray you mark." },
    { r = {"OPHELIA"}, t = "White his shroud as the mountain snow.", d = "Sings" },
    { d = "Enter King" },
    { r = {"GERTRUDE"}, t = "Alas, look here, my lord!" },
    { r = {"OPHELIA"}, t = "Larded all with sweet flowers;", d = "Sings" },
    { r = {"OPHELIA"}, t = "Which bewept to the grave did not go" },
    { r = {"OPHELIA"}, t = "With true-love showers." },
    { r = {"CLAUDIUS"}, t = "How do you, pretty lady?" },
    { r = {"OPHELIA"}, t = "Well, God dild you!" },
    { r = {"OPHELIA"}, t = "They say the owl was a baker’s daughter." },
    { r = {"OPHELIA"}, t = "Lord, we know what we are, but know not what we may be." },
    { r = {"OPHELIA"}, t = "God be at your table!" },
    { r = {"CLAUDIUS"}, t = "Conceit upon her father." },
    { r = {"OPHELIA"}, t = "Pray you, let’s have no words of this; but when they ask you what it means, say you this:" },
    { r = {"OPHELIA"}, t = "Tomorrow is Saint Valentine’s day,", d = "Sings" },
    { r = {"OPHELIA"}, t = "All in the morning betime," },
    { r = {"OPHELIA"}, t = "And I a maid at your window," },
    { r = {"OPHELIA"}, t = "To be your Valentine." },
    { r = {"OPHELIA"}, t = "Then up he rose and donn’d his clothes," },
    { r = {"OPHELIA"}, t = "And dupp’d the chamber door," },
    { r = {"OPHELIA"}, t = "Let in the maid, that out a maid" },
    { r = {"OPHELIA"}, t = "Never departed more." },
    { r = {"CLAUDIUS"}, t = "Pretty Ophelia!" },
    { r = {"OPHELIA"}, t = "Indeed la, without an oath, I’ll make an end on’t." },
    { r = {"OPHELIA"}, t = "By Gis and by Saint Charity,", d = "Sings" },
    { r = {"OPHELIA"}, t = "Alack, and fie for shame!" },
    { r = {"OPHELIA"}, t = "Young men will do’t if they come to’t;" },
    { r = {"OPHELIA"}, t = "By Cock, they are to blame." },
    { r = {"OPHELIA"}, t = "Quoth she, before you tumbled me," },
    { r = {"OPHELIA"}, t = "You promis’d me to wed." },
    { r = {"OPHELIA"}, t = "So would I ha’ done, by yonder sun," },
    { r = {"OPHELIA"}, t = "An thou hadst not come to my bed." },
    { r = {"CLAUDIUS"}, t = "How long hath she been thus?" },
    { r = {"OPHELIA"}, t = "I hope all will be well." },
    { r = {"OPHELIA"}, t = "We must be patient." },
    { r = {"OPHELIA"}, t = "But I cannot choose but weep, to think they would lay him i’ th’ cold ground." },
    { r = {"OPHELIA"}, t = "My brother shall know of it." },
    { r = {"OPHELIA"}, t = "And so I thank you for your good counsel." },
    { r = {"OPHELIA"}, t = "Come, my coach!" },
    { r = {"OPHELIA"}, t = "Good night, ladies; good night, sweet ladies; good night, good night." },
    { d = "Exit" },
    { r = {"CLAUDIUS"}, t = "Follow her close; give her good watch, I pray you." },
    { d = "Exit Horatio" },
    { r = {"CLAUDIUS"}, t = "O, this is the poison of deep grief; it springs" },
    { r = {"CLAUDIUS"}, t = "All from her father’s death. O Gertrude, Gertrude," },
    { r = {"CLAUDIUS"}, t = "When sorrows come, they come not single spies," },
    { r = {"CLAUDIUS"}, t = "But in battalions. First, her father slain;" },
    { r = {"CLAUDIUS"}, t = "Next, your son gone; and he most violent author" },
    { r = {"CLAUDIUS"}, t = "Of his own just remove; the people muddied," },
    { r = {"CLAUDIUS"}, t = "Thick, and unwholesome in their thoughts and whispers" },
    { r = {"CLAUDIUS"}, t = "For good Polonius’ death; and we have done but greenly" },
    { r = {"CLAUDIUS"}, t = "In hugger-mugger to inter him. Poor Ophelia" },
    { r = {"CLAUDIUS"}, t = "Divided from herself and her fair judgement," },
    { r = {"CLAUDIUS"}, t = "Without the which we are pictures or mere beasts." },
    { r = {"CLAUDIUS"}, t = "Last, and as much containing as all these," },
    { r = {"CLAUDIUS"}, t = "Her brother is in secret come from France," },
    { r = {"CLAUDIUS"}, t = "Feeds on his wonder, keeps himself in clouds," },
    { r = {"CLAUDIUS"}, t = "And wants not buzzers to infect his ear" },
    { r = {"CLAUDIUS"}, t = "With pestilent speeches of his father’s death," },
    { r = {"CLAUDIUS"}, t = "Wherein necessity, of matter beggar’d," },
    { r = {"CLAUDIUS"}, t = "Will nothing stick our person to arraign" },
    { r = {"CLAUDIUS"}, t = "In ear and ear. O my dear Gertrude, this," },
    { r = {"CLAUDIUS"}, t = "Like to a murdering piece, in many places" },
    { r = {"CLAUDIUS"}, t = "Gives me superfluous death." },
    { d = "A noise within" },
    { r = {"GERTRUDE"}, t = "Alack, what noise is this?" },
    { r = {"CLAUDIUS"}, t = "Where are my Switzers? Let them guard the door." },
    { d = "Enter a Gentleman" },
    { r = {"CLAUDIUS"}, t = "What is the matter?" },
    { r = {"GENTLEMAN"}, t = "Save yourself, my lord." },
    { r = {"GENTLEMAN"}, t = "The ocean, overpeering of his list," },
    { r = {"GENTLEMAN"}, t = "Eats not the flats with more impetuous haste" },
    { r = {"GENTLEMAN"}, t = "Than young Laertes, in a riotous head," },
    { r = {"GENTLEMAN"}, t = "O’erbears your offices. The rabble call him lord," },
    { r = {"GENTLEMAN"}, t = "And, as the world were now but to begin," },
    { r = {"GENTLEMAN"}, t = "Antiquity forgot, custom not known," },
    { r = {"GENTLEMAN"}, t = "The ratifiers and props of every word," },
    { r = {"GENTLEMAN"}, t = "They cry ‘Choose we! Laertes shall be king!’" },
    { r = {"GENTLEMAN"}, t = "Caps, hands, and tongues applaud it to the clouds," },
    { r = {"GENTLEMAN"}, t = "‘Laertes shall be king, Laertes king.’" },
    { r = {"GERTRUDE"}, t = "How cheerfully on the false trail they cry." },
    { r = {"GERTRUDE"}, t = "O, this is counter, you false Danish dogs." },
    { d = "A noise within" },
    { r = {"CLAUDIUS"}, t = "The doors are broke." },
    { d = "Enter Laertes, armed; Danes following" },
    { r = {"LAERTES"}, t = "Where is this king?—Sirs, stand you all without." },
    { r = {"DANES"}, t = "No, let’s come in." },
    { r = {"LAERTES"}, t = "I pray you, give me leave." },
    { r = {"DANES"}, t = "We will, we will." },
    { d = "They retire without the door" },
    { r = {"LAERTES"}, t = "I thank you. Keep the door. O thou vile king," },
    { r = {"LAERTES"}, t = "Give me my father." },
    { r = {"GERTRUDE"}, t = "Calmly, good Laertes." },
    { r = {"LAERTES"}, t = "That drop of blood that’s calm proclaims me bastard;" },
    { r = {"LAERTES"}, t = "Cries cuckold to my father, brands the harlot" },
    { r = {"LAERTES"}, t = "Even here between the chaste unsmirched brow" },
    { r = {"LAERTES"}, t = "Of my true mother." },
    { r = {"CLAUDIUS"}, t = "What is the cause, Laertes," },
    { r = {"CLAUDIUS"}, t = "That thy rebellion looks so giant-like?—" },
    { r = {"CLAUDIUS"}, t = "Let him go, Gertrude. Do not fear our person." },
    { r = {"CLAUDIUS"}, t = "There’s such divinity doth hedge a king," },
    { r = {"CLAUDIUS"}, t = "That treason can but peep to what it would," },
    { r = {"CLAUDIUS"}, t = "Acts little of his will.—Tell me, Laertes," },
    { r = {"CLAUDIUS"}, t = "Why thou art thus incens’d.—Let him go, Gertrude:—" },
    { r = {"CLAUDIUS"}, t = "Speak, man." },
    { r = {"LAERTES"}, t = "Where is my father?" },
    { r = {"CLAUDIUS"}, t = "Dead." },
    { r = {"GERTRUDE"}, t = "But not by him." },
    { r = {"CLAUDIUS"}, t = "Let him demand his fill." },
    { r = {"LAERTES"}, t = "How came he dead? I’ll not be juggled with." },
    { r = {"LAERTES"}, t = "To hell, allegiance! Vows, to the blackest devil!" },
    { r = {"LAERTES"}, t = "Conscience and grace, to the profoundest pit!" },
    { r = {"LAERTES"}, t = "I dare damnation. To this point I stand," },
    { r = {"LAERTES"}, t = "That both the worlds, I give to negligence," },
    { r = {"LAERTES"}, t = "Let come what comes; only I’ll be reveng’d" },
    { r = {"LAERTES"}, t = "Most throughly for my father." },
    { r = {"CLAUDIUS"}, t = "Who shall stay you?" },
    { r = {"LAERTES"}, t = "My will, not all the world." },
    { r = {"LAERTES"}, t = "And for my means, I’ll husband them so well," },
    { r = {"LAERTES"}, t = "They shall go far with little." },
    { r = {"CLAUDIUS"}, t = "Good Laertes," },
    { r = {"CLAUDIUS"}, t = "If you desire to know the certainty" },
    { r = {"CLAUDIUS"}, t = "Of your dear father’s death, is’t writ in your revenge" },
    { r = {"CLAUDIUS"}, t = "That, sweepstake, you will draw both friend and foe," },
    { r = {"CLAUDIUS"}, t = "Winner and loser?" },
    { r = {"LAERTES"}, t = "None but his enemies." },
    { r = {"CLAUDIUS"}, t = "Will you know them then?" },
    { r = {"LAERTES"}, t = "To his good friends thus wide I’ll ope my arms;" },
    { r = {"LAERTES"}, t = "And, like the kind life-rendering pelican," },
    { r = {"LAERTES"}, t = "Repast them with my blood." },
    { r = {"CLAUDIUS"}, t = "Why, now you speak" },
    { r = {"CLAUDIUS"}, t = "Like a good child and a true gentleman." },
    { r = {"CLAUDIUS"}, t = "That I am guiltless of your father’s death," },
    { r = {"CLAUDIUS"}, t = "And am most sensibly in grief for it," },
    { r = {"CLAUDIUS"}, t = "It shall as level to your judgement ’pear" },
    { r = {"CLAUDIUS"}, t = "As day does to your eye." },
    { r = {"DANES"}, t = "Let her come in.", d = "Within" },
    { r = {"LAERTES"}, t = "How now! What noise is that?" },
    { d = "Re-enter Ophelia, fantastically dressed with straws and flowers" },
    { r = {"LAERTES"}, t = "O heat, dry up my brains. Tears seven times salt," },
    { r = {"LAERTES"}, t = "Burn out the sense and virtue of mine eye." },
    { r = {"LAERTES"}, t = "By heaven, thy madness shall be paid by weight," },
    { r = {"LAERTES"}, t = "Till our scale turn the beam. O rose of May!" },
    { r = {"LAERTES"}, t = "Dear maid, kind sister, sweet Ophelia!" },
    { r = {"LAERTES"}, t = "O heavens, is’t possible a young maid’s wits" },
    { r = {"LAERTES"}, t = "Should be as mortal as an old man’s life?" },
    { r = {"LAERTES"}, t = "Nature is fine in love, and where ’tis fine," },
    { r = {"LAERTES"}, t = "It sends some precious instance of itself" },
    { r = {"LAERTES"}, t = "After the thing it loves." },
    { r = {"OPHELIA"}, t = "They bore him barefac’d on the bier,", d = "Sings" },
    { r = {"OPHELIA"}, t = "Hey non nonny, nonny, hey nonny" },
    { r = {"OPHELIA"}, t = "And on his grave rain’d many a tear.—" },
    { r = {"OPHELIA"}, t = "Fare you well, my dove!" },
    { r = {"LAERTES"}, t = "Hadst thou thy wits, and didst persuade revenge," },
    { r = {"LAERTES"}, t = "It could not move thus." },
    { r = {"OPHELIA"}, t = "You must sing ‘Down a-down, and you call him a-down-a.’" },
    { r = {"OPHELIA"}, t = "O, how the wheel becomes it!" },
    { r = {"OPHELIA"}, t = "It is the false steward that stole his master’s daughter." },
    { r = {"LAERTES"}, t = "This nothing’s more than matter." },
    { r = {"OPHELIA"}, t = "There’s rosemary, that’s for remembrance; pray love, remember." },
    { r = {"OPHELIA"}, t = "And there is pansies, that’s for thoughts." },
    { r = {"LAERTES"}, t = "A document in madness, thoughts and remembrance fitted." },
    { r = {"OPHELIA"}, t = "There’s fennel for you, and columbines." },
    { r = {"OPHELIA"}, t = "There’s rue for you; and here’s some for me." },
    { r = {"OPHELIA"}, t = "We may call it herb of grace o’ Sundays." },
    { r = {"OPHELIA"}, t = "O you must wear your rue with a difference." },
    { r = {"OPHELIA"}, t = "There’s a daisy." },
    { r = {"OPHELIA"}, t = "I would give you some violets, but they wither’d all when my father died." },
    { r = {"OPHELIA"}, t = "They say he made a good end." },
    { r = {"OPHELIA"}, t = "For bonny sweet Robin is all my joy.", d = "Sings" },
    { r = {"LAERTES"}, t = "Thought and affliction, passion, hell itself" },
    { r = {"LAERTES"}, t = "She turns to favour and to prettiness." },
    { r = {"OPHELIA"}, t = "And will he not come again?", d = "Sings" },
    { r = {"OPHELIA"}, t = "And will he not come again?" },
    { r = {"OPHELIA"}, t = "No, no, he is dead," },
    { r = {"OPHELIA"}, t = "Go to thy death-bed," },
    { r = {"OPHELIA"}, t = "He never will come again." },
    { r = {"OPHELIA"}, t = "His beard was as white as snow," },
    { r = {"OPHELIA"}, t = "All flaxen was his poll." },
    { r = {"OPHELIA"}, t = "He is gone, he is gone," },
    { r = {"OPHELIA"}, t = "And we cast away moan." },
    { r = {"OPHELIA"}, t = "God ha’ mercy on his soul." },
    { r = {"OPHELIA"}, t = "And of all Christian souls, I pray God. God b’ wi’ ye." },
    { d = "Exit" },
    { r = {"LAERTES"}, t = "Do you see this, O God?" },
    { r = {"CLAUDIUS"}, t = "Laertes, I must commune with your grief," },
    { r = {"CLAUDIUS"}, t = "Or you deny me right. Go but apart," },
    { r = {"CLAUDIUS"}, t = "Make choice of whom your wisest friends you will," },
    { r = {"CLAUDIUS"}, t = "And they shall hear and judge ’twixt you and me." },
    { r = {"CLAUDIUS"}, t = "If by direct or by collateral hand" },
    { r = {"CLAUDIUS"}, t = "They find us touch’d, we will our kingdom give," },
    { r = {"CLAUDIUS"}, t = "Our crown, our life, and all that we call ours" },
    { r = {"CLAUDIUS"}, t = "To you in satisfaction; but if not," },
    { r = {"CLAUDIUS"}, t = "Be you content to lend your patience to us," },
    { r = {"CLAUDIUS"}, t = "And we shall jointly labour with your soul" },
    { r = {"CLAUDIUS"}, t = "To give it due content." },
    { r = {"LAERTES"}, t = "Let this be so;" },
    { r = {"LAERTES"}, t = "His means of death, his obscure burial,—" },
    { r = {"LAERTES"}, t = "No trophy, sword, nor hatchment o’er his bones," },
    { r = {"LAERTES"}, t = "No noble rite, nor formal ostentation,—" },
    { r = {"LAERTES"}, t = "Cry to be heard, as ’twere from heaven to earth," },
    { r = {"LAERTES"}, t = "That I must call’t in question." },
    { r = {"CLAUDIUS"}, t = "So you shall." },
    { r = {"CLAUDIUS"}, t = "And where th’offence is let the great axe fall." },
    { r = {"CLAUDIUS"}, t = "I pray you go with me." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 6. Another room in the Castle.", h = true },
    { d = "Enter Horatio and a Servant" },
    { r = {"HORATIO"}, t = "What are they that would speak with me?" },
    { r = {"SERVANT"}, t = "Sailors, sir. They say they have letters for you." },
    { r = {"HORATIO"}, t = "Let them come in." },
    { d = "Exit Servant" },
    { r = {"HORATIO"}, t = "I do not know from what part of the world" },
    { r = {"HORATIO"}, t = "I should be greeted, if not from Lord Hamlet." },
    { d = "Enter Sailors" },
    { r = {"FIRST SAILOR"}, t = "God bless you, sir." },
    { r = {"HORATIO"}, t = "Let him bless thee too." },
    { r = {"FIRST SAILOR"}, t = "He shall, sir, and’t please him." },
    { r = {"FIRST SAILOR"}, t = "There’s a letter for you, sir." },
    { r = {"FIRST SAILOR"}, t = "It comes from th’ambassador that was bound for England; if your name be Horatio, as I am let to know it is." },
    { r = {"HORATIO"}, t = "‘Horatio, when thou shalt have overlooked this, give these fellows some means to the King.", d = "Reads" },
    { r = {"HORATIO"}, t = "They have letters for him." },
    { r = {"HORATIO"}, t = "Ere we were two days old at sea, a pirate of very warlike appointment gave us chase." },
    { r = {"HORATIO"}, t = "Finding ourselves too slow of sail, we put on a compelled valour, and in the grapple I boarded them." },
    { r = {"HORATIO"}, t = "On the instant they got clear of our ship, so I alone became their prisoner." },
    { r = {"HORATIO"}, t = "They have dealt with me like thieves of mercy." },
    { r = {"HORATIO"}, t = "But they knew what they did; I am to do a good turn for them." },
    { r = {"HORATIO"}, t = "Let the King have the letters I have sent, and repair thou to me with as much haste as thou wouldst fly death." },
    { r = {"HORATIO"}, t = "I have words to speak in thine ear will make thee dumb; yet are they much too light for the bore of the matter." },
    { r = {"HORATIO"}, t = "These good fellows will bring thee where I am." },
    { r = {"HORATIO"}, t = "Rosencrantz and Guildenstern hold their course for England: of them I have much to tell thee." },
    { r = {"HORATIO"}, t = "Farewell." },
    { r = {"HORATIO"}, t = "He that thou knowest thine," },
    { r = {"HORATIO"}, t = "HAMLET.’" },
    { r = {"HORATIO"}, t = "Come, I will give you way for these your letters," },
    { r = {"HORATIO"}, t = "And do’t the speedier, that you may direct me" },
    { r = {"HORATIO"}, t = "To him from whom you brought them." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 7. Another room in the Castle.", h = true },
    { d = "Enter King and Laertes" },
    { r = {"CLAUDIUS"}, t = "Now must your conscience my acquittance seal," },
    { r = {"CLAUDIUS"}, t = "And you must put me in your heart for friend," },
    { r = {"CLAUDIUS"}, t = "Sith you have heard, and with a knowing ear," },
    { r = {"CLAUDIUS"}, t = "That he which hath your noble father slain" },
    { r = {"CLAUDIUS"}, t = "Pursu’d my life." },
    { r = {"LAERTES"}, t = "It well appears. But tell me" },
    { r = {"LAERTES"}, t = "Why you proceeded not against these feats," },
    { r = {"LAERTES"}, t = "So crimeful and so capital in nature," },
    { r = {"LAERTES"}, t = "As by your safety, wisdom, all things else," },
    { r = {"LAERTES"}, t = "You mainly were stirr’d up." },
    { r = {"CLAUDIUS"}, t = "O, for two special reasons," },
    { r = {"CLAUDIUS"}, t = "Which may to you, perhaps, seem much unsinew’d," },
    { r = {"CLAUDIUS"}, t = "But yet to me they are strong. The Queen his mother" },
    { r = {"CLAUDIUS"}, t = "Lives almost by his looks; and for myself,—" },
    { r = {"CLAUDIUS"}, t = "My virtue or my plague, be it either which,—" },
    { r = {"CLAUDIUS"}, t = "She’s so conjunctive to my life and soul," },
    { r = {"CLAUDIUS"}, t = "That, as the star moves not but in his sphere," },
    { r = {"CLAUDIUS"}, t = "I could not but by her. The other motive," },
    { r = {"CLAUDIUS"}, t = "Why to a public count I might not go," },
    { r = {"CLAUDIUS"}, t = "Is the great love the general gender bear him," },
    { r = {"CLAUDIUS"}, t = "Who, dipping all his faults in their affection," },
    { r = {"CLAUDIUS"}, t = "Would like the spring that turneth wood to stone," },
    { r = {"CLAUDIUS"}, t = "Convert his gyves to graces; so that my arrows," },
    { r = {"CLAUDIUS"}, t = "Too slightly timber’d for so loud a wind," },
    { r = {"CLAUDIUS"}, t = "Would have reverted to my bow again," },
    { r = {"CLAUDIUS"}, t = "And not where I had aim’d them." },
    { r = {"LAERTES"}, t = "And so have I a noble father lost," },
    { r = {"LAERTES"}, t = "A sister driven into desperate terms," },
    { r = {"LAERTES"}, t = "Whose worth, if praises may go back again," },
    { r = {"LAERTES"}, t = "Stood challenger on mount of all the age" },
    { r = {"LAERTES"}, t = "For her perfections. But my revenge will come." },
    { r = {"CLAUDIUS"}, t = "Break not your sleeps for that. You must not think" },
    { r = {"CLAUDIUS"}, t = "That we are made of stuff so flat and dull" },
    { r = {"CLAUDIUS"}, t = "That we can let our beard be shook with danger," },
    { r = {"CLAUDIUS"}, t = "And think it pastime. You shortly shall hear more." },
    { r = {"CLAUDIUS"}, t = "I lov’d your father, and we love ourself," },
    { r = {"CLAUDIUS"}, t = "And that, I hope, will teach you to imagine" },
    { d = "Enter a Messenger" },
    { r = {"CLAUDIUS"}, t = "How now? What news?" },
    { r = {"MESSENGER"}, t = "Letters, my lord, from Hamlet." },
    { r = {"MESSENGER"}, t = "This to your Majesty; this to the Queen." },
    { r = {"CLAUDIUS"}, t = "From Hamlet! Who brought them?" },
    { r = {"MESSENGER"}, t = "Sailors, my lord, they say; I saw them not." },
    { r = {"MESSENGER"}, t = "They were given me by Claudio. He receiv’d them" },
    { r = {"MESSENGER"}, t = "Of him that brought them." },
    { r = {"CLAUDIUS"}, t = "Laertes, you shall hear them." },
    { r = {"CLAUDIUS"}, t = "Leave us." },
    { d = "Exit Messenger" },
    { r = {"CLAUDIUS"}, t = "‘High and mighty, you shall know I am set naked on your kingdom.", d = "Reads" },
    { r = {"CLAUDIUS"}, t = "Tomorrow shall I beg leave to see your kingly eyes." },
    { r = {"CLAUDIUS"}, t = "When I shall, first asking your pardon thereunto, recount the occasions of my sudden and more strange return." },
    { r = {"CLAUDIUS"}, t = "HAMLET.’" },
    { r = {"CLAUDIUS"}, t = "What should this mean? Are all the rest come back?" },
    { r = {"CLAUDIUS"}, t = "Or is it some abuse, and no such thing?" },
    { r = {"LAERTES"}, t = "Know you the hand?" },
    { r = {"CLAUDIUS"}, t = "’Tis Hamlet’s character. ‘Naked!’" },
    { r = {"CLAUDIUS"}, t = "And in a postscript here he says ‘alone.’" },
    { r = {"CLAUDIUS"}, t = "Can you advise me?" },
    { r = {"LAERTES"}, t = "I am lost in it, my lord. But let him come," },
    { r = {"LAERTES"}, t = "It warms the very sickness in my heart" },
    { r = {"LAERTES"}, t = "That I shall live and tell him to his teeth," },
    { r = {"LAERTES"}, t = "‘Thus diest thou.’" },
    { r = {"CLAUDIUS"}, t = "If it be so, Laertes,—" },
    { r = {"CLAUDIUS"}, t = "As how should it be so? How otherwise?—" },
    { r = {"CLAUDIUS"}, t = "Will you be rul’d by me?" },
    { r = {"LAERTES"}, t = "Ay, my lord;" },
    { r = {"LAERTES"}, t = "So you will not o’errule me to a peace." },
    { r = {"CLAUDIUS"}, t = "To thine own peace. If he be now return’d," },
    { r = {"CLAUDIUS"}, t = "As checking at his voyage, and that he means" },
    { r = {"CLAUDIUS"}, t = "No more to undertake it, I will work him" },
    { r = {"CLAUDIUS"}, t = "To an exploit, now ripe in my device," },
    { r = {"CLAUDIUS"}, t = "Under the which he shall not choose but fall;" },
    { r = {"CLAUDIUS"}, t = "And for his death no wind shall breathe," },
    { r = {"CLAUDIUS"}, t = "But even his mother shall uncharge the practice" },
    { r = {"CLAUDIUS"}, t = "And call it accident." },
    { r = {"LAERTES"}, t = "My lord, I will be rul’d;" },
    { r = {"LAERTES"}, t = "The rather if you could devise it so" },
    { r = {"LAERTES"}, t = "That I might be the organ." },
    { r = {"CLAUDIUS"}, t = "It falls right." },
    { r = {"CLAUDIUS"}, t = "You have been talk’d of since your travel much," },
    { r = {"CLAUDIUS"}, t = "And that in Hamlet’s hearing, for a quality" },
    { r = {"CLAUDIUS"}, t = "Wherein they say you shine. Your sum of parts" },
    { r = {"CLAUDIUS"}, t = "Did not together pluck such envy from him" },
    { r = {"CLAUDIUS"}, t = "As did that one, and that, in my regard," },
    { r = {"CLAUDIUS"}, t = "Of the unworthiest siege." },
    { r = {"LAERTES"}, t = "What part is that, my lord?" },
    { r = {"CLAUDIUS"}, t = "A very riband in the cap of youth," },
    { r = {"CLAUDIUS"}, t = "Yet needful too, for youth no less becomes" },
    { r = {"CLAUDIUS"}, t = "The light and careless livery that it wears" },
    { r = {"CLAUDIUS"}, t = "Than settled age his sables and his weeds," },
    { r = {"CLAUDIUS"}, t = "Importing health and graveness. Two months since" },
    { r = {"CLAUDIUS"}, t = "Here was a gentleman of Normandy,—" },
    { r = {"CLAUDIUS"}, t = "I’ve seen myself, and serv’d against, the French," },
    { r = {"CLAUDIUS"}, t = "And they can well on horseback, but this gallant" },
    { r = {"CLAUDIUS"}, t = "Had witchcraft in’t. He grew unto his seat," },
    { r = {"CLAUDIUS"}, t = "And to such wondrous doing brought his horse," },
    { r = {"CLAUDIUS"}, t = "As had he been incorps’d and demi-natur’d" },
    { r = {"CLAUDIUS"}, t = "With the brave beast. So far he topp’d my thought" },
    { r = {"CLAUDIUS"}, t = "That I in forgery of shapes and tricks," },
    { r = {"CLAUDIUS"}, t = "Come short of what he did." },
    { r = {"LAERTES"}, t = "A Norman was’t?" },
    { r = {"CLAUDIUS"}, t = "A Norman." },
    { r = {"LAERTES"}, t = "Upon my life, Lamord." },
    { r = {"CLAUDIUS"}, t = "The very same." },
    { r = {"LAERTES"}, t = "I know him well. He is the brooch indeed" },
    { r = {"LAERTES"}, t = "And gem of all the nation." },
    { r = {"CLAUDIUS"}, t = "He made confession of you," },
    { r = {"CLAUDIUS"}, t = "And gave you such a masterly report" },
    { r = {"CLAUDIUS"}, t = "For art and exercise in your defence," },
    { r = {"CLAUDIUS"}, t = "And for your rapier most especially," },
    { r = {"CLAUDIUS"}, t = "That he cried out ’twould be a sight indeed" },
    { r = {"CLAUDIUS"}, t = "If one could match you. The scrimers of their nation" },
    { r = {"CLAUDIUS"}, t = "He swore had neither motion, guard, nor eye," },
    { r = {"CLAUDIUS"}, t = "If you oppos’d them. Sir, this report of his" },
    { r = {"CLAUDIUS"}, t = "Did Hamlet so envenom with his envy" },
    { r = {"CLAUDIUS"}, t = "That he could nothing do but wish and beg" },
    { r = {"CLAUDIUS"}, t = "Your sudden coming o’er to play with him." },
    { r = {"CLAUDIUS"}, t = "Now, out of this," },
    { r = {"LAERTES"}, t = "What out of this, my lord?" },
    { r = {"CLAUDIUS"}, t = "Laertes, was your father dear to you?" },
    { r = {"CLAUDIUS"}, t = "Or are you like the painting of a sorrow," },
    { r = {"CLAUDIUS"}, t = "A face without a heart?" },
    { r = {"LAERTES"}, t = "Why ask you this?" },
    { r = {"CLAUDIUS"}, t = "Not that I think you did not love your father," },
    { r = {"CLAUDIUS"}, t = "But that I know love is begun by time," },
    { r = {"CLAUDIUS"}, t = "And that I see, in passages of proof," },
    { r = {"CLAUDIUS"}, t = "Time qualifies the spark and fire of it." },
    { r = {"CLAUDIUS"}, t = "There lives within the very flame of love" },
    { r = {"CLAUDIUS"}, t = "A kind of wick or snuff that will abate it;" },
    { r = {"CLAUDIUS"}, t = "And nothing is at a like goodness still," },
    { r = {"CLAUDIUS"}, t = "For goodness, growing to a pleurisy," },
    { r = {"CLAUDIUS"}, t = "Dies in his own too much. That we would do," },
    { r = {"CLAUDIUS"}, t = "We should do when we would; for this ‘would’ changes," },
    { r = {"CLAUDIUS"}, t = "And hath abatements and delays as many" },
    { r = {"CLAUDIUS"}, t = "As there are tongues, are hands, are accidents;" },
    { r = {"CLAUDIUS"}, t = "And then this ‘should’ is like a spendthrift sigh" },
    { r = {"CLAUDIUS"}, t = "That hurts by easing. But to the quick o’ th’ulcer:" },
    { r = {"CLAUDIUS"}, t = "Hamlet comes back: what would you undertake" },
    { r = {"CLAUDIUS"}, t = "To show yourself your father’s son in deed," },
    { r = {"CLAUDIUS"}, t = "More than in words?" },
    { r = {"LAERTES"}, t = "To cut his throat i’ th’ church." },
    { r = {"CLAUDIUS"}, t = "No place, indeed, should murder sanctuarize;" },
    { r = {"CLAUDIUS"}, t = "Revenge should have no bounds. But good Laertes," },
    { r = {"CLAUDIUS"}, t = "Will you do this, keep close within your chamber." },
    { r = {"CLAUDIUS"}, t = "Hamlet return’d shall know you are come home:" },
    { r = {"CLAUDIUS"}, t = "We’ll put on those shall praise your excellence," },
    { r = {"CLAUDIUS"}, t = "And set a double varnish on the fame" },
    { r = {"CLAUDIUS"}, t = "The Frenchman gave you, bring you in fine together" },
    { r = {"CLAUDIUS"}, t = "And wager on your heads. He, being remiss," },
    { r = {"CLAUDIUS"}, t = "Most generous, and free from all contriving," },
    { r = {"CLAUDIUS"}, t = "Will not peruse the foils; so that with ease," },
    { r = {"CLAUDIUS"}, t = "Or with a little shuffling, you may choose" },
    { r = {"CLAUDIUS"}, t = "A sword unbated, and in a pass of practice," },
    { r = {"CLAUDIUS"}, t = "Requite him for your father." },
    { r = {"LAERTES"}, t = "I will do’t." },
    { r = {"LAERTES"}, t = "And for that purpose I’ll anoint my sword." },
    { r = {"LAERTES"}, t = "I bought an unction of a mountebank" },
    { r = {"LAERTES"}, t = "So mortal that, but dip a knife in it," },
    { r = {"LAERTES"}, t = "Where it draws blood no cataplasm so rare," },
    { r = {"LAERTES"}, t = "Collected from all simples that have virtue" },
    { r = {"LAERTES"}, t = "Under the moon, can save the thing from death" },
    { r = {"LAERTES"}, t = "This is but scratch’d withal. I’ll touch my point" },
    { r = {"LAERTES"}, t = "With this contagion, that if I gall him slightly," },
    { r = {"LAERTES"}, t = "It may be death." },
    { r = {"CLAUDIUS"}, t = "Let’s further think of this," },
    { r = {"CLAUDIUS"}, t = "Weigh what convenience both of time and means" },
    { r = {"CLAUDIUS"}, t = "May fit us to our shape. If this should fail," },
    { r = {"CLAUDIUS"}, t = "And that our drift look through our bad performance." },
    { r = {"CLAUDIUS"}, t = "’Twere better not assay’d. Therefore this project" },
    { r = {"CLAUDIUS"}, t = "Should have a back or second, that might hold" },
    { r = {"CLAUDIUS"}, t = "If this did blast in proof. Soft, let me see." },
    { r = {"CLAUDIUS"}, t = "We’ll make a solemn wager on your cunnings,—" },
    { r = {"CLAUDIUS"}, t = "I ha’t! When in your motion you are hot and dry," },
    { r = {"CLAUDIUS"}, t = "As make your bouts more violent to that end," },
    { r = {"CLAUDIUS"}, t = "And that he calls for drink, I’ll have prepar’d him" },
    { r = {"CLAUDIUS"}, t = "A chalice for the nonce; whereon but sipping," },
    { r = {"CLAUDIUS"}, t = "If he by chance escape your venom’d stuck," },
    { r = {"CLAUDIUS"}, t = "Our purpose may hold there." },
    { d = "Enter Queen" },
    { r = {"CLAUDIUS"}, t = "How now, sweet Queen?" },
    { r = {"GERTRUDE"}, t = "One woe doth tread upon another’s heel," },
    { r = {"GERTRUDE"}, t = "So fast they follow. Your sister’s drown’d, Laertes." },
    { r = {"LAERTES"}, t = "Drown’d! O, where?" },
    { r = {"GERTRUDE"}, t = "There is a willow grows aslant a brook," },
    { r = {"GERTRUDE"}, t = "That shows his hoary leaves in the glassy stream." },
    { r = {"GERTRUDE"}, t = "There with fantastic garlands did she make" },
    { r = {"GERTRUDE"}, t = "Of crow-flowers, nettles, daisies, and long purples," },
    { r = {"GERTRUDE"}, t = "That liberal shepherds give a grosser name," },
    { r = {"GERTRUDE"}, t = "But our cold maids do dead men’s fingers call them." },
    { r = {"GERTRUDE"}, t = "There on the pendant boughs her coronet weeds" },
    { r = {"GERTRUDE"}, t = "Clamb’ring to hang, an envious sliver broke," },
    { r = {"GERTRUDE"}, t = "When down her weedy trophies and herself" },
    { r = {"GERTRUDE"}, t = "Fell in the weeping brook. Her clothes spread wide," },
    { r = {"GERTRUDE"}, t = "And mermaid-like, awhile they bore her up," },
    { r = {"GERTRUDE"}, t = "Which time she chaunted snatches of old tunes," },
    { r = {"GERTRUDE"}, t = "As one incapable of her own distress," },
    { r = {"GERTRUDE"}, t = "Or like a creature native and indued" },
    { r = {"GERTRUDE"}, t = "Unto that element. But long it could not be" },
    { r = {"GERTRUDE"}, t = "Till that her garments, heavy with their drink," },
    { r = {"GERTRUDE"}, t = "Pull’d the poor wretch from her melodious lay" },
    { r = {"GERTRUDE"}, t = "To muddy death." },
    { r = {"LAERTES"}, t = "Alas, then she is drown’d?" },
    { r = {"GERTRUDE"}, t = "Drown’d, drown’d." },
    { r = {"LAERTES"}, t = "Too much of water hast thou, poor Ophelia," },
    { r = {"LAERTES"}, t = "And therefore I forbid my tears. But yet" },
    { r = {"LAERTES"}, t = "It is our trick; nature her custom holds," },
    { r = {"LAERTES"}, t = "Let shame say what it will. When these are gone," },
    { r = {"LAERTES"}, t = "The woman will be out. Adieu, my lord," },
    { r = {"LAERTES"}, t = "I have a speech of fire, that fain would blaze," },
    { r = {"LAERTES"}, t = "But that this folly douts it." },
    { d = "Exit" },
    { r = {"CLAUDIUS"}, t = "Let’s follow, Gertrude;" },
    { r = {"CLAUDIUS"}, t = "How much I had to do to calm his rage!" },
    { r = {"CLAUDIUS"}, t = "Now fear I this will give it start again;" },
    { r = {"CLAUDIUS"}, t = "Therefore let’s follow." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. A churchyard.", h = true },
    { d = "Enter two Clowns with spades, &c" },
    { r = {"FIRST CLOWN"}, t = "Is she to be buried in Christian burial, when she wilfully seeks her own salvation?" },
    { r = {"SECOND CLOWN"}, t = "I tell thee she is, and therefore make her grave straight." },
    { r = {"SECOND CLOWN"}, t = "The crowner hath sat on her, and finds it Christian burial." },
    { r = {"FIRST CLOWN"}, t = "How can that be, unless she drowned herself in her own defence?" },
    { r = {"SECOND CLOWN"}, t = "Why, ’tis found so." },
    { r = {"FIRST CLOWN"}, t = "It must be se offendendo, it cannot be else." },
    { r = {"FIRST CLOWN"}, t = "For here lies the point: if I drown myself wittingly, it argues an act: and an act hath three branches." },
    { r = {"FIRST CLOWN"}, t = "It is to act, to do, and to perform: argal, she drowned herself wittingly." },
    { r = {"SECOND CLOWN"}, t = "Nay, but hear you, goodman delver," },
    { r = {"FIRST CLOWN"}, t = "Give me leave." },
    { r = {"FIRST CLOWN"}, t = "Here lies the water; good." },
    { r = {"FIRST CLOWN"}, t = "Here stands the man; good." },
    { r = {"FIRST CLOWN"}, t = "If the man go to this water and drown himself, it is, will he nill he, he goes,—mark you that." },
    { r = {"FIRST CLOWN"}, t = "But if the water come to him and drown him, he drowns not himself." },
    { r = {"FIRST CLOWN"}, t = "Argal, he that is not guilty of his own death shortens not his own life." },
    { r = {"SECOND CLOWN"}, t = "But is this law?" },
    { r = {"FIRST CLOWN"}, t = "Ay, marry, is’t, crowner’s quest law." },
    { r = {"SECOND CLOWN"}, t = "Will you ha’ the truth on’t?" },
    { r = {"SECOND CLOWN"}, t = "If this had not been a gentlewoman, she should have been buried out o’ Christian burial." },
    { r = {"FIRST CLOWN"}, t = "Why, there thou say’st." },
    { r = {"FIRST CLOWN"}, t = "And the more pity that great folk should have countenance in this world to drown or hang themselves more than their even Christian." },
    { r = {"FIRST CLOWN"}, t = "Come, my spade." },
    { r = {"FIRST CLOWN"}, t = "There is no ancient gentlemen but gardeners, ditchers, and grave-makers: they hold up Adam’s profession." },
    { r = {"SECOND CLOWN"}, t = "Was he a gentleman?" },
    { r = {"FIRST CLOWN"}, t = "He was the first that ever bore arms." },
    { r = {"SECOND CLOWN"}, t = "Why, he had none." },
    { r = {"FIRST CLOWN"}, t = "What, art a heathen?" },
    { r = {"FIRST CLOWN"}, t = "How dost thou understand the Scripture?" },
    { r = {"FIRST CLOWN"}, t = "The Scripture says Adam digg’d." },
    { r = {"FIRST CLOWN"}, t = "Could he dig without arms?" },
    { r = {"FIRST CLOWN"}, t = "I’ll put another question to thee." },
    { r = {"FIRST CLOWN"}, t = "If thou answerest me not to the purpose, confess thyself" },
    { r = {"SECOND CLOWN"}, t = "Go to." },
    { r = {"FIRST CLOWN"}, t = "What is he that builds stronger than either the mason, the shipwright, or the carpenter?" },
    { r = {"SECOND CLOWN"}, t = "The gallows-maker; for that frame outlives a thousand tenants." },
    { r = {"FIRST CLOWN"}, t = "I like thy wit well in good faith, the gallows does well." },
    { r = {"FIRST CLOWN"}, t = "But how does it well?" },
    { r = {"FIRST CLOWN"}, t = "It does well to those that do ill." },
    { r = {"FIRST CLOWN"}, t = "Now, thou dost ill to say the gallows is built stronger than the church; argal, the gallows may do well to thee." },
    { r = {"FIRST CLOWN"}, t = "To’t again, come." },
    { r = {"SECOND CLOWN"}, t = "Who builds stronger than a mason, a shipwright, or a carpenter?" },
    { r = {"FIRST CLOWN"}, t = "Ay, tell me that, and unyoke." },
    { r = {"SECOND CLOWN"}, t = "Marry, now I can tell." },
    { r = {"FIRST CLOWN"}, t = "To’t." },
    { r = {"SECOND CLOWN"}, t = "Mass, I cannot tell." },
    { d = "Enter Hamlet and Horatio, at a distance" },
    { r = {"FIRST CLOWN"}, t = "Cudgel thy brains no more about it, for your dull ass will not mend his pace with beating; and when you are asked this question next, say ‘a grave-maker’." },
    { r = {"FIRST CLOWN"}, t = "The houses he makes last till doomsday." },
    { r = {"FIRST CLOWN"}, t = "Go, get thee to Yaughan; fetch me a stoup of liquor." },
    { d = "Exit Second Clown" },
    { d = "Digs and sings" },
    { r = {"FIRST CLOWN"}, t = "In youth when I did love, did love," },
    { r = {"FIRST CLOWN"}, t = "Methought it was very sweet;" },
    { r = {"FIRST CLOWN"}, t = "To contract, O, the time for, a, my behove," },
    { r = {"FIRST CLOWN"}, t = "O methought there was nothing meet." },
    { r = {"HAMLET"}, t = "Has this fellow no feeling of his business, that he sings at grave-making?" },
    { r = {"HORATIO"}, t = "Custom hath made it in him a property of easiness." },
    { r = {"HAMLET"}, t = "’Tis e’en so; the hand of little employment hath the daintier sense." },
    { r = {"FIRST CLOWN"}, t = "But age with his stealing steps", d = "Sings" },
    { r = {"FIRST CLOWN"}, t = "Hath claw’d me in his clutch," },
    { r = {"FIRST CLOWN"}, t = "And hath shipp’d me into the land," },
    { r = {"FIRST CLOWN"}, t = "As if I had never been such." },
    { d = "Throws up a skull" },
    { r = {"HAMLET"}, t = "That skull had a tongue in it, and could sing once." },
    { r = {"HAMLET"}, t = "How the knave jowls it to th’ ground, as if ’twere Cain’s jawbone, that did the first murder!" },
    { r = {"HAMLET"}, t = "This might be the pate of a politician which this ass now o’er-offices, one that would circumvent God, might it not?" },
    { r = {"HORATIO"}, t = "It might, my lord." },
    { r = {"HAMLET"}, t = "Or of a courtier, which could say ‘Good morrow, sweet lord!" },
    { r = {"HAMLET"}, t = "How dost thou, good lord?’" },
    { r = {"HAMLET"}, t = "This might be my lord such-a-one, that praised my lord such-a-one’s horse when he meant to beg it, might it not?" },
    { r = {"HORATIO"}, t = "Ay, my lord." },
    { r = {"HAMLET"}, t = "Why, e’en so: and now my Lady Worm’s; chapless, and knocked about the mazard with a sexton’s spade." },
    { r = {"HAMLET"}, t = "Here’s fine revolution, an we had the trick to see’t." },
    { r = {"HAMLET"}, t = "Did these bones cost no more the breeding but to play at loggets with ’em?" },
    { r = {"HAMLET"}, t = "Mine ache to think on’t." },
    { r = {"FIRST CLOWN"}, t = "A pickaxe and a spade, a spade,", d = "Sings" },
    { r = {"FIRST CLOWN"}, t = "For and a shrouding-sheet;" },
    { r = {"FIRST CLOWN"}, t = "O, a pit of clay for to be made" },
    { r = {"FIRST CLOWN"}, t = "For such a guest is meet." },
    { d = "Throws up another skull" },
    { r = {"HAMLET"}, t = "There’s another." },
    { r = {"HAMLET"}, t = "Why may not that be the skull of a lawyer?" },
    { r = {"HAMLET"}, t = "Where be his quiddits now, his quillets, his cases, his tenures, and his tricks?" },
    { r = {"HAMLET"}, t = "Why does he suffer this rude knave now to knock him about the sconce with a dirty shovel, and will not tell him of his action of battery?" },
    { r = {"HAMLET"}, t = "Hum." },
    { r = {"HAMLET"}, t = "This fellow might be in’s time a great buyer of land, with his statutes, his recognizances, his fines, his double vouchers, his recoveries." },
    { r = {"HAMLET"}, t = "Is this the fine of his fines, and the recovery of his recoveries, to have his fine pate full of fine dirt?" },
    { r = {"HAMLET"}, t = "Will his vouchers vouch him no more of his purchases, and double ones too, than the length and breadth of a pair of indentures?" },
    { r = {"HAMLET"}, t = "The very conveyances of his lands will scarcely lie in this box; and must the inheritor himself have no more, ha?" },
    { r = {"HORATIO"}, t = "Not a jot more, my lord." },
    { r = {"HAMLET"}, t = "Is not parchment made of sheep-skins?" },
    { r = {"HORATIO"}, t = "Ay, my lord, and of calf-skins too." },
    { r = {"HAMLET"}, t = "They are sheep and calves which seek out assurance in that." },
    { r = {"HAMLET"}, t = "I will speak to this fellow.—Whose grave’s this, sir?" },
    { r = {"FIRST CLOWN"}, t = "Mine, sir." },
    { r = {"FIRST CLOWN"}, t = "O, a pit of clay for to be made", d = "Sings" },
    { r = {"FIRST CLOWN"}, t = "For such a guest is meet." },
    { r = {"HAMLET"}, t = "I think it be thine indeed, for thou liest in’t." },
    { r = {"FIRST CLOWN"}, t = "You lie out on’t, sir, and therefore ’tis not yours." },
    { r = {"FIRST CLOWN"}, t = "For my part, I do not lie in’t, yet it is mine." },
    { r = {"HAMLET"}, t = "Thou dost lie in’t, to be in’t and say it is thine. ’Tis for the dead, not for the quick; therefore thou liest." },
    { r = {"FIRST CLOWN"}, t = "’Tis a quick lie, sir; ’t will away again from me to you." },
    { r = {"HAMLET"}, t = "What man dost thou dig it for?" },
    { r = {"FIRST CLOWN"}, t = "For no man, sir." },
    { r = {"HAMLET"}, t = "What woman then?" },
    { r = {"FIRST CLOWN"}, t = "For none neither." },
    { r = {"HAMLET"}, t = "Who is to be buried in’t?" },
    { r = {"FIRST CLOWN"}, t = "One that was a woman, sir; but, rest her soul, she’s dead." },
    { r = {"HAMLET"}, t = "How absolute the knave is!" },
    { r = {"HAMLET"}, t = "We must speak by the card, or equivocation will undo us." },
    { r = {"HAMLET"}, t = "By the Lord, Horatio, these three years I have taken note of it, the age is grown so picked that the toe of the peasant comes so near the heel of the courtier he galls his kibe.—How long hast thou been a grave-maker?" },
    { r = {"FIRST CLOWN"}, t = "Of all the days i’ th’ year, I came to’t that day that our last King Hamlet o’ercame Fortinbras." },
    { r = {"HAMLET"}, t = "How long is that since?" },
    { r = {"FIRST CLOWN"}, t = "Cannot you tell that?" },
    { r = {"FIRST CLOWN"}, t = "Every fool can tell that." },
    { r = {"FIRST CLOWN"}, t = "It was the very day that young Hamlet was born,—he that is mad, and sent into England." },
    { r = {"HAMLET"}, t = "Ay, marry, why was he sent into England?" },
    { r = {"FIRST CLOWN"}, t = "Why, because he was mad; he shall recover his wits there; or if he do not, it’s no great matter there." },
    { r = {"HAMLET"}, t = "Why?" },
    { r = {"FIRST CLOWN"}, t = "’Twill not be seen in him there; there the men are as mad as he." },
    { r = {"HAMLET"}, t = "How came he mad?" },
    { r = {"FIRST CLOWN"}, t = "Very strangely, they say." },
    { r = {"HAMLET"}, t = "How strangely?" },
    { r = {"FIRST CLOWN"}, t = "Faith, e’en with losing his wits." },
    { r = {"HAMLET"}, t = "Upon what ground?" },
    { r = {"FIRST CLOWN"}, t = "Why, here in Denmark." },
    { r = {"FIRST CLOWN"}, t = "I have been sexton here, man and boy, thirty years." },
    { r = {"HAMLET"}, t = "How long will a man lie i’ th’earth ere he rot?" },
    { r = {"FIRST CLOWN"}, t = "Faith, if he be not rotten before he die,—as we have many pocky corses nowadays that will scarce hold the laying in,—he will last you some eight year or nine year." },
    { r = {"FIRST CLOWN"}, t = "A tanner will last you nine year." },
    { r = {"HAMLET"}, t = "Why he more than another?" },
    { r = {"FIRST CLOWN"}, t = "Why, sir, his hide is so tann’d with his trade that he will keep out water a great while." },
    { r = {"FIRST CLOWN"}, t = "And your water is a sore decayer of your whoreson dead body." },
    { r = {"FIRST CLOWN"}, t = "Here’s a skull now; this skull hath lain in the earth three-and-twenty years." },
    { r = {"HAMLET"}, t = "Whose was it?" },
    { r = {"FIRST CLOWN"}, t = "A whoreson, mad fellow’s it was. Whose do you think it was?" },
    { r = {"HAMLET"}, t = "Nay, I know not." },
    { r = {"FIRST CLOWN"}, t = "A pestilence on him for a mad rogue!" },
    { r = {"FIRST CLOWN"}, t = "A pour’d a flagon of Rhenish on my head once." },
    { r = {"FIRST CLOWN"}, t = "This same skull, sir, was Yorick’s skull, the King’s jester." },
    { r = {"HAMLET"}, t = "This?" },
    { r = {"FIRST CLOWN"}, t = "E’en that." },
    { r = {"HAMLET"}, t = "Let me see." },
    { r = {"HAMLET"}, t = "Alas, poor Yorick. I knew him,", d = "Takes the skull", e = "/sigh" },
    { r = {"HAMLET"}, t = "Horatio, a fellow of infinite jest, of most excellent fancy." },
    { r = {"HAMLET"}, t = "He hath borne me on his back a thousand times; and now, how abhorred in my imagination it is!" },
    { r = {"HAMLET"}, t = "My gorge rises at it." },
    { r = {"HAMLET"}, t = "Here hung those lips that I have kiss’d I know not how oft." },
    { r = {"HAMLET"}, t = "Where be your gibes now? your gambols? your songs? your flashes of merriment, that were wont to set the table on a roar?" },
    { r = {"HAMLET"}, t = "Not one now, to mock your own grinning?" },
    { r = {"HAMLET"}, t = "Quite chop-fallen?" },
    { r = {"HAMLET"}, t = "Now get you to my lady’s chamber, and tell her, let her paint an inch thick, to this favour she must come." },
    { r = {"HAMLET"}, t = "Make her laugh at that.—Prithee, Horatio, tell me one thing." },
    { r = {"HORATIO"}, t = "What’s that, my lord?" },
    { r = {"HAMLET"}, t = "Dost thou think Alexander looked o’ this fashion i’ th’earth?" },
    { r = {"HORATIO"}, t = "E’en so." },
    { r = {"HAMLET"}, t = "And smelt so? Pah!" },
    { d = "Throws down the skull" },
    { r = {"HORATIO"}, t = "E’en so, my lord." },
    { r = {"HAMLET"}, t = "To what base uses we may return, Horatio!" },
    { r = {"HAMLET"}, t = "Why may not imagination trace the noble dust of Alexander till he find it stopping a bung-hole?" },
    { r = {"HORATIO"}, t = "’Twere to consider too curiously to consider so." },
    { r = {"HAMLET"}, t = "No, faith, not a jot." },
    { r = {"HAMLET"}, t = "But to follow him thither with modesty enough, and likelihood to lead it; as thus." },
    { r = {"HAMLET"}, t = "Alexander died, Alexander was buried, Alexander returneth into dust; the dust is earth; of earth we make loam; and why of that loam whereto he was converted might they not stop a beer-barrel?" },
    { r = {"HAMLET"}, t = "Imperious Caesar, dead and turn’d to clay," },
    { r = {"HAMLET"}, t = "Might stop a hole to keep the wind away." },
    { r = {"HAMLET"}, t = "O, that that earth which kept the world in awe" },
    { r = {"HAMLET"}, t = "Should patch a wall t’expel the winter’s flaw." },
    { r = {"HAMLET"}, t = "But soft! but soft! aside! Here comes the King." },
    { d = "Enter priests, &c, in procession; the corpse of Ophelia, Laertes and Mourners following; King, Queen, their Trains, &c" },
    { r = {"HAMLET"}, t = "The Queen, the courtiers. Who is that they follow?" },
    { r = {"HAMLET"}, t = "And with such maimed rites? This doth betoken" },
    { r = {"HAMLET"}, t = "The corse they follow did with desperate hand" },
    { r = {"HAMLET"}, t = "Fordo it own life. ’Twas of some estate." },
    { r = {"HAMLET"}, t = "Couch we awhile and mark." },
    { d = "Retiring with Horatio" },
    { r = {"LAERTES"}, t = "What ceremony else?" },
    { r = {"HAMLET"}, t = "That is Laertes, a very noble youth. Mark." },
    { r = {"LAERTES"}, t = "What ceremony else?" },
    { r = {"PRIEST"}, t = "Her obsequies have been as far enlarg’d" },
    { r = {"PRIEST"}, t = "As we have warranties. Her death was doubtful;" },
    { r = {"PRIEST"}, t = "And but that great command o’ersways the order," },
    { r = {"PRIEST"}, t = "She should in ground unsanctified have lodg’d" },
    { r = {"PRIEST"}, t = "Till the last trumpet. For charitable prayers," },
    { r = {"PRIEST"}, t = "Shards, flints, and pebbles should be thrown on her." },
    { r = {"PRIEST"}, t = "Yet here she is allowed her virgin rites," },
    { r = {"PRIEST"}, t = "Her maiden strewments, and the bringing home" },
    { r = {"PRIEST"}, t = "Of bell and burial." },
    { r = {"LAERTES"}, t = "Must there no more be done?" },
    { r = {"PRIEST"}, t = "No more be done." },
    { r = {"PRIEST"}, t = "We should profane the service of the dead" },
    { r = {"PRIEST"}, t = "To sing sage requiem and such rest to her" },
    { r = {"PRIEST"}, t = "As to peace-parted souls." },
    { r = {"LAERTES"}, t = "Lay her i’ th’earth," },
    { r = {"LAERTES"}, t = "And from her fair and unpolluted flesh" },
    { r = {"LAERTES"}, t = "May violets spring. I tell thee, churlish priest," },
    { r = {"LAERTES"}, t = "A minist’ring angel shall my sister be" },
    { r = {"LAERTES"}, t = "When thou liest howling." },
    { r = {"HAMLET"}, t = "What, the fair Ophelia?" },
    { r = {"GERTRUDE"}, t = "Sweets to the sweet. Farewell.", d = "Scattering flowers" },
    { r = {"GERTRUDE"}, t = "I hop’d thou shouldst have been my Hamlet’s wife;" },
    { r = {"GERTRUDE"}, t = "I thought thy bride-bed to have deck’d, sweet maid," },
    { r = {"GERTRUDE"}, t = "And not have strew’d thy grave." },
    { r = {"LAERTES"}, t = "O, treble woe" },
    { r = {"LAERTES"}, t = "Fall ten times treble on that cursed head" },
    { r = {"LAERTES"}, t = "Whose wicked deed thy most ingenious sense" },
    { r = {"LAERTES"}, t = "Depriv’d thee of. Hold off the earth a while," },
    { r = {"LAERTES"}, t = "Till I have caught her once more in mine arms." },
    { r = {"LAERTES"}, t = "Now pile your dust upon the quick and dead,", d = "Leaps into the grave" },
    { r = {"LAERTES"}, t = "Till of this flat a mountain you have made," },
    { r = {"LAERTES"}, t = "To o’ertop old Pelion or the skyish head" },
    { r = {"LAERTES"}, t = "Of blue Olympus." },
    { r = {"HAMLET"}, t = "What is he whose grief", d = "Advancing" },
    { r = {"HAMLET"}, t = "Bears such an emphasis? whose phrase of sorrow" },
    { r = {"HAMLET"}, t = "Conjures the wand’ring stars, and makes them stand" },
    { r = {"HAMLET"}, t = "Like wonder-wounded hearers? This is I," },
    { r = {"HAMLET"}, t = "Hamlet the Dane." },
    { d = "Leaps into the grave" },
    { r = {"LAERTES"}, t = "The devil take thy soul!", d = "Grappling with him" },
    { r = {"HAMLET"}, t = "Thou pray’st not well." },
    { r = {"HAMLET"}, t = "I prithee take thy fingers from my throat;" },
    { r = {"HAMLET"}, t = "For though I am not splenative and rash," },
    { r = {"HAMLET"}, t = "Yet have I in me something dangerous," },
    { r = {"HAMLET"}, t = "Which let thy wiseness fear. Away thy hand!" },
    { r = {"CLAUDIUS"}, t = "Pluck them asunder." },
    { r = {"GERTRUDE"}, t = "Hamlet! Hamlet!" },
    { r = {"ALL"}, t = "Gentlemen!" },
    { r = {"HORATIO"}, t = "Good my lord, be quiet." },
    { d = "The Attendants part them, and they come out of the grave" },
    { r = {"HAMLET"}, t = "Why, I will fight with him upon this theme" },
    { r = {"HAMLET"}, t = "Until my eyelids will no longer wag." },
    { r = {"GERTRUDE"}, t = "O my son, what theme?" },
    { r = {"HAMLET"}, t = "I lov’d Ophelia; forty thousand brothers" },
    { r = {"HAMLET"}, t = "Could not, with all their quantity of love," },
    { r = {"HAMLET"}, t = "Make up my sum. What wilt thou do for her?" },
    { r = {"CLAUDIUS"}, t = "O, he is mad, Laertes." },
    { r = {"GERTRUDE"}, t = "For love of God forbear him!" },
    { r = {"HAMLET"}, t = "’Swounds, show me what thou’lt do:" },
    { r = {"HAMLET"}, t = "Woul’t weep? woul’t fight? woul’t fast? woul’t tear thyself?" },
    { r = {"HAMLET"}, t = "Woul’t drink up eisel? eat a crocodile?" },
    { r = {"HAMLET"}, t = "I’ll do’t. Dost thou come here to whine?" },
    { r = {"HAMLET"}, t = "To outface me with leaping in her grave?" },
    { r = {"HAMLET"}, t = "Be buried quick with her, and so will I." },
    { r = {"HAMLET"}, t = "And if thou prate of mountains, let them throw" },
    { r = {"HAMLET"}, t = "Millions of acres on us, till our ground," },
    { r = {"HAMLET"}, t = "Singeing his pate against the burning zone," },
    { r = {"HAMLET"}, t = "Make Ossa like a wart. Nay, an thou’lt mouth," },
    { r = {"HAMLET"}, t = "I’ll rant as well as thou." },
    { r = {"GERTRUDE"}, t = "This is mere madness:" },
    { r = {"GERTRUDE"}, t = "And thus awhile the fit will work on him;" },
    { r = {"GERTRUDE"}, t = "Anon, as patient as the female dove," },
    { r = {"GERTRUDE"}, t = "When that her golden couplets are disclos’d," },
    { r = {"GERTRUDE"}, t = "His silence will sit drooping." },
    { r = {"HAMLET"}, t = "Hear you, sir;" },
    { r = {"HAMLET"}, t = "What is the reason that you use me thus?" },
    { r = {"HAMLET"}, t = "I lov’d you ever. But it is no matter." },
    { r = {"HAMLET"}, t = "Let Hercules himself do what he may," },
    { r = {"HAMLET"}, t = "The cat will mew, and dog will have his day." },
    { d = "Exit" },
    { r = {"CLAUDIUS"}, t = "I pray thee, good Horatio, wait upon him." },
    { d = "Exit Horatio" },
    { r = {"CLAUDIUS"}, t = "Strengthen your patience in our last night’s speech;", d = "To Laertes" },
    { r = {"CLAUDIUS"}, t = "We’ll put the matter to the present push.—" },
    { r = {"CLAUDIUS"}, t = "Good Gertrude, set some watch over your son." },
    { r = {"CLAUDIUS"}, t = "This grave shall have a living monument." },
    { r = {"CLAUDIUS"}, t = "An hour of quiet shortly shall we see;" },
    { r = {"CLAUDIUS"}, t = "Till then in patience our proceeding be." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 2. A hall in the Castle.", h = true },
    { d = "Enter Hamlet and Horatio" },
    { r = {"HAMLET"}, t = "So much for this, sir. Now let me see the other;" },
    { r = {"HAMLET"}, t = "You do remember all the circumstance?" },
    { r = {"HORATIO"}, t = "Remember it, my lord!" },
    { r = {"HAMLET"}, t = "Sir, in my heart there was a kind of fighting" },
    { r = {"HAMLET"}, t = "That would not let me sleep. Methought I lay" },
    { r = {"HAMLET"}, t = "Worse than the mutinies in the bilboes. Rashly," },
    { r = {"HAMLET"}, t = "And prais’d be rashness for it,—let us know," },
    { r = {"HAMLET"}, t = "Our indiscretion sometime serves us well," },
    { r = {"HAMLET"}, t = "When our deep plots do pall; and that should teach us" },
    { r = {"HAMLET"}, t = "There’s a divinity that shapes our ends," },
    { r = {"HAMLET"}, t = "Rough-hew them how we will." },
    { r = {"HORATIO"}, t = "That is most certain." },
    { r = {"HAMLET"}, t = "Up from my cabin," },
    { r = {"HAMLET"}, t = "My sea-gown scarf’d about me, in the dark" },
    { r = {"HAMLET"}, t = "Grop’d I to find out them; had my desire," },
    { r = {"HAMLET"}, t = "Finger’d their packet, and in fine, withdrew" },
    { r = {"HAMLET"}, t = "To mine own room again, making so bold," },
    { r = {"HAMLET"}, t = "My fears forgetting manners, to unseal" },
    { r = {"HAMLET"}, t = "Their grand commission; where I found, Horatio," },
    { r = {"HAMLET"}, t = "Oh royal knavery! an exact command," },
    { r = {"HAMLET"}, t = "Larded with many several sorts of reasons," },
    { r = {"HAMLET"}, t = "Importing Denmark’s health, and England’s too," },
    { r = {"HAMLET"}, t = "With ho! such bugs and goblins in my life," },
    { r = {"HAMLET"}, t = "That on the supervise, no leisure bated," },
    { r = {"HAMLET"}, t = "No, not to stay the grinding of the axe," },
    { r = {"HAMLET"}, t = "My head should be struck off." },
    { r = {"HORATIO"}, t = "Is’t possible?" },
    { r = {"HAMLET"}, t = "Here’s the commission, read it at more leisure." },
    { r = {"HAMLET"}, t = "But wilt thou hear me how I did proceed?" },
    { r = {"HORATIO"}, t = "I beseech you." },
    { r = {"HAMLET"}, t = "Being thus benetted round with villanies,—" },
    { r = {"HAMLET"}, t = "Or I could make a prologue to my brains," },
    { r = {"HAMLET"}, t = "They had begun the play,—I sat me down," },
    { r = {"HAMLET"}, t = "Devis’d a new commission, wrote it fair:" },
    { r = {"HAMLET"}, t = "I once did hold it, as our statists do," },
    { r = {"HAMLET"}, t = "A baseness to write fair, and labour’d much" },
    { r = {"HAMLET"}, t = "How to forget that learning; but, sir, now" },
    { r = {"HAMLET"}, t = "It did me yeoman’s service. Wilt thou know" },
    { r = {"HAMLET"}, t = "The effect of what I wrote?" },
    { r = {"HORATIO"}, t = "Ay, good my lord." },
    { r = {"HAMLET"}, t = "An earnest conjuration from the King," },
    { r = {"HAMLET"}, t = "As England was his faithful tributary," },
    { r = {"HAMLET"}, t = "As love between them like the palm might flourish," },
    { r = {"HAMLET"}, t = "As peace should still her wheaten garland wear" },
    { r = {"HAMLET"}, t = "And stand a comma ’tween their amities," },
    { r = {"HAMLET"}, t = "And many such-like ‘as’es of great charge," },
    { r = {"HAMLET"}, t = "That on the view and know of these contents," },
    { r = {"HAMLET"}, t = "Without debatement further, more or less," },
    { r = {"HAMLET"}, t = "He should the bearers put to sudden death," },
    { r = {"HAMLET"}, t = "Not shriving-time allow’d." },
    { r = {"HORATIO"}, t = "How was this seal’d?" },
    { r = {"HAMLET"}, t = "Why, even in that was heaven ordinant." },
    { r = {"HAMLET"}, t = "I had my father’s signet in my purse," },
    { r = {"HAMLET"}, t = "Which was the model of that Danish seal:" },
    { r = {"HAMLET"}, t = "Folded the writ up in the form of the other," },
    { r = {"HAMLET"}, t = "Subscrib’d it: gave’t th’impression; plac’d it safely," },
    { r = {"HAMLET"}, t = "The changeling never known. Now, the next day" },
    { r = {"HAMLET"}, t = "Was our sea-fight, and what to this was sequent" },
    { r = {"HAMLET"}, t = "Thou know’st already." },
    { r = {"HORATIO"}, t = "So Guildenstern and Rosencrantz go to’t." },
    { r = {"HAMLET"}, t = "Why, man, they did make love to this employment." },
    { r = {"HAMLET"}, t = "They are not near my conscience; their defeat" },
    { r = {"HAMLET"}, t = "Does by their own insinuation grow." },
    { r = {"HAMLET"}, t = "’Tis dangerous when the baser nature comes" },
    { r = {"HAMLET"}, t = "Between the pass and fell incensed points" },
    { r = {"HAMLET"}, t = "Of mighty opposites." },
    { r = {"HORATIO"}, t = "Why, what a king is this!" },
    { r = {"HAMLET"}, t = "Does it not, thinks’t thee, stand me now upon,—" },
    { r = {"HAMLET"}, t = "He that hath kill’d my king, and whor’d my mother," },
    { r = {"HAMLET"}, t = "Popp’d in between th’election and my hopes," },
    { r = {"HAMLET"}, t = "Thrown out his angle for my proper life," },
    { r = {"HAMLET"}, t = "And with such cozenage—is’t not perfect conscience" },
    { r = {"HAMLET"}, t = "To quit him with this arm? And is’t not to be damn’d" },
    { r = {"HAMLET"}, t = "To let this canker of our nature come" },
    { r = {"HAMLET"}, t = "In further evil?" },
    { r = {"HORATIO"}, t = "It must be shortly known to him from England" },
    { r = {"HORATIO"}, t = "What is the issue of the business there." },
    { r = {"HAMLET"}, t = "It will be short. The interim is mine;" },
    { r = {"HAMLET"}, t = "And a man’s life’s no more than to say ‘One’." },
    { r = {"HAMLET"}, t = "But I am very sorry, good Horatio," },
    { r = {"HAMLET"}, t = "That to Laertes I forgot myself;" },
    { r = {"HAMLET"}, t = "For by the image of my cause I see" },
    { r = {"HAMLET"}, t = "The portraiture of his. I’ll court his favours." },
    { r = {"HAMLET"}, t = "But sure the bravery of his grief did put me" },
    { r = {"HAMLET"}, t = "Into a tow’ring passion." },
    { r = {"HORATIO"}, t = "Peace, who comes here?" },
    { d = "Enter Osric" },
    { r = {"OSRIC"}, t = "Your lordship is right welcome back to Denmark." },
    { r = {"HAMLET"}, t = "I humbly thank you, sir. Dost know this waterfly?" },
    { r = {"HORATIO"}, t = "No, my good lord." },
    { r = {"HAMLET"}, t = "Thy state is the more gracious; for ’tis a vice to know him." },
    { r = {"HAMLET"}, t = "He hath much land, and fertile; let a beast be lord of beasts, and his crib shall stand at the king’s mess; ’tis a chough; but, as I say, spacious in the possession of dirt." },
    { r = {"OSRIC"}, t = "Sweet lord, if your lordship were at leisure, I should impart a thing to you from his Majesty." },
    { r = {"HAMLET"}, t = "I will receive it with all diligence of spirit." },
    { r = {"HAMLET"}, t = "Put your bonnet to his right use; ’tis for the head." },
    { r = {"OSRIC"}, t = "I thank your lordship, ’tis very hot." },
    { r = {"HAMLET"}, t = "No, believe me, ’tis very cold, the wind is northerly." },
    { r = {"OSRIC"}, t = "It is indifferent cold, my lord, indeed." },
    { r = {"HAMLET"}, t = "Methinks it is very sultry and hot for my complexion." },
    { r = {"OSRIC"}, t = "Exceedingly, my lord; it is very sultry,—as ’twere—I cannot tell how." },
    { r = {"OSRIC"}, t = "But, my lord, his Majesty bade me signify to you that he has laid a great wager on your head." },
    { r = {"OSRIC"}, t = "Sir, this is the matter," },
    { r = {"HAMLET"}, t = "I beseech you, remember," },
    { d = "Hamlet moves him to put on his hat" },
    { r = {"OSRIC"}, t = "Nay, in good faith; for mine ease, in good faith." },
    { r = {"OSRIC"}, t = "Sir, here is newly come to court Laertes; believe me, an absolute gentleman, full of most excellent differences, of very soft society and great showing." },
    { r = {"OSRIC"}, t = "Indeed, to speak feelingly of him, he is the card or calendar of gentry; for you shall find in him the continent of what part a gentleman would see." },
    { r = {"HAMLET"}, t = "Sir, his definement suffers no perdition in you, though I know, to divide him inventorially would dizzy th’arithmetic of memory, and yet but yaw neither, in respect of his quick sail." },
    { r = {"HAMLET"}, t = "But, in the verity of extolment, I take him to be a soul of great article and his infusion of such dearth and rareness as, to make true diction of him, his semblable is his mirror and who else would trace him his umbrage, nothing more." },
    { r = {"OSRIC"}, t = "Your lordship speaks most infallibly of him." },
    { r = {"HAMLET"}, t = "The concernancy, sir?" },
    { r = {"HAMLET"}, t = "Why do we wrap the gentleman in our more rawer breath?" },
    { r = {"OSRIC"}, t = "Sir?" },
    { r = {"HORATIO"}, t = "Is’t not possible to understand in another tongue?" },
    { r = {"HORATIO"}, t = "You will do’t, sir, really." },
    { r = {"HAMLET"}, t = "What imports the nomination of this gentleman?" },
    { r = {"OSRIC"}, t = "Of Laertes?" },
    { r = {"HORATIO"}, t = "His purse is empty already, all’s golden words are spent." },
    { r = {"HAMLET"}, t = "Of him, sir." },
    { r = {"OSRIC"}, t = "I know you are not ignorant," },
    { r = {"HAMLET"}, t = "I would you did, sir; yet in faith if you did, it would not much approve me." },
    { r = {"HAMLET"}, t = "Well, sir?" },
    { r = {"OSRIC"}, t = "You are not ignorant of what excellence Laertes is," },
    { r = {"HAMLET"}, t = "I dare not confess that, lest I should compare with him in excellence; but to know a man well were to know himself." },
    { r = {"OSRIC"}, t = "I mean, sir, for his weapon; but in the imputation laid on him, by them in his meed he’s unfellowed." },
    { r = {"HAMLET"}, t = "What’s his weapon?" },
    { r = {"OSRIC"}, t = "Rapier and dagger." },
    { r = {"HAMLET"}, t = "That’s two of his weapons. But well." },
    { r = {"OSRIC"}, t = "The King, sir, hath wager’d with him six Barbary horses, against the which he has imponed, as I take it, six French rapiers and poniards, with their assigns, as girdle, hangers, and so." },
    { r = {"OSRIC"}, t = "Three of the carriages, in faith, are very dear to fancy, very responsive to the hilts, most delicate carriages, and of very liberal conceit." },
    { r = {"HAMLET"}, t = "What call you the carriages?" },
    { r = {"HORATIO"}, t = "I knew you must be edified by the margin ere you had done." },
    { r = {"OSRIC"}, t = "The carriages, sir, are the hangers." },
    { r = {"HAMLET"}, t = "The phrase would be more german to the matter if we could carry cannon by our sides." },
    { r = {"HAMLET"}, t = "I would it might be hangers till then." },
    { r = {"HAMLET"}, t = "But on." },
    { r = {"HAMLET"}, t = "Six Barbary horses against six French swords, their assigns, and three liberal conceited carriages: that’s the French bet against the Danish." },
    { r = {"HAMLET"}, t = "Why is this all imponed, as you call it?" },
    { r = {"OSRIC"}, t = "The King, sir, hath laid that in a dozen passes between you and him, he shall not exceed you three hits." },
    { r = {"OSRIC"}, t = "He hath laid on twelve for nine." },
    { r = {"OSRIC"}, t = "And it would come to immediate trial if your lordship would vouchsafe the answer." },
    { r = {"HAMLET"}, t = "How if I answer no?" },
    { r = {"OSRIC"}, t = "I mean, my lord, the opposition of your person in trial." },
    { r = {"HAMLET"}, t = "Sir, I will walk here in the hall." },
    { r = {"HAMLET"}, t = "If it please his Majesty, it is the breathing time of day with me." },
    { r = {"HAMLET"}, t = "Let the foils be brought, the gentleman willing, and the King hold his purpose, I will win for him if I can; if not, I will gain nothing but my shame and the odd hits." },
    { r = {"OSRIC"}, t = "Shall I re-deliver you e’en so?" },
    { r = {"HAMLET"}, t = "To this effect, sir; after what flourish your nature will." },
    { r = {"OSRIC"}, t = "I commend my duty to your lordship." },
    { r = {"HAMLET"}, t = "Yours, yours." },
    { d = "Exit Osric" },
    { r = {"HAMLET"}, t = "He does well to commend it himself, there are no tongues else for’s turn." },
    { r = {"HORATIO"}, t = "This lapwing runs away with the shell on his head." },
    { r = {"HAMLET"}, t = "He did comply with his dug before he suck’d it." },
    { r = {"HAMLET"}, t = "Thus has he,— and many more of the same bevy that I know the drossy age dotes on,— only got the tune of the time and outward habit of encounter;" },
    { r = {"HAMLET"}, t = "a kind of yeasty collection, which carries them through and through the most fanned and winnowed opinions; and do but blow them to their trial, the bubbles are out." },
    { d = "Enter a Lord" },
    { r = {"LORD"}, t = "My lord, his Majesty commended him to you by young Osric, who brings back to him that you attend him in the hall." },
    { r = {"LORD"}, t = "He sends to know if your pleasure hold to play with Laertes or that you will take longer time." },
    { r = {"HAMLET"}, t = "I am constant to my purposes, they follow the King’s pleasure." },
    { r = {"HAMLET"}, t = "If his fitness speaks, mine is ready." },
    { r = {"HAMLET"}, t = "Now or whensoever, provided I be so able as now." },
    { r = {"LORD"}, t = "The King and Queen and all are coming down." },
    { r = {"HAMLET"}, t = "In happy time." },
    { r = {"LORD"}, t = "The Queen desires you to use some gentle entertainment to Laertes before you fall to play." },
    { r = {"HAMLET"}, t = "She well instructs me." },
    { d = "Exit Lord" },
    { r = {"HORATIO"}, t = "You will lose this wager, my lord." },
    { r = {"HAMLET"}, t = "I do not think so." },
    { r = {"HAMLET"}, t = "Since he went into France, I have been in continual practice." },
    { r = {"HAMLET"}, t = "I shall win at the odds." },
    { r = {"HAMLET"}, t = "But thou wouldst not think how ill all’s here about my heart: but it is no matter." },
    { r = {"HORATIO"}, t = "Nay, good my lord." },
    { r = {"HAMLET"}, t = "It is but foolery; but it is such a kind of gain-giving as would perhaps trouble a woman." },
    { r = {"HORATIO"}, t = "If your mind dislike anything, obey it." },
    { r = {"HORATIO"}, t = "I will forestall their repair hither, and say you are not fit." },
    { r = {"HAMLET"}, t = "Not a whit, we defy augury." },
    { r = {"HAMLET"}, t = "There’s a special providence in the fall of a sparrow." },
    { r = {"HAMLET"}, t = "If it be now, ’tis not to come; if it be not to come, it will be now; if it be not now, yet it will come." },
    { r = {"HAMLET"}, t = "The readiness is all." },
    { r = {"HAMLET"}, t = "Since no man has aught of what he leaves, what is’t to leave betimes?" },
    { d = "Enter King, Queen, Laertes, Lords, Osric and Attendants with foils &c" },
    { r = {"CLAUDIUS"}, t = "Come, Hamlet, come, and take this hand from me." },
    { d = "The King puts Laertes’s hand into Hamlet’s" },
    { r = {"HAMLET"}, t = "Give me your pardon, sir. I have done you wrong;" },
    { r = {"HAMLET"}, t = "But pardon’t as you are a gentleman." },
    { r = {"HAMLET"}, t = "This presence knows, and you must needs have heard," },
    { r = {"HAMLET"}, t = "How I am punish’d with sore distraction." },
    { r = {"HAMLET"}, t = "What I have done" },
    { r = {"HAMLET"}, t = "That might your nature, honour, and exception" },
    { r = {"HAMLET"}, t = "Roughly awake, I here proclaim was madness." },
    { r = {"HAMLET"}, t = "Was’t Hamlet wrong’d Laertes? Never Hamlet." },
    { r = {"HAMLET"}, t = "If Hamlet from himself be ta’en away," },
    { r = {"HAMLET"}, t = "And when he’s not himself does wrong Laertes," },
    { r = {"HAMLET"}, t = "Then Hamlet does it not, Hamlet denies it." },
    { r = {"HAMLET"}, t = "Who does it, then? His madness. If’t be so," },
    { r = {"HAMLET"}, t = "Hamlet is of the faction that is wrong’d;" },
    { r = {"HAMLET"}, t = "His madness is poor Hamlet’s enemy." },
    { r = {"HAMLET"}, t = "Sir, in this audience," },
    { r = {"HAMLET"}, t = "Let my disclaiming from a purpos’d evil" },
    { r = {"HAMLET"}, t = "Free me so far in your most generous thoughts" },
    { r = {"HAMLET"}, t = "That I have shot my arrow o’er the house" },
    { r = {"HAMLET"}, t = "And hurt my brother." },
    { r = {"LAERTES"}, t = "I am satisfied in nature," },
    { r = {"LAERTES"}, t = "Whose motive in this case should stir me most" },
    { r = {"LAERTES"}, t = "To my revenge. But in my terms of honour" },
    { r = {"LAERTES"}, t = "I stand aloof, and will no reconcilement" },
    { r = {"LAERTES"}, t = "Till by some elder masters of known honour" },
    { r = {"LAERTES"}, t = "I have a voice and precedent of peace" },
    { r = {"LAERTES"}, t = "To keep my name ungor’d. But till that time" },
    { r = {"LAERTES"}, t = "I do receive your offer’d love like love," },
    { r = {"LAERTES"}, t = "And will not wrong it." },
    { r = {"HAMLET"}, t = "I embrace it freely," },
    { r = {"HAMLET"}, t = "And will this brother’s wager frankly play.—" },
    { r = {"HAMLET"}, t = "Give us the foils; come on." },
    { r = {"LAERTES"}, t = "Come, one for me." },
    { r = {"HAMLET"}, t = "I’ll be your foil, Laertes; in mine ignorance" },
    { r = {"HAMLET"}, t = "Your skill shall like a star i’ th’ darkest night," },
    { r = {"HAMLET"}, t = "Stick fiery off indeed." },
    { r = {"LAERTES"}, t = "You mock me, sir." },
    { r = {"HAMLET"}, t = "No, by this hand." },
    { r = {"CLAUDIUS"}, t = "Give them the foils, young Osric. Cousin Hamlet," },
    { r = {"CLAUDIUS"}, t = "You know the wager?" },
    { r = {"HAMLET"}, t = "Very well, my lord." },
    { r = {"HAMLET"}, t = "Your Grace has laid the odds o’ the weaker side." },
    { r = {"CLAUDIUS"}, t = "I do not fear it. I have seen you both;" },
    { r = {"CLAUDIUS"}, t = "But since he is better’d, we have therefore odds." },
    { r = {"LAERTES"}, t = "This is too heavy. Let me see another." },
    { r = {"HAMLET"}, t = "This likes me well. These foils have all a length?" },
    { d = "They prepare to play" },
    { r = {"OSRIC"}, t = "Ay, my good lord." },
    { r = {"CLAUDIUS"}, t = "Set me the stoups of wine upon that table." },
    { r = {"CLAUDIUS"}, t = "If Hamlet give the first or second hit," },
    { r = {"CLAUDIUS"}, t = "Or quit in answer of the third exchange," },
    { r = {"CLAUDIUS"}, t = "Let all the battlements their ordnance fire;" },
    { r = {"CLAUDIUS"}, t = "The King shall drink to Hamlet’s better breath," },
    { r = {"CLAUDIUS"}, t = "And in the cup an union shall he throw" },
    { r = {"CLAUDIUS"}, t = "Richer than that which four successive kings" },
    { r = {"CLAUDIUS"}, t = "In Denmark’s crown have worn. Give me the cups;" },
    { r = {"CLAUDIUS"}, t = "And let the kettle to the trumpet speak," },
    { r = {"CLAUDIUS"}, t = "The trumpet to the cannoneer without," },
    { r = {"CLAUDIUS"}, t = "The cannons to the heavens, the heavens to earth," },
    { r = {"CLAUDIUS"}, t = "‘Now the King drinks to Hamlet.’ Come, begin." },
    { r = {"CLAUDIUS"}, t = "And you, the judges, bear a wary eye." },
    { r = {"HAMLET"}, t = "Come on, sir." },
    { r = {"LAERTES"}, t = "Come, my lord." },
    { d = "They play" },
    { r = {"HAMLET"}, t = "One." },
    { r = {"LAERTES"}, t = "No." },
    { r = {"HAMLET"}, t = "Judgement." },
    { r = {"OSRIC"}, t = "A hit, a very palpable hit." },
    { r = {"LAERTES"}, t = "Well; again." },
    { r = {"CLAUDIUS"}, t = "Stay, give me drink. Hamlet, this pearl is thine;" },
    { r = {"CLAUDIUS"}, t = "Here’s to thy health." },
    { d = "Trumpets sound, and cannon shot off within" },
    { r = {"CLAUDIUS"}, t = "Give him the cup." },
    { r = {"HAMLET"}, t = "I’ll play this bout first; set it by awhile." },
    { d = "They play" },
    { r = {"HAMLET"}, t = "Come. Another hit; what say you?" },
    { r = {"LAERTES"}, t = "A touch, a touch, I do confess." },
    { r = {"CLAUDIUS"}, t = "Our son shall win." },
    { r = {"GERTRUDE"}, t = "He’s fat, and scant of breath." },
    { r = {"GERTRUDE"}, t = "Here, Hamlet, take my napkin, rub thy brows." },
    { r = {"GERTRUDE"}, t = "The Queen carouses to thy fortune, Hamlet.", u = {"Bottle of Pinot Noir", "Flask of Port", "Rhapsody Malt", "Thunder Ale", "Refreshing Spring Water"} },
    { r = {"HAMLET"}, t = "Good madam." },
    { r = {"CLAUDIUS"}, t = "Gertrude, do not drink." },
    { r = {"GERTRUDE"}, t = "I will, my lord; I pray you pardon me." },
    { r = {"CLAUDIUS"}, t = "It is the poison’d cup; it is too late.", d = "Aside" },
    { r = {"HAMLET"}, t = "I dare not drink yet, madam. By and by." },
    { r = {"GERTRUDE"}, t = "Come, let me wipe thy face." },
    { r = {"LAERTES"}, t = "My lord, I’ll hit him now." },
    { r = {"CLAUDIUS"}, t = "I do not think’t." },
    { r = {"LAERTES"}, t = "And yet ’tis almost ’gainst my conscience.", d = "Aside" },
    { r = {"HAMLET"}, t = "Come for the third, Laertes. You do but dally." },
    { r = {"HAMLET"}, t = "I pray you pass with your best violence." },
    { r = {"HAMLET"}, t = "I am afeard you make a wanton of me." },
    { r = {"LAERTES"}, t = "Say you so? Come on." },
    { d = "They play" },
    { r = {"OSRIC"}, t = "Nothing neither way." },
    { r = {"LAERTES"}, t = "Have at you now." },
    { d = "Laertes wounds Hamlet; then, in scuffling, they change rapiers, and Hamlet wounds Laertes" },
    { r = {"CLAUDIUS"}, t = "Part them; they are incens’d." },
    { r = {"HAMLET"}, t = "Nay, come again!" },
    { d = "The Queen falls" },
    { r = {"OSRIC"}, t = "Look to the Queen there, ho!" },
    { r = {"HORATIO"}, t = "They bleed on both sides. How is it, my lord?" },
    { r = {"OSRIC"}, t = "How is’t, Laertes?" },
    { r = {"LAERTES"}, t = "Why, as a woodcock to my own springe, Osric." },
    { r = {"LAERTES"}, t = "I am justly kill’d with mine own treachery." },
    { r = {"HAMLET"}, t = "How does the Queen?" },
    { r = {"CLAUDIUS"}, t = "She swoons to see them bleed." },
    { r = {"GERTRUDE"}, t = "No, no, the drink, the drink! O my dear Hamlet!" },
    { r = {"GERTRUDE"}, t = "The drink, the drink! I am poison’d." },
    { r = {"GERTRUDE"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { r = {"HAMLET"}, t = "O villany! Ho! Let the door be lock’d:" },
    { r = {"HAMLET"}, t = "Treachery! Seek it out." },
    { d = "Laertes falls" },
    { r = {"LAERTES"}, t = "It is here, Hamlet. Hamlet, thou art slain." },
    { r = {"LAERTES"}, t = "No medicine in the world can do thee good." },
    { r = {"LAERTES"}, t = "In thee there is not half an hour of life;" },
    { r = {"LAERTES"}, t = "The treacherous instrument is in thy hand," },
    { r = {"LAERTES"}, t = "Unbated and envenom’d. The foul practice" },
    { r = {"LAERTES"}, t = "Hath turn’d itself on me. Lo, here I lie," },
    { r = {"LAERTES"}, t = "Never to rise again. Thy mother’s poison’d." },
    { r = {"LAERTES"}, t = "I can no more. The King, the King’s to blame." },
    { r = {"HAMLET"}, t = "The point envenom’d too!" },
    { r = {"HAMLET"}, t = "Then, venom, to thy work." },
    { d = "Stabs the King" },
    { r = {"HAMLET"}, t = "OSRIC and LORDS." },
    { r = {"HAMLET"}, t = "Treason! treason!" },
    { r = {"CLAUDIUS"}, t = "O yet defend me, friends. I am but hurt." },
    { r = {"HAMLET"}, t = "Here, thou incestuous, murderous, damned Dane," },
    { r = {"HAMLET"}, t = "Drink off this potion. Is thy union here?" },
    { r = {"HAMLET"}, t = "Follow my mother." },
    { r = {"CLAUDIUS"}, d = "King dies", e = "/lie", s = {"Feign Death"} },
    { r = {"LAERTES"}, t = "He is justly serv’d." },
    { r = {"LAERTES"}, t = "It is a poison temper’d by himself." },
    { r = {"LAERTES"}, t = "Exchange forgiveness with me, noble Hamlet." },
    { r = {"LAERTES"}, t = "Mine and my father’s death come not upon thee," },
    { r = {"LAERTES"}, t = "Nor thine on me." },
    { r = {"LAERTES"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { r = {"HAMLET"}, t = "Heaven make thee free of it! I follow thee." },
    { r = {"HAMLET"}, t = "I am dead, Horatio. Wretched Queen, adieu." },
    { r = {"HAMLET"}, t = "You that look pale and tremble at this chance," },
    { r = {"HAMLET"}, t = "That are but mutes or audience to this act," },
    { r = {"HAMLET"}, t = "Had I but time,—as this fell sergeant, death," },
    { r = {"HAMLET"}, t = "Is strict in his arrest,—O, I could tell you,—" },
    { r = {"HAMLET"}, t = "But let it be. Horatio, I am dead," },
    { r = {"HAMLET"}, t = "Thou liv’st; report me and my cause aright" },
    { r = {"HAMLET"}, t = "To the unsatisfied." },
    { r = {"HORATIO"}, t = "Never believe it." },
    { r = {"HORATIO"}, t = "I am more an antique Roman than a Dane." },
    { r = {"HORATIO"}, t = "Here’s yet some liquor left." },
    { r = {"HAMLET"}, t = "As th’art a man," },
    { r = {"HAMLET"}, t = "Give me the cup. Let go; by Heaven, I’ll have’t." },
    { r = {"HAMLET"}, t = "O good Horatio, what a wounded name," },
    { r = {"HAMLET"}, t = "Things standing thus unknown, shall live behind me." },
    { r = {"HAMLET"}, t = "If thou didst ever hold me in thy heart," },
    { r = {"HAMLET"}, t = "Absent thee from felicity awhile," },
    { r = {"HAMLET"}, t = "And in this harsh world draw thy breath in pain," },
    { r = {"HAMLET"}, t = "To tell my story." },
    { d = "March afar off, and shot within" },
    { r = {"HAMLET"}, t = "What warlike noise is this?" },
    { r = {"OSRIC"}, t = "Young Fortinbras, with conquest come from Poland," },
    { r = {"OSRIC"}, t = "To the ambassadors of England gives" },
    { r = {"OSRIC"}, t = "This warlike volley." },
    { r = {"HAMLET"}, t = "O, I die, Horatio." },
    { r = {"HAMLET"}, t = "The potent poison quite o’er-crows my spirit:" },
    { r = {"HAMLET"}, t = "I cannot live to hear the news from England," },
    { r = {"HAMLET"}, t = "But I do prophesy th’election lights" },
    { r = {"HAMLET"}, t = "On Fortinbras. He has my dying voice." },
    { r = {"HAMLET"}, t = "So tell him, with the occurrents more and less," },
    { r = {"HAMLET"}, t = "Which have solicited. The rest is silence." },
    { r = {"HAMLET"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { r = {"HORATIO"}, t = "Now cracks a noble heart. Good night, sweet prince," },
    { r = {"HORATIO"}, t = "And flights of angels sing thee to thy rest." },
    { r = {"HORATIO"}, t = "Why does the drum come hither?" },
    { d = "March within" },
    { d = "Enter Fortinbras, the English Ambassadors and others" },
    { r = {"FORTINBRAS"}, t = "Where is this sight?" },
    { r = {"HORATIO"}, t = "What is it you would see?" },
    { r = {"HORATIO"}, t = "If aught of woe or wonder, cease your search." },
    { r = {"FORTINBRAS"}, t = "This quarry cries on havoc. O proud death," },
    { r = {"FORTINBRAS"}, t = "What feast is toward in thine eternal cell," },
    { r = {"FORTINBRAS"}, t = "That thou so many princes at a shot" },
    { r = {"FORTINBRAS"}, t = "So bloodily hast struck?" },
    { r = {"FIRST AMBASSADOR"}, t = "The sight is dismal;" },
    { r = {"FIRST AMBASSADOR"}, t = "And our affairs from England come too late." },
    { r = {"FIRST AMBASSADOR"}, t = "The ears are senseless that should give us hearing," },
    { r = {"FIRST AMBASSADOR"}, t = "To tell him his commandment is fulfill’d," },
    { r = {"FIRST AMBASSADOR"}, t = "That Rosencrantz and Guildenstern are dead." },
    { r = {"FIRST AMBASSADOR"}, t = "Where should we have our thanks?" },
    { r = {"HORATIO"}, t = "Not from his mouth," },
    { r = {"HORATIO"}, t = "Had it th’ability of life to thank you." },
    { r = {"HORATIO"}, t = "He never gave commandment for their death." },
    { r = {"HORATIO"}, t = "But since, so jump upon this bloody question," },
    { r = {"HORATIO"}, t = "You from the Polack wars, and you from England" },
    { r = {"HORATIO"}, t = "Are here arriv’d, give order that these bodies" },
    { r = {"HORATIO"}, t = "High on a stage be placed to the view," },
    { r = {"HORATIO"}, t = "And let me speak to th’ yet unknowing world" },
    { r = {"HORATIO"}, t = "How these things came about. So shall you hear" },
    { r = {"HORATIO"}, t = "Of carnal, bloody and unnatural acts," },
    { r = {"HORATIO"}, t = "Of accidental judgements, casual slaughters," },
    { r = {"HORATIO"}, t = "Of deaths put on by cunning and forc’d cause," },
    { r = {"HORATIO"}, t = "And, in this upshot, purposes mistook" },
    { r = {"HORATIO"}, t = "Fall’n on the inventors’ heads. All this can I" },
    { r = {"HORATIO"}, t = "Truly deliver." },
    { r = {"FORTINBRAS"}, t = "Let us haste to hear it," },
    { r = {"FORTINBRAS"}, t = "And call the noblest to the audience." },
    { r = {"FORTINBRAS"}, t = "For me, with sorrow I embrace my fortune." },
    { r = {"FORTINBRAS"}, t = "I have some rights of memory in this kingdom," },
    { r = {"FORTINBRAS"}, t = "Which now to claim my vantage doth invite me." },
    { r = {"HORATIO"}, t = "Of that I shall have also cause to speak," },
    { r = {"HORATIO"}, t = "And from his mouth whose voice will draw on more." },
    { r = {"HORATIO"}, t = "But let this same be presently perform’d," },
    { r = {"HORATIO"}, t = "Even while men’s minds are wild, lest more mischance" },
    { r = {"HORATIO"}, t = "On plots and errors happen." },
    { r = {"FORTINBRAS"}, t = "Let four captains" },
    { r = {"FORTINBRAS"}, t = "Bear Hamlet like a soldier to the stage," },
    { r = {"FORTINBRAS"}, t = "For he was likely, had he been put on," },
    { r = {"FORTINBRAS"}, t = "To have prov’d most royally; and for his passage," },
    { r = {"FORTINBRAS"}, t = "The soldiers’ music and the rites of war" },
    { r = {"FORTINBRAS"}, t = "Speak loudly for him." },
    { r = {"FORTINBRAS"}, t = "Take up the bodies. Such a sight as this" },
    { r = {"FORTINBRAS"}, t = "Becomes the field, but here shows much amiss." },
    { r = {"FORTINBRAS"}, t = "Go, bid the soldiers shoot." },
    { d = "A dead march" },
    { d = "Exeunt, bearing off the bodies, after which a peal of ordnance is shot off" },
  },
}
